-- Easy Professions (Forever): guide texts in esES (translated from wow-professions.com/forever)
local _, ns = ...
ns.AddTranslation("esES", {
  ["This WoW Forever Alchemy leveling guide will show you the fastest and cheapest way to level your Alchemy skill from 1 to 300. You will also find every trainer location and where to train Alchemy past 75, 150 and 225."] = "Esta guía de Alquimia para WoW Forever te mostrará la forma más rápida y barata de subir tu habilidad de Alquimia de 1 a 300. También encontrarás la ubicación de todos los instructores y dónde aprender Alquimia más allá de 75, 150 y 225.",
  ["Below you will find the full shopping list, the Alchemy trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Alchemy is best combined with Herbalism, with these two you can save a lot of gold because you don't have to buy the herbs from the Auction House."] = "A continuación encontrarás la lista de la compra completa, los instructores de Alquimia por zona inicial y capital, y las recetas más baratas para cada rango de habilidad, de Aprendiz a Artesano. La Alquimia combina mejor con Herboristería: con estas dos puedes ahorrar mucho oro porque no tienes que comprar las hierbas en la casa de subastas.",
  ["This is based on the Forever beta. Leveling takes a long time, so testing the higher levels on live will take a while. If you find something that's off, send me feedback."] = "Esto se basa en la beta de Forever. Subir de nivel lleva mucho tiempo, así que probar los niveles altos en el servidor real llevará un tiempo. Si encuentras algo que no cuadra, envíame tus comentarios.",
  ["Shopping List"] = "Lista de la compra",
  ["These numbers are estimates. Once a recipe turns yellow you won't get a skill point from every craft, so you might need a few more or a few less."] = "Estas cifras son estimaciones. Cuando una receta se vuelve amarilla ya no obtendrás un punto de habilidad con cada creación, así que puede que necesites algunos más o algunos menos.",
  ["Alchemy Trainer Locations"] = "Ubicación de los instructores de Alquimia",
  ["Apprentice Alchemy has no level requirement in Forever, so you can learn it on a fresh character."] = "Alquimia de Aprendiz no tiene requisito de nivel en Forever, así que puedes aprenderla con un personaje recién creado.",
  ["Every capital city has a trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "Todas las capitales tienen un instructor. También puedes preguntar a un guardia y quedará marcado con una bandera roja en tu mapa.",
  ["Horde"] = "Horda",
  ["Alliance"] = "Alianza",
  ["Capital Cities"] = "Capitales",
  ["Undercity: {n:0:horde:Doctor Martin Felben}"] = "Entrañas: {n:0:horde:Doctor Martin Felben}",
  ["Thunder Bluff: {n:0:horde:Kray}"] = "Cima del Trueno: {n:0:horde:Kray}",
  ["Starting Zones"] = "Zonas iniciales",
  ["Not every zone has a trainer, the table shows the closest one for each race."] = "No todas las zonas tienen instructor; la tabla muestra el más cercano para cada raza.",
  ["Race"] = "Raza",
  ["Zone"] = "Zona",
  ["Closest trainer"] = "Instructor más cercano",
  ["Orc, Troll"] = "Orco, Trol",
  ["{n:0:horde:Miao'zan} in Sen'jin Village"] = "{n:0:horde:Miao'zan} en la Aldea Sen'jin",
  ["There is no Alchemy trainer in Mulgore, go to {n:0:horde:Kray} on the middle rise in Thunder Bluff"] = "No hay instructor de Alquimia en Mulgore, ve a ver a {n:0:horde:Kray} en la meseta central de Cima del Trueno",
  ["Undead"] = "No-muerto",
  ["Tirisfal Glades"] = "Claros de Tirisfal",
  ["{n:0:horde:Carolai Anise} in the small house at the north-west end of Brill"] = "{n:0:horde:Carolai Anise} en la casita del extremo noroeste de Rémol",
  ["Zephras Isle"] = "Isla Zephras",
  ["{n:0::Iaadaria Bitterwind} or {n:0::Valiena Swiftgale} in Valanaar, {n:0::Nyassa Swiftdraught} in Shen'dar Village"] = "{n:0::Iaadaria Bitterwind} o {n:0::Valiena Swiftgale} en Valanaar, {n:0::Nyassa Swiftdraught} en la Aldea Shen'dar",
  ["Stormwind City: {n:0:alliance:Tel'Athir}"] = "Ventormenta: {n:0:alliance:Tel'Athir}",
  ["Ironforge: {n:0:alliance:Vosur Brakthel}"] = "Forjaz: {n:0:alliance:Vosur Brakthel}",
  ["Human"] = "Humano",
  ["Elwynn Forest"] = "Bosque de Elwynn",
  ["{n:0:alliance:Alchemist Mallory} in a cottage in the hills between Stormwind and Northshire"] = "{n:0:alliance:Alchemist Mallory} en una cabaña en las colinas entre Ventormenta y Villanorte",
  ["Dwarf, Gnome"] = "Enano, Gnomo",
  ["There is no Alchemy trainer in Dun Morogh, go to {n:0:alliance:Vosur Brakthel} in Tinker Town in Ironforge"] = "No hay instructor de Alquimia en Dun Morogh, ve a ver a {n:0:alliance:Vosur Brakthel} en Ciudad Manitas, en Forjaz",
  ["Night Elf"] = "Elfo de la noche",
  ["{n:0:alliance:Cyndra Kindwhisper} in a small house east of the inn in Dolanaar"] = "{n:0:alliance:Cyndra Kindwhisper} en una casita al este de la posada de Dolanaar",
  ["You can find every Alchemy trainer for Horde and Alliance on my WoW Forever Alchemy Trainers page."] = "Puedes encontrar todos los instructores de Alquimia de la Horda y la Alianza en mi página de instructores de Alquimia de WoW Forever.",
  ["Apprentice Alchemy (1-55)"] = "Alquimia de Aprendiz (1-55)",
  ["9x {s:1245250:inv_potion_77:Elixir of Minor Force} - 9 Silverleaf, 9 Empty Vial"] = "9x {s:1245250:inv_potion_77:Elixir of Minor Force} - 9 Hojaplata, 9 Vial vacío",
  ["The vials are sold by Alchemy Supply and Trade Supply vendors, most trainers have one nearby. In Undercity the closest one is {n:0:horde:Algernon}, in Dolanaar it's {n:0:alliance:Narret Shadowgrove}."] = "Los viales los venden los vendedores de suministros de alquimia y de suministros de comercio; la mayoría de los instructores tienen uno cerca. En Entrañas el más cercano es {n:0:horde:Algernon}, en Dolanaar es {n:0:alliance:Narret Shadowgrove}.",
  ["45x {s:7183:inv_potion_63:Elixir of Minor Defense} - 45 Silverleaf, 45 Peacebloom, 45 Empty Vial"] = "45x {s:7183:inv_potion_63:Elixir of Minor Defense} - 45 Hojaplata, 45 Flor de paz, 45 Vial vacío",
  ["Journeyman Alchemy (55-150)"] = "Alquimia de Oficial (55-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Alchemy. You need {b}Alchemy 50{/b} and {b}level 10{/b}:"] = "Para entrenar más allá de 75, visita a uno de estos instructores y aprende Alquimia de Oficial. Necesitas {b}Alquimia 50{/b} y {b}nivel 10{/b}:",
  ["{b}Horde trainers:{/b}"] = "{b}Instructores de la Horda:{/b}",
  ["Undercity: {n:0:horde:Doctor Marsh}"] = "Entrañas: {n:0:horde:Doctor Marsh}",
  ["Thunder Bluff: {n:0:horde:Bena Winterhoof}"] = "Cima del Trueno: {n:0:horde:Bena Winterhoof}",
  ["{b}Alliance trainers:{/b}"] = "{b}Instructores de la Alianza:{/b}",
  ["Stormwind City: {n:0:alliance:Lilyssia Nightbreeze}"] = "Ventormenta: {n:0:alliance:Lilyssia Nightbreeze}",
  ["Ironforge: {n:0:alliance:Tally Berryfizz}"] = "Forjaz: {n:0:alliance:Tally Berryfizz}",
  ["10x {s:2331:inv_potion_70:Minor Mana Potion} - 10 Mageroyal, 10 Peacebloom, 10 Empty Vial"] = "10x {s:2331:inv_potion_70:Minor Mana Potion} - 10 Marregal, 10 Flor de paz, 10 Vial vacío",
  ["28x {s:2334:inv_potion_42:Elixir of Minor Fortitude} - 56 Earthroot, 28 Peacebloom, 28 Empty Vial"] = "28x {s:2334:inv_potion_42:Elixir of Minor Fortitude} - 56 Raíz de tierra, 28 Flor de paz, 28 Vial vacío",
  ["30x {s:3171:inv_potion_06:Elixir of Wisdom} - 30 Mageroyal, 60 Briarthorn, 30 Empty Vial"] = "30x {s:3171:inv_potion_06:Elixir of Wisdom} - 30 Marregal, 60 Brezospina, 30 Vial vacío",
  ["Keep the elixirs if you also level Tailoring, you will need them for the Gloves of Meditation."] = "Guarda los elixires si también subes Sastrería, los necesitarás para los Guantes de meditación.",
  ["10x {s:3173:inv_potion_71:Lesser Mana Potion} - 10 Mageroyal, 10 Stranglekelp, 10 Empty Vial"] = "10x {s:3173:inv_potion_71:Lesser Mana Potion} - 10 Marregal, 10 Alga estranguladora, 10 Vial vacío",
  ["20x {s:7837:inv_potion_38:Fire Oil} - 40 Firefin Snapper, 20 Empty Vial"] = "20x {s:7837:inv_potion_38:Fire Oil} - 40 Pargo aleta de fuego, 20 Vial vacío",
  ["You get 2 oils from every craft. Keep 30 of them, you will need them for the Elixir of Fire Power in the next part."] = "Obtienes 2 aceites con cada creación. Guarda 30, los necesitarás para el Elixir de poder de fuego en la siguiente parte.",
  ["Expert Alchemy (150-225)"] = "Alquimia de Experto (150-225)",
  ["To train past 150, visit {n:0:horde:Doctor Herbert Halsey} in Undercity (Horde) or {n:0:alliance:Ainethil} in Darnassus (Alliance) and learn Expert Alchemy. You need {b}Alchemy 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Para entrenar más allá de 150, visita a {n:0:horde:Doctor Herbert Halsey} en Entrañas (Horda) o a {n:0:alliance:Ainethil} en Darnassus (Alianza) y aprende Alquimia de Experto. Necesitas {b}Alquimia 125{/b} y {b}nivel 20{/b}, y cuesta 50 de plata.",
  ["15x {s:7845:inv_potion_55:Elixir of Fire Power} - 30 Fire Oil, 15 Kingsblood, 15 Leaded Vial"] = "15x {s:7845:inv_potion_55:Elixir of Fire Power} - 30 Aceite de fuego, 15 Sangrerregia, 15 Vial emplomado",
  ["These are the Fire Oils you kept."] = "Estos son los Aceites de fuego que guardaste.",
  ["36x {s:3452:inv_potion_72:Mana Potion} - 36 Stranglekelp, 36 Kingsblood, 36 Leaded Vial"] = "36x {s:3452:inv_potion_72:Mana Potion} - 36 Alga estranguladora, 36 Sangrerregia, 36 Vial emplomado",
  ["36x {s:7259:inv_potion_06:Nature Protection Potion} - 36 Liferoot, 36 Stranglekelp, 36 Leaded Vial"] = "36x {s:7259:inv_potion_06:Nature Protection Potion} - 36 Vidarraíz, 36 Alga estranguladora, 36 Vial emplomado",
  ["{i:6057:inv_scroll_03:Recipe: Nature Protection Potion} is sold by these vendors, it's bind on pickup, so buy it with the character that levels Alchemy:"] = "{i:6057:inv_scroll_03:Recipe: Nature Protection Potion} lo venden estos vendedores; se liga al recogerlo, así que cómpralo con el personaje que sube Alquimia:",
  ["{n:0:horde:Bronk} in Feralas"] = "{n:0:horde:Bronk} en Feralas",
  ["{n:0:alliance:Logannas} in Feralas"] = "{n:0:alliance:Logannas} en Feralas",
  ["{n:0::Glyx Brewright} in Stranglethorn Vale"] = "{n:0::Glyx Brewright} en la Vega de Tuercespina",
  ["{n:0::Alchemist Pestlezugg} in Tanaris"] = "{n:0::Alchemist Pestlezugg} en Tanaris",
  ["Artisan Alchemy (225-300)"] = "Alquimia de Artesano (225-300)",
  ["To train past 225, visit {n:0:horde:Rogvar} in Stonard, Swamp of Sorrows (Horde) or {n:0:alliance:Kylanna Windwhisper} in Feathermoon Stronghold, Feralas (Alliance) and learn Artisan Alchemy. You need {b}Alchemy 200{/b} and {b}level 35{/b}."] = "Para entrenar más allá de 225, visita a {n:0:horde:Rogvar} en Rocal, Pantano de las Penas (Horda) o a {n:0:alliance:Kylanna Windwhisper} en el Bastión Plumaluna, Feralas (Alianza) y aprende Alquimia de Artesano. Necesitas {b}Alquimia 200{/b} y {b}nivel 35{/b}.",
  ["26x {s:7259:inv_potion_06:Nature Protection Potion} - 26 Liferoot, 26 Stranglekelp, 26 Leaded Vial"] = "26x {s:7259:inv_potion_06:Nature Protection Potion} - 26 Vidarraíz, 26 Alga estranguladora, 26 Vial emplomado",
  ["15x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 15 Blindweed, 15 Khadgar's Whisker, 15 Crystal Vial"] = "15x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 15 Carolina, 15 Mostacho de Khadgar, 15 Vial de cristal",
  ["47x {s:17551:inv_potion_68:Stonescale Oil} - 47 Stonescale Eel, 47 Leaded Vial"] = "47x {s:17551:inv_potion_68:Stonescale Oil} - 47 Anguila escama de piedra, 47 Vial emplomado",
  ["{b}Keep all of them{/b}, one craft makes 2 and the elixirs at 265 need all 94."] = "{b}Guárdalos todos{/b}: cada creación da 2 y los elixires de 265 necesitan los 94.",
  ["Alternative recipe"] = "Receta alternativa",
  ["If {i:13422:inv_misc_fish_11:Stonescale Eel} is expensive, skip this and keep making the Elixir of Greater Intellect until 265 (about 21), then make the Superior Mana Potions under 265-300."] = "Si {i:13422:inv_misc_fish_11:Stonescale Eel} está cara, sáltate esto y sigue haciendo el Elixir de intelecto superior hasta 265 (unos 21), luego haz las Pociones de maná excelentes de la sección 265-300.",
  ["10x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 10 Blindweed, 10 Khadgar's Whisker, 10 Crystal Vial"] = "10x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 10 Carolina, 10 Mostacho de Khadgar, 10 Vial de cristal",
  ["47x {s:17554:inv_potion_66:Elixir of Greater Defense} - 94 Stonescale Oil, 47 Sungrass, 47 Crystal Vial"] = "47x {s:17554:inv_potion_66:Elixir of Greater Defense} - 94 Aceite de escama de piedra, 47 Solea, 47 Vial de cristal",
  ["{i:13478:inv_scroll_03:Recipe: Elixir of Superior Defense} is sold by {n:0:horde:Kor'geld} in Orgrimmar and {n:0:alliance:Soolie Berryfizz} in Ironforge."] = "{i:13478:inv_scroll_03:Recipe: Elixir of Superior Defense} lo venden {n:0:horde:Kor'geld} en Orgrimmar y {n:0:alliance:Soolie Berryfizz} en Forjaz.",
  ["If you skipped the Stonescale Oil, make this:"] = "Si te saltaste el Aceite de escama de piedra, haz esto:",
  ["55x {s:17553:inv_potion_74:Superior Mana Potion} - 110 Sungrass, 110 Blindweed, 55 Crystal Vial."] = "55x {s:17553:inv_potion_74:Superior Mana Potion} - 110 Solea, 110 Carolina, 55 Vial de cristal.",
  ["{i:13477:inv_scroll_03:Recipe: Superior Mana Potion} is sold by {n:0:horde:Algernon} in Undercity and {n:0:alliance:Ulthir} in Darnassus."] = "{i:13477:inv_scroll_03:Recipe: Superior Mana Potion} lo venden {n:0:horde:Algernon} en Entrañas y {n:0:alliance:Ulthir} en Darnassus.",
  ["This WoW Forever Blacksmithing leveling guide will show you the fastest and cheapest way to level your Blacksmithing skill from 1 to 300. You will also find every trainer location and where to train Blacksmithing past 75, 150 and 225."] = "Esta guía de Herrería para WoW Forever te mostrará la forma más rápida y barata de subir tu habilidad de Herrería de 1 a 300. También encontrarás la ubicación de todos los instructores y dónde aprender Herrería más allá de 75, 150 y 225.",
  ["Below you will find the full shopping list, the Blacksmithing trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Blacksmithing uses a lot of ore, so I recommend leveling it together with Mining, you will need a lot of gold if you want to buy everything from the Auction House."] = "A continuación encontrarás la lista de la compra completa, los instructores de Herrería por zona inicial y capital, y las recetas más baratas para cada rango de habilidad, de Aprendiz a Artesano. La Herrería usa mucho mineral, así que te recomiendo subirla junto con Minería; necesitarás mucho oro si quieres comprarlo todo en la casa de subastas.",
  ["The Thorium Bars include the 140 you need for the four quests."] = "Las Barras de torio incluyen las 140 que necesitas para las cuatro misiones.",
  ["Blacksmithing Trainer Locations"] = "Ubicación de los instructores de Herrería",
  ["Apprentice Blacksmithing has no level requirement in Forever, so you can learn it on a fresh character."] = "Herrería de Aprendiz no tiene requisito de nivel en Forever, así que puedes aprenderla con un personaje recién creado.",
  ["Every capital city has a trainer except Darnassus. You can also ask a guard, then it will be marked with a red flag on your map."] = "Todas las capitales tienen un instructor excepto Darnassus. También puedes preguntar a un guardia y quedará marcado con una bandera roja en tu mapa.",
  ["Undercity: {n:0:horde:Basil Frye}"] = "Entrañas: {n:0:horde:Basil Frye}",
  ["Thunder Bluff: {n:0:horde:Thrag Stonehoof}"] = "Cima del Trueno: {n:0:horde:Thrag Stonehoof}",
  ["{n:0:horde:Dwukk} at the forge in Razor Hill"] = "{n:0:horde:Dwukk} en la forja de Cerrotajo",
  ["There is no Blacksmithing trainer in Mulgore, go to {n:0:horde:Thrag Stonehoof} on the lower rise in Thunder Bluff"] = "No hay instructor de Herrería en Mulgore, ve a ver a {n:0:horde:Thrag Stonehoof} en la meseta inferior de Cima del Trueno",
  ["{n:0:horde:Angus Hammerhand} at Bandarion Keep. Nobody near him sells a {i:5956:inv_hammer_20:Blacksmith Hammer}, {b}buy one before you go{/b} from {n:0:horde:Walter Mason} in Deathknell or {n:0:horde:Abigail Shiel} in Brill."] = "{n:0:horde:Angus Hammerhand} en el Bastión de Bandarion. Nadie cerca de él vende un {i:5956:inv_hammer_20:Blacksmith Hammer}, así que {b}cómpralo antes de ir{/b} a {n:0:horde:Walter Mason} en Camposanto o a {n:0:horde:Abigail Shiel} en Rémol.",
  ["{n:0::Daeann Steelwind} in Valanaar, {n:0::Aedi Thriceforged} in Shen'dar Village"] = "{n:0::Daeann Steelwind} en Valanaar, {n:0::Aedi Thriceforged} en la Aldea Shen'dar",
  ["Stormwind City: {n:0:alliance:Dane Lindgren}"] = "Ventormenta: {n:0:alliance:Dane Lindgren}",
  ["Ironforge: {n:0:alliance:Groum Stonebeard}"] = "Forjaz: {n:0:alliance:Groum Stonebeard}",
  ["{n:0:alliance:Smith Argus} in Goldshire, across from the inn"] = "{n:0:alliance:Smith Argus} en Villadorada, enfrente de la posada",
  ["{n:0:alliance:Tognus Flintfire} in Kharanos, across from the Thunderbrew Distillery"] = "{n:0:alliance:Tognus Flintfire} en Kharanos, enfrente de la Destilería Cebatruenos",
  ["There is no Blacksmithing trainer in Teldrassil or Darnassus, the closest one is {n:0:alliance:Delfrum Flintbeard} in Auberdine, Darkshore"] = "No hay instructor de Herrería en Teldrassil ni en Darnassus; el más cercano es {n:0:alliance:Delfrum Flintbeard} en Auberdine, Costa Oscura",
  ["You can find every Blacksmithing trainer for Horde and Alliance on my WoW Forever Blacksmithing Trainers page."] = "Puedes encontrar todos los instructores de Herrería de la Horda y la Alianza en mi página de instructores de Herrería de WoW Forever.",
  ["Apprentice Blacksmithing (1-75)"] = "Herrería de Aprendiz (1-75)",
  ["Buy a {i:5956:inv_hammer_20:Blacksmith Hammer} when you learn Blacksmithing, most recipes need it, so you can craft gear for yourself while you level. It costs a few copper, open your faction below to see who sells it closest to your trainer."] = "Compra un {i:5956:inv_hammer_20:Blacksmith Hammer} cuando aprendas Herrería; la mayoría de las recetas lo necesitan, así podrás fabricar equipo para ti mientras subes. Cuesta unos pocos cobres; despliega tu facción abajo para ver quién lo vende más cerca de tu instructor.",
  ["Horde vendors"] = "Vendedores de la Horda",
  ["Vendor"] = "Vendedor",
  ["{n:0:horde:Sumi}, right next to the trainer"] = "{n:0:horde:Sumi}, justo al lado del instructor",
  ["Undercity"] = "Entrañas",
  ["{n:0:horde:Samuel Van Brunt}, right next to the trainer"] = "{n:0:horde:Samuel Van Brunt}, justo al lado del instructor",
  ["Thunder Bluff"] = "Cima del Trueno",
  ["{n:0:horde:Taur Stonehoof}, right next to the trainer"] = "{n:0:horde:Taur Stonehoof}, justo al lado del instructor",
  ["{n:0:horde:Flakk} in Razor Hill"] = "{n:0:horde:Flakk} en Cerrotajo",
  ["{n:0:horde:Walter Mason} in Deathknell {n:0:horde:Abigail Shiel} in Brill"] = "{n:0:horde:Walter Mason} en Camposanto {n:0:horde:Abigail Shiel} en Rémol",
  ["{n:0::Halavuul Cragwind}, the Mining trainer in Valanaar {n:0::Aedi Thriceforged} in Shen'dar Village"] = "{n:0::Halavuul Cragwind}, el instructor de Minería de Valanaar {n:0::Aedi Thriceforged} en la Aldea Shen'dar",
  ["Alliance vendors"] = "Vendedores de la Alianza",
  ["Stormwind City"] = "Ventormenta",
  ["{n:0:alliance:Kaita Deepforge}, right next to the trainer"] = "{n:0:alliance:Kaita Deepforge}, justo al lado del instructor",
  ["Ironforge"] = "Forjaz",
  ["{n:0:alliance:Thurgrum Deepforge}, right next to the trainer"] = "{n:0:alliance:Thurgrum Deepforge}, justo al lado del instructor",
  ["{n:0:alliance:Tharynn Bouden} in Goldshire"] = "{n:0:alliance:Tharynn Bouden} en Villadorada",
  ["{n:0:alliance:Thrawn Boltar}, right next to the trainer"] = "{n:0:alliance:Thrawn Boltar}, justo al lado del instructor",
  ["Darkshore"] = "Costa Oscura",
  ["{n:0:alliance:Elisa Steelhand} in Auberdine, right next to the trainer"] = "{n:0:alliance:Elisa Steelhand} en Auberdine, justo al lado del instructor",
  ["30x {s:2660:inv_stone_sharpeningstone_01:Rough Sharpening Stone} - 30 Rough Stone"] = "30x {s:2660:inv_stone_sharpeningstone_01:Rough Sharpening Stone} - 30 Piedra en bruto",
  ["30x {s:3320:inv_stone_grindingstone_01:Rough Grinding Stone} - 60 Rough Stone"] = "30x {s:3320:inv_stone_grindingstone_01:Rough Grinding Stone} - 60 Piedra en bruto",
  ["Keep 10 of them, you need them for the Silver Rods at 75."] = "Guarda 10, los necesitas para las Varas de plata en 75.",
  ["36x {s:3326:inv_stone_grindingstone_02:Coarse Grinding Stone} - 72 Coarse Stone"] = "36x {s:3326:inv_stone_grindingstone_02:Coarse Grinding Stone} - 72 Piedra basta",
  ["Make all 36, you will need them for the bracers at 95 and 112."] = "Haz las 36, las necesitarás para los brazales de 95 y 112.",
  ["If you are not at 75 after these, make a few more."] = "Si no estás en 75 después de esto, haz unas cuantas más.",
  ["Journeyman Blacksmithing (75-150)"] = "Herrería de Oficial (75-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Blacksmithing. You need {b}Blacksmithing 50{/b} and {b}level 10{/b}:"] = "Para entrenar más allá de 75, visita a uno de estos instructores y aprende Herrería de Oficial. Necesitas {b}Herrería 50{/b} y {b}nivel 10{/b}:",
