  ["Stormwind City: {n:0:alliance:Therum Deepforge}"] = "Ventormenta: {n:0:alliance:Therum Deepforge}",
  ["Ironforge: {n:0:alliance:Rotgath Stonebeard}"] = "Forjaz: {n:0:alliance:Rotgath Stonebeard}",
  ["5x {s:7818:inv_staff_01:Silver Rod} - 5 Silver Bar, 10 Rough Grinding Stone"] = "5x {s:7818:inv_staff_01:Silver Rod} - 5 Barra de plata, 10 Piedra de afilar en bruto",
  ["You need the {i:5956:inv_hammer_20:Blacksmith Hammer} from here on."] = "A partir de aquí necesitas el {i:5956:inv_hammer_20:Blacksmith Hammer}.",
  ["Make 5x {s:2666:inv_belt_03:Runed Copper Belt} instead (10 Copper Bar each) if one Silver Bar costs more than 10 Copper Bars."] = "Haz 5x {s:2666:inv_belt_03:Runed Copper Belt} en su lugar (10 Barra de cobre cada uno) si una Barra de plata cuesta más que 10 Barras de cobre.",
  ["18x {s:2666:inv_belt_03:Runed Copper Belt} - 180 Copper Bar"] = "18x {s:2666:inv_belt_03:Runed Copper Belt} - 180 Barra de cobre",
  ["5x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 25 Bronze Bar, 10 Coarse Grinding Stone"] = "5x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 25 Barra de bronce, 10 Piedra de afilar basta",
  ["Use 10 of the Coarse Grinding Stones you made at 50 and keep the other 26 for 112."] = "Usa 10 de las Piedras de afilar bastas que hiciste en 50 y guarda las otras 26 para 112.",
  ["20x {s:3337:inv_stone_grindingstone_03:Heavy Grinding Stone} - 60 Heavy Stone"] = "20x {s:3337:inv_stone_grindingstone_03:Heavy Grinding Stone} - 60 Piedra pesada",
  ["Keep them, you need all 20 for the Golden Scale Bracers at 180."] = "Guárdalas, necesitas las 20 para los Brazales de escamas doradas en 180.",
  ["13x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 65 Bronze Bar, 26 Coarse Grinding Stone"] = "13x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 65 Barra de bronce, 26 Piedra de afilar basta",
  ["24x {s:2742:inv_sword_04:Bronze Shortsword} - 120 Bronze Bar, 96 Weak Flux, 48 Medium Leather"] = "24x {s:2742:inv_sword_04:Bronze Shortsword} - 120 Barra de bronce, 96 Flujo débil, 48 Cuero medio",
  ["I recommend these over the Patterned Bronze Bracers because they sell for more than twice as much to a vendor, so they end up cheaper."] = "Te recomiendo estas en lugar de los Brazales de bronce estampados porque se venden por más del doble a un vendedor, así que al final salen más baratas.",
  ["{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} and the {i:3466:inv_misc_ammo_gunpowder_01:Strong Flux} for the Bronze Warhammers (140-150) are sold by the Blacksmithing Supply vendor right next to the Blacksmithing trainer in every capital city."] = "El {i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} y el {i:3466:inv_misc_ammo_gunpowder_01:Strong Flux} para los Martillos de guerra de bronce (140-150) los vende el vendedor de suministros de herrería, justo al lado del instructor de Herrería en todas las capitales.",
  ["If you disenchant your greens:"] = "Si desencantas tus objetos verdes:",
  ["24x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 120 Bronze Bar, 48 Coarse Grinding Stone."] = "24x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 120 Barra de bronce, 48 Piedra de afilar basta.",
  ["10x {s:9985:inv_hammer_18:Bronze Warhammer} - 80 Bronze Bar, 10 Strong Flux, 10 Medium Leather"] = "10x {s:9985:inv_hammer_18:Bronze Warhammer} - 80 Barra de bronce, 10 Flujo fuerte, 10 Cuero medio",
  ["Expert Blacksmithing (150-215)"] = "Herrería de Experto (150-215)",
  ["To train past 150, visit {n:0:horde:Saru Steelfury} in Orgrimmar (Horde) or {n:0:alliance:Bengus Deepforge} in Ironforge (Alliance) and learn Expert Blacksmithing. You need {b}Blacksmithing 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Para entrenar más allá de 150, visita a {n:0:horde:Saru Steelfury} en Orgrimmar (Horda) o a {n:0:alliance:Bengus Deepforge} en Forjaz (Alianza) y aprende Herrería de Experto. Necesitas {b}Herrería 125{/b} y {b}nivel 20{/b}, y cuesta 50 de plata.",
  ["30x {s:3501:inv_bracer_06:Green Iron Bracers} - 180 Iron Bar, 30 Green Dye"] = "30x {s:3501:inv_bracer_06:Green Iron Bracers} - 180 Barra de hierro, 30 Tinte verde",
  ["Green Dye is sold by {n:0:horde:Tamar} in Orgrimmar and {n:0:alliance:Bombus Finespindle} in Ironforge."] = "El Tinte verde lo venden {n:0:horde:Tamar} en Orgrimmar y {n:0:alliance:Bombus Finespindle} en Forjaz.",
  ["8x {s:9920:inv_stone_grindingstone_04:Solid Grinding Stone} - 32 Solid Stone"] = "8x {s:9920:inv_stone_grindingstone_04:Solid Grinding Stone} - 32 Piedra sólida",
  ["Keep them, you need 6 for the Heavy Mithril Axes at 210."] = "Guárdalas, necesitas 6 para las Hachas de mitril pesadas en 210.",
  ["20x {s:7223:inv_bracer_10:Golden Scale Bracers} - 100 Steel Bar, 40 Heavy Grinding Stone"] = "20x {s:7223:inv_bracer_10:Golden Scale Bracers} - 100 Barra de acero, 40 Piedra de afilar pesada",
  ["Use the 20 Heavy Grinding Stones you made at 100 and make 20 more (60 {i:2838:inv_stone_12:Heavy Stone})."] = "Usa las 20 Piedras de afilar pesadas que hiciste en 100 y haz 20 más (60 {i:2838:inv_stone_12:Heavy Stone}).",
  ["If you have Mining 165, you can smelt the {i:3859:inv_ingot_steel:Steel Bars} yourself from {i:3575:inv_ingot_iron:Iron Bar} and {i:3857:inv_ore_tin_01:Coal}. Coal is sold by the Blacksmithing Supply vendor next to the Blacksmithing trainer in every capital city."] = "Si tienes Minería 165, puedes fundir tú mismo las {i:3859:inv_ingot_steel:Steel Bars} con {i:3575:inv_ingot_iron:Iron Bar} y {i:3857:inv_ore_tin_01:Coal}. El Carbón lo vende el vendedor de suministros de herrería, junto al instructor de Herrería en todas las capitales.",
  ["Alliance players should keep 6 of these. You might need them if you choose Armorsmithing."] = "Los jugadores de la Alianza deberían guardar 6. Puede que los necesites si eliges Forjador de armaduras.",
  ["17x {s:9931:inv_pants_04:Mithril Plate Pants} - 204 Mithril Bar"] = "17x {s:9931:inv_pants_04:Mithril Plate Pants} - 204 Barra de mitril",
  ["I recommend these over the Heavy Mithril Gauntlets because they sell for more than three times as much to a vendor, so they end up cheaper."] = "Te recomiendo estos en lugar de los Guanteletes de mitril pesados porque se venden por más del triple a un vendedor, así que al final salen más baratos.",
  ["6x {s:9993:inv_axe_14:Heavy Mithril Axe} - 72 Mithril Bar, 12 Citrine, 6 Solid Grinding Stone, 24 Heavy Leather"] = "6x {s:9993:inv_axe_14:Heavy Mithril Axe} - 72 Barra de mitril, 12 Citrino, 6 Piedra de afilar sólida, 24 Cuero pesado",
  ["Keep 2 of these. You might need them if you choose Weaponsmithing."] = "Guarda 2. Puede que las necesites si eliges Forjador de armas.",
  ["Blacksmithing Specializations"] = "Especializaciones de Herrería",
  ["At {b}Blacksmithing 200{/b} and {b}level 40{/b}, you can specialize in Armorsmithing or Weaponsmithing to craft powerful armor or weapons. Choosing one is optional, you don't need it to level Blacksmithing, and you can choose later too."] = "Con {b}Herrería 200{/b} y {b}nivel 40{/b} puedes especializarte en Forjador de armaduras o Forjador de armas para fabricar armaduras o armas poderosas. Elegir una es opcional, no la necesitas para subir Herrería y también puedes elegirla más tarde.",
  ["For information on how to become an Armorsmith or a Weaponsmith, please see my separate guides:"] = "Para saber cómo convertirte en Forjador de armaduras o Forjador de armas, consulta mis guías aparte:",
  ["Artisan Blacksmithing (215-300)"] = "Herrería de Artesano (215-300)",
  ["To train past 225, visit {n:0::Brikk Keencraft} in Booty Bay, Stranglethorn Vale and learn Artisan Blacksmithing. You need {b}Blacksmithing 200{/b} and {b}level 35{/b}, and both factions learn it there."] = "Para entrenar más allá de 225, visita a {n:0::Brikk Keencraft} en Bahía del Botín, Vega de Tuercespina, y aprende Herrería de Artesano. Necesitas {b}Herrería 200{/b} y {b}nivel 35{/b}, y ambas facciones la aprenden allí.",
  ["{i:7989:inv_scroll_06:Plans: Mithril Spurs} is a world drop. If you already have it, you can use the {b}Mithril Spurs{/b} tab instead."] = "{i:7989:inv_scroll_06:Plans: Mithril Spurs} es un botín aleatorio del mundo. Si ya lo tienes, puedes usar la pestaña {b}Espuelas de mitril{/b} en su lugar.",
  ["Heavy Mithril"] = "Mitril pesado",
  ["Mithril Spurs"] = "Espuelas de mitril",
  ["10x {s:9959:inv_chest_plate10:Heavy Mithril Breastplate} - 160 Mithril Bar"] = "10x {s:9959:inv_chest_plate10:Heavy Mithril Breastplate} - 160 Barra de mitril",
  ["Keep 2 of these. You might need them if you choose Armorsmithing."] = "Guarda 2. Puede que las necesites si eliges Forjador de armaduras.",
  ["5x {s:16641:inv_stone_sharpeningstone_05:Dense Sharpening Stone} - 5 Dense Stone"] = "5x {s:16641:inv_stone_sharpeningstone_05:Dense Sharpening Stone} - 5 Piedra densa",
  ["16x {s:9968:inv_boots_plate_01:Heavy Mithril Boots} - 224 Mithril Bar, 64 Thick Leather"] = "16x {s:9968:inv_boots_plate_01:Heavy Mithril Boots} - 224 Barra de mitril, 64 Cuero grueso",
  ["5x {s:16647:inv_belt_01:Imperial Plate Belt} - 110 Thorium Bar, 30 Rugged Leather, 5 Aquamarine"] = "5x {s:16647:inv_belt_01:Imperial Plate Belt} - 110 Barra de torio, 30 Cuero basto, 5 Aguamarina",
  ["You can get the recipe from the {q:7653::Imperial Plate Belt} quest (Requires {b}level 50{/b}) in Tanaris from {n:14567::Derotain Mudsipper}. You will need 20 Thorium Bar to complete it. Do his {q:7652::A Blue Light Bargain} quest first, it unlocks the Imperial Plate quests."] = "Puedes conseguir la receta con la misión {q:7653::Imperial Plate Belt} (requiere {b}nivel 50{/b}) en Tanaris, de {n:14567::Derotain Mudsipper}. Necesitarás 20 Barra de torio para completarla. Haz primero su misión {q:7652::A Blue Light Bargain}, que desbloquea las misiones de placas imperiales.",
  ["{b}The next three recipes are also from the same NPC{/b}, so make sure to bring at least 140 Thorium Bar with you to get all 4 recipes."] = "{b}Las tres recetas siguientes también son del mismo PNJ{/b}, así que asegúrate de llevar al menos 140 Barra de torio para conseguir las 4 recetas.",
  ["If you have the plans for one of these world drops, you can make it from 240 instead:"] = "Si tienes los diseños de uno de estos botines del mundo, puedes hacerlo a partir de 240:",
  ["240-255: 27x {s:10005:inv_sword_30:Dazzling Mithril Rapier} - 378 Mithril Bar, 27 Aquamarine, 54 Lesser Moonstone, 54 Moss Agate, 27 Solid Grinding Stone, 54 Mageweave Cloth"] = "240-255: 27x {s:10005:inv_sword_30:Dazzling Mithril Rapier} - 378 Barra de mitril, 27 Aguamarina, 54 Piedra lunar inferior, 54 Ágata musgosa, 27 Piedra de afilar sólida, 54 Paño de tejido mágico",
  ["240-255: 20x {s:10009:inv_hammer_17:Runed Mithril Hammer} - 360 Mithril Bar, 40 Core of Earth, 20 Solid Grinding Stone, 80 Thick Leather"] = "240-255: 20x {s:10009:inv_hammer_17:Runed Mithril Hammer} - 360 Barra de mitril, 40 Núcleo de tierra, 20 Piedra de afilar sólida, 80 Cuero grueso",
  ["240-255: 17x {s:16644:inv_bracer_13:Thorium Bracers} - 204 Thorium Bar, 68 Blue Power Crystal"] = "240-255: 17x {s:16644:inv_bracer_13:Thorium Bracers} - 204 Barra de torio, 68 Cristal de poder azul",
  ["10x {s:9964:ability_rogue_sprint:Mithril Spurs} - 40 Mithril Bar, 30 Solid Grinding Stone (120 Solid Stone)"] = "10x {s:9964:ability_rogue_sprint:Mithril Spurs} - 40 Barra de mitril, 30 Piedra de afilar sólida (120 Piedra sólida)",
  ["33x {s:9964:ability_rogue_sprint:Mithril Spurs} - 132 Mithril Bar, 99 Solid Grinding Stone (396 Solid Stone)"] = "33x {s:9964:ability_rogue_sprint:Mithril Spurs} - 132 Barra de mitril, 99 Piedra de afilar sólida (396 Piedra sólida)",
  ["{b}The next three recipes all come from one NPC in Tanaris{/b}, so make sure to bring at least 120 Thorium Bar with you to get all 3 recipes."] = "{b}Las tres recetas siguientes vienen todas de un mismo PNJ en Tanaris{/b}, así que asegúrate de llevar al menos 120 Barra de torio para conseguir las 3 recetas.",
  ["27x {s:16649:inv_bracer_19:Imperial Plate Bracers} - 540 Thorium Bar, 27 Star Ruby"] = "27x {s:16649:inv_bracer_19:Imperial Plate Bracers} - 540 Barra de torio, 27 Rubí estrella",
  ["You get the recipe from the {q:7655::Imperial Plate Bracer} quest (Requires {b}level 50{/b}) in Tanaris from {n:14567::Derotain Mudsipper}. You will need 20 Thorium Bar to complete it."] = "Consigues la receta con la misión {q:7655::Imperial Plate Bracer} (requiere {b}nivel 50{/b}) en Tanaris, de {n:14567::Derotain Mudsipper}. Necesitarás 20 Barra de torio para completarla.",
  ["20x {s:16657:inv_boots_plate_01:Imperial Plate Boots} - 680 Thorium Bar, 20 Star Ruby, 20 Aquamarine"] = "20x {s:16657:inv_boots_plate_01:Imperial Plate Boots} - 680 Barra de torio, 20 Rubí estrella, 20 Aguamarina",
  ["You get the recipe from the {q:7654::Imperial Plate Boots} quest, it needs 40 Thorium Bar."] = "Consigues la receta con la misión {q:7654::Imperial Plate Boots}, que necesita 40 Barra de torio.",
  ["{b}Note:{/b} It wasn't possible to level this far on the beta, so this part only relies on the data I found in the game files. There might be more recipes we haven't discovered yet, but if there is nothing else, these are the only recipes you can use to level until 300."] = "{b}Nota:{/b} No fue posible subir hasta aquí en la beta, así que esta parte se basa solo en los datos que encontré en los archivos del juego. Puede que haya más recetas que aún no hemos descubierto, pero si no hay nada más, estas son las únicas recetas que puedes usar para subir hasta 300.",
  ["10x {s:16730:inv_pants_04:Imperial Plate Leggings} - 440 Thorium Bar, 20 Star Ruby"] = "10x {s:16730:inv_pants_04:Imperial Plate Leggings} - 440 Barra de torio, 20 Rubí estrella",
  ["You get the recipe from the {q:7658::Imperial Plate Leggings} quest, it needs 60 Thorium Bar."] = "Consigues la receta con la misión {q:7658::Imperial Plate Leggings}, que necesita 60 Barra de torio.",
  ["This WoW Forever Enchanting leveling guide will show you the fastest and cheapest way to level your Enchanting skill from 1 to 300. You will also find every trainer location and where to train Enchanting past 75, 150 and 225."] = "Esta guía de Encantamiento para WoW Forever te mostrará la forma más rápida y barata de subir tu habilidad de Encantamiento de 1 a 300. También encontrarás la ubicación de todos los instructores y dónde aprender Encantamiento más allá de 75, 150 y 225.",
  ["Enchanting goes well with Tailoring because you don't need a gathering profession for either of them, and you can disenchant the items you made with Tailoring. Below you will find the shopping list, the Enchanting trainers by starting zone and capital city, and the cheapest enchants for every skill range. Forever added a few new low level recipes, so the first 70 points are cheaper than in Classic."] = "El Encantamiento combina bien con Sastrería porque ninguna de las dos necesita una profesión de recolección, y puedes desencantar los objetos que hagas con Sastrería. A continuación encontrarás la lista de la compra, los instructores de Encantamiento por zona inicial y capital, y los encantamientos más baratos para cada rango de habilidad. Forever añadió algunas recetas nuevas de nivel bajo, así que los primeros 70 puntos son más baratos que en Classic.",
  ["An alternative replaces the whole row, so buy the one that is cheaper."] = "Una alternativa sustituye toda la fila, así que compra la que sea más barata.",
  ["Enchanting Trainer Locations"] = "Ubicación de los instructores de Encantamiento",
  ["Apprentice Enchanting has no level requirement in Forever, so you can learn it on a fresh character."] = "Encantamiento de Aprendiz no tiene requisito de nivel en Forever, así que puedes aprenderlo con un personaje recién creado.",
  ["Undercity: {n:0:horde:Malcomb Wynn}"] = "Entrañas: {n:0:horde:Malcomb Wynn}",
  ["Thunder Bluff: {n:0:horde:Mot Dawnstrider}"] = "Cima del Trueno: {n:0:horde:Mot Dawnstrider}",
  ["{n:0:horde:Pa'zula} in Sen'jin Village"] = "{n:0:horde:Pa'zula} en la Aldea Sen'jin",
  ["There is no Enchanting trainer in Mulgore, go to {n:0:horde:Mot Dawnstrider} on the middle rise in Thunder Bluff"] = "No hay instructor de Encantamiento en Mulgore, ve a ver a {n:0:horde:Mot Dawnstrider} en la meseta central de Cima del Trueno",
  ["{n:0:horde:Vance Undergloom} upstairs in the inn in Brill"] = "{n:0:horde:Vance Undergloom} en el piso de arriba de la posada de Rémol",
  ["{n:0::Eaysaa Brightgust} in Valanaar, {n:0::Nasalanna Windsinger} in Shen'dar Village"] = "{n:0::Eaysaa Brightgust} en Valanaar, {n:0::Nasalanna Windsinger} en la Aldea Shen'dar",
  ["Stormwind City: {n:0:alliance:Betty Quin}"] = "Ventormenta: {n:0:alliance:Betty Quin}",
  ["Ironforge: {n:0:alliance:Thonys Pillarstone}"] = "Forjaz: {n:0:alliance:Thonys Pillarstone}",
  ["There is no Enchanting trainer in Elwynn Forest, go to {n:0:alliance:Betty Quin} in the Mage Quarter in Stormwind City"] = "No hay instructor de Encantamiento en el Bosque de Elwynn, ve a ver a {n:0:alliance:Betty Quin} en el Barrio de los Magos de Ventormenta",
  ["There is no Enchanting trainer in Dun Morogh, go to {n:0:alliance:Thonys Pillarstone} at the Great Forge in Ironforge"] = "No hay instructor de Encantamiento en Dun Morogh, ve a ver a {n:0:alliance:Thonys Pillarstone} en La Gran Fundición de Forjaz",
  ["{n:0:alliance:Alanna Raveneye} at the Oracle Glade, in the north-west of Teldrassil"] = "{n:0:alliance:Alanna Raveneye} en el Claro del Oráculo, al noroeste de Teldrassil",
  ["You can find every Enchanting trainer for Horde and Alliance on my WoW Forever Enchanting Trainers page."] = "Puedes encontrar todos los instructores de Encantamiento de la Horda y la Alianza en mi página de instructores de Encantamiento de WoW Forever.",
  ["Enchanting Macro for Faster Leveling"] = "Macro de Encantamiento para subir más rápido",
  ["I highly recommend using this macro to speed up the leveling process."] = "Te recomiendo mucho usar esta macro para acelerar la subida.",
  ["This macro presses the Create button for you and confirms the prompt that asks if you want to replace the enchant already on the item, without any extra clicks."] = "Esta macro pulsa el botón Crear por ti y confirma la ventana que pregunta si quieres sustituir el encantamiento que ya tiene el objeto, sin clics adicionales.",
  ["If you have never made a macro, type /m in the chat and press Enter, click New, give it a name and paste these two lines into it."] = "Si nunca has hecho una macro, escribe /m en el chat y pulsa Intro, haz clic en Nueva, ponle un nombre y pega estas dos líneas.",
  ["How to Use"] = "Cómo usarla",
  ["Place the macro on your action bar"] = "Coloca la macro en tu barra de acción",
  ["Open your Enchanting profession window"] = "Abre la ventana de tu profesión de Encantamiento",
  ["Select the enchant you want to craft (make sure it's the right one)"] = "Selecciona el encantamiento que quieres crear (asegúrate de que sea el correcto)",
  ["Put the item you want to enchant into the optional target slot"] = "Pon el objeto que quieres encantar en la casilla de objetivo opcional",
  ["Press the macro repeatedly"] = "Pulsa la macro repetidamente",
  ["Disenchanting"] = "Desencantar",
  ["You get {s:13262:inv_enchant_disenchant:Disenchant} together with Apprentice Enchanting. In WoW Forever {b}Disenchant is not in your spellbook{/b}, it's in the Enchanting box of the Professions window."] = "Obtienes {s:13262:inv_enchant_disenchant:Disenchant} junto con Encantamiento de Aprendiz. En WoW Forever {b}Desencantar no está en tu libro de hechizos{/b}, sino en el recuadro de Encantamiento de la ventana de Profesiones.",
  ["If you are looking for the disenchanting table, it's in my disenchanting guide, and if you can't find the Disenchant button, the guide shows it with pictures:"] = "Si buscas la tabla de desencantamiento, está en mi guía de desencantamiento, y si no encuentras el botón Desencantar, la guía lo muestra con imágenes:",
  ["Apprentice Enchanting (1-70)"] = "Encantamiento de Aprendiz (1-70)",
  ["1x {s:7421:inv_staff_goldfeathered_01:Runed Copper Rod} - 1 Copper Rod, 1 Mote of Magic"] = "1x {s:7421:inv_staff_goldfeathered_01:Runed Copper Rod} - 1 Vara de cobre, 1 Mota de magia",
  ["The {i:6217:inv_misc_flute_01:Copper Rod} and the {i:247786:inv_elemental_mote_mana:Mote of Magic} are sold by the Enchanting Supply vendor near your trainer, don't buy them from the Auction House."] = "La {i:6217:inv_misc_flute_01:Copper Rod} y la {i:247786:inv_elemental_mote_mana:Mote of Magic} las vende el vendedor de suministros de encantamiento cerca de tu instructor, no las compres en la casa de subastas.",
  ["{b}If you are leveling in a starting zone with a low level character{/b}, you can buy the Copper Rod from a trade vendor there, but the Mote of Magic is only sold by Enchanting vendors. In the starting zones only the trainers on {b}Zephras Isle{/b} and in {b}Tirisfal Glades{/b} (Brill) sell it, everyone else has to visit the trainer in the capital city, the vendor stands right next to them."] = "{b}Si estás subiendo en una zona inicial con un personaje de nivel bajo{/b}, puedes comprar la Vara de cobre a un vendedor de suministros de comercio de allí, pero la Mota de magia solo la venden los vendedores de encantamiento. En las zonas iniciales solo la venden los instructores de la {b}Isla Zephras{/b} y de los {b}Claros de Tirisfal{/b} (Rémol); los demás tienen que visitar al instructor de la capital, el vendedor está justo a su lado.",
  ["18x {s:7418:spell_holy_greaterheal:Enchant Bracer - Inferior Stamina} - 18 Mote of Magic"] = "18x {s:7418:spell_holy_greaterheal:Enchant Bracer - Inferior Stamina} - 18 Mota de magia",
  ["Make one of these:"] = "Haz uno de estos:",
  ["50x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 50 Strange Dust"] = "50x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 50 Polvo extraño",
  ["50x {s:7428:spell_holy_greaterheal:Enchant Bracer - Minor Deflect} - 50 Lesser Magic Essence"] = "50x {s:7428:spell_holy_greaterheal:Enchant Bracer - Minor Deflect} - 50 Esencia mágica menor",
  ["A {i:10939:inv_enchant_essencemagiclarge:Greater Magic Essence} turns into 3 Lesser Magic Essence when you right-click it in your bags, so you can buy those too."] = "Una {i:10939:inv_enchant_essencemagiclarge:Greater Magic Essence} se convierte en 3 Esencia mágica menor al hacer clic derecho sobre ella en tus bolsas, así que también puedes comprar esas.",
  ["Journeyman Enchanting (70-150)"] = "Encantamiento de Oficial (70-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Enchanting. You need {b}Enchanting 50{/b} and {b}level 10{/b}:"] = "Para entrenar más allá de 75, visita a uno de estos instructores y aprende Encantamiento de Oficial. Necesitas {b}Encantamiento 50{/b} y {b}nivel 10{/b}:",
  ["Undercity: {n:0:horde:Lavinia Crowe}"] = "Entrañas: {n:0:horde:Lavinia Crowe}",
  ["Thunder Bluff: {n:0:horde:Teg Dawnstrider}"] = "Cima del Trueno: {n:0:horde:Teg Dawnstrider}",
  ["Stormwind City: {n:0:alliance:Lucan Cordell}"] = "Ventormenta: {n:0:alliance:Lucan Cordell}",
  ["Ironforge: {n:0:alliance:Gimble Thistlefuzz}"] = "Forjaz: {n:0:alliance:Gimble Thistlefuzz}",
  ["If you bought Strange Dust pick the {b}Strange Dust{/b} tab, if you bought Lesser Magic Essence pick the {b}Lesser Magic Essence{/b} tab."] = "Si compraste Polvo extraño, elige la pestaña {b}Polvo extraño{/b}; si compraste Esencia mágica menor, elige la pestaña {b}Esencia mágica menor{/b}.",
  ["Strange Dust"] = "Polvo extraño",
  ["Lesser Magic Essence"] = "Esencia mágica menor",
  ["49x {s:7426:spell_holy_greaterheal:Enchant Chest - Minor Absorption} - 49 Lesser Magic Essence"] = "49x {s:7426:spell_holy_greaterheal:Enchant Chest - Minor Absorption} - 49 Esencia mágica menor",
  ["1x {s:7795:inv_staff_01:Runed Silver Rod} - 1 Silver Rod, 3 Strange Dust, 4 Lesser Magic Essence, 1 Shadowgem"] = "1x {s:7795:inv_staff_01:Runed Silver Rod} - 1 Vara de plata, 3 Polvo extraño, 4 Esencia mágica menor, 1 Gema de las Sombras",
  ["{i:6338:inv_staff_01:Silver Rod} and every other rod in this guide (Golden, Truesilver, Arcanite) is made by Blacksmiths, you can buy them from the Auction House."] = "La {i:6338:inv_staff_01:Silver Rod} y todas las demás varas de esta guía (dorada, veraplata, arcanita) las fabrican los herreros; puedes comprarlas en la casa de subastas.",
  ["23x {s:14807:inv_staff_07:Greater Magic Wand} - 23 Simple Wood, 46 Lesser Magic Essence"] = "23x {s:14807:inv_staff_07:Greater Magic Wand} - 23 Madera simple, 46 Esencia mágica menor",
  ["37x {s:7793:spell_holy_greaterheal:Enchant 2H Weapon - Lesser Intellect} - 148 Lesser Magic Essence"] = "37x {s:7793:spell_holy_greaterheal:Enchant 2H Weapon - Lesser Intellect} - 148 Esencia mágica menor",
  ["{i:6349:inv_misc_note_01:Formula: Enchant 2H Weapon - Lesser Intellect} is sold by these vendors:"] = "{i:6349:inv_misc_note_01:Formula: Enchant 2H Weapon - Lesser Intellect} lo venden estos vendedores:",
  ["{n:0:horde:Kithas} in Orgrimmar"] = "{n:0:horde:Kithas} en Orgrimmar",
  ["{n:0:horde:Nata Dawnstrider} in Thunder Bluff"] = "{n:0:horde:Nata Dawnstrider} en Cima del Trueno",
  ["{n:0:horde:Leo Sarn} in Silverpine Forest"] = "{n:0:horde:Leo Sarn} en el Bosque de Argénteos",
  ["{n:0:alliance:Tilli Thistlefuzz} in Ironforge"] = "{n:0:alliance:Tilli Thistlefuzz} en Forjaz",
  ["Buy {i:20752:inv_misc_note_01:Formula: Minor Mana Oil} and {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} from them too, you will need them at 150 and 200."] = "Cómprales también {i:20752:inv_misc_note_01:Formula: Minor Mana Oil} y {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil}, los necesitarás en 150 y 200.",
  ["If you don't want to get the formula, make this:"] = "Si no quieres conseguir la fórmula, haz esto:",
  ["25x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 100 Strange Dust"] = "25x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 100 Polvo extraño",
  ["23x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 23 Strange Dust"] = "23x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 23 Polvo extraño",
  ["15x {s:7457:spell_holy_greaterheal:Enchant Bracer - Minor Stamina} - 30 Strange Dust"] = "15x {s:7457:spell_holy_greaterheal:Enchant Bracer - Minor Stamina} - 30 Polvo extraño",
  ["9x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 18 Strange Dust"] = "9x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 18 Polvo extraño",
  ["32x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 64 Strange Dust"] = "32x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 64 Polvo extraño",
  ["20x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 80 Strange Dust"] = "20x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 80 Polvo extraño",
  ["If 20 Soul Dust cost less than 80 Strange Dust, make this:"] = "Si 20 Polvo de alma cuestan menos que 80 Polvo extraño, haz esto:",
  ["20x {s:13501:spell_holy_greaterheal:Enchant Bracer - Lesser Stamina} - 20 Soul Dust."] = "20x {s:13501:spell_holy_greaterheal:Enchant Bracer - Lesser Stamina} - 20 Polvo de alma.",
  ["Expert Enchanting (150-225)"] = "Encantamiento de Experto (150-225)",
  ["To train past 150, visit one of these trainers and learn Expert Enchanting. You need {b}Enchanting 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Para entrenar más allá de 150, visita a uno de estos instructores y aprende Encantamiento de Experto. Necesitas {b}Encantamiento 125{/b} y {b}nivel 20{/b}, y cuesta 50 de plata.",
  ["There is only one Expert Enchanting trainer for each faction. {n:0:horde:Hgarth} in Stonetalon Mountains at Sun Rock Retreat is the Horde trainer, he is up on the hill above the village. {n:0:alliance:Kitta Firewind} in Elwynn Forest is the Alliance trainer, she is at the top of the Tower of Azora."] = "Solo hay un instructor de Encantamiento de Experto por facción. {n:0:horde:Hgarth}, en el Refugio Roca del Sol de la Sierra Espolón, es el instructor de la Horda; está en lo alto de la colina sobre el pueblo. {n:0:alliance:Kitta Firewind}, en el Bosque de Elwynn, es la instructora de la Alianza; está en lo alto de la Torre de Azora.",
  ["1x {s:13628:inv_staff_10:Runed Golden Rod} - 1 Golden Rod, 1 Iridescent Pearl, 1 Greater Astral Essence, 1 Soul Dust"] = "1x {s:13628:inv_staff_10:Runed Golden Rod} - 1 Vara dorada, 1 Perla iridiscente, 1 Esencia astral superior, 1 Polvo de alma",
  ["16x {s:25125:inv_potion_98:Minor Mana Oil} - 16 Soul Dust, 32 Maple Seed, 16 Leaded Vial"] = "16x {s:25125:inv_potion_98:Minor Mana Oil} - 16 Polvo de alma, 32 Semilla de arce, 16 Vial emplomado",
  ["{i:20752:inv_misc_note_01:Formula: Minor Mana Oil} is sold by these vendors:"] = "{i:20752:inv_misc_note_01:Formula: Minor Mana Oil} lo venden estos vendedores:",
  ["{n:0:horde:Thaddeus Webb} in Undercity"] = "{n:0:horde:Thaddeus Webb} en Entrañas",
  ["{n:0:alliance:Vaean} in Darnassus"] = "{n:0:alliance:Vaean} en Darnassus",
  ["{n:0:alliance:Jessara Cordell} in Stormwind City"] = "{n:0:alliance:Jessara Cordell} en Ventormenta",
  ["Buy {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} from them too, you will need it at 200."] = "Cómprales también {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil}, lo necesitarás en 200.",
  ["{i:17034:inv_misc_food_02:Maple Seed} is sold by Reagent vendors and {i:3372:inv_potion_85:Leaded Vial} by Alchemy Supply vendors."] = "La {i:17034:inv_misc_food_02:Maple Seed} la venden los vendedores de componentes y el {i:3372:inv_potion_85:Leaded Vial} los vendedores de suministros de alquimia.",
  ["47x {s:13637:spell_holy_greaterheal:Enchant Boots - Lesser Agility} - 47 Soul Dust"] = "47x {s:13637:spell_holy_greaterheal:Enchant Boots - Lesser Agility} - 47 Polvo de alma",
  ["If 2 Vision Dust cost less than 3 Soul Dust, stop the boots at 185 and make this until 200:"] = "Si 2 Polvo de visión cuestan menos que 3 Polvo de alma, deja las botas en 185 y haz esto hasta 200:",
  ["15x {s:13661:spell_holy_greaterheal:Enchant Bracer - Strength} - 15 Vision Dust."] = "15x {s:13661:spell_holy_greaterheal:Enchant Bracer - Strength} - 15 Polvo de visión.",
  ["1x {s:13702:inv_staff_11:Runed Truesilver Rod} - 1 Truesilver Rod, 1 Black Pearl, 1 Greater Mystic Essence, 1 Vision Dust"] = "1x {s:13702:inv_staff_11:Runed Truesilver Rod} - 1 Vara de veraplata, 1 Perla negra, 1 Esencia mística superior, 1 Polvo de visión",
  ["25x {s:25126:inv_potion_103:Lesser Wizard Oil} - 25 Vision Dust, 50 Stranglethorn Seed, 25 Leaded Vial"] = "25x {s:25126:inv_potion_103:Lesser Wizard Oil} - 25 Polvo de visión, 50 Semilla de Tuercespina, 25 Vial emplomado",
  ["If you didn't buy {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} yet, the vendors are listed at the 151-165 step above."] = "Si aún no compraste {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil}, los vendedores aparecen en el paso 151-165 de arriba.",
  ["{i:17035:inv_misc_food_02:Stranglethorn Seed} is sold by Reagent vendors and {i:3372:inv_potion_85:Leaded Vial} by Alchemy Supply vendors."] = "La {i:17035:inv_misc_food_02:Stranglethorn Seed} la venden los vendedores de componentes y el {i:3372:inv_potion_85:Leaded Vial} los vendedores de suministros de alquimia.",
  ["5x {s:13746:spell_holy_greaterheal:Enchant Cloak - Greater Defense} - 5 Vision Dust"] = "5x {s:13746:spell_holy_greaterheal:Enchant Cloak - Greater Defense} - 5 Polvo de visión",
  ["Artisan Enchanting (225-300)"] = "Encantamiento de Artesano (225-300)",
  ["The Expert Enchanting trainers only teach you up to 225. To train Enchanting past 225 you need {b}level 35{/b} and {b}Enchanting 200{/b}, then learn Artisan Enchanting from Annora in Uldaman (I explain below how to find her). {b}She is the only trainer who teaches Artisan Enchanting.{/b}"] = "Los instructores de Encantamiento de Experto solo enseñan hasta 225. Para entrenar Encantamiento más allá de 225 necesitas {b}nivel 35{/b} y {b}Encantamiento 200{/b}; después aprende Encantamiento de Artesano con Annora en Uldaman (abajo te explico cómo encontrarla). {b}Es la única instructora que enseña Encantamiento de Artesano.{/b}",
  ["There are a few recipes only Annora teaches, {b}so bring enough gold to learn every recipe and enough materials to reach Enchanting 250{/b}, otherwise you have to go back to Uldaman for the higher recipes. Around 50 {i:11137:inv_enchant_dustvision:Vision Dust} gets you to 250."] = "Hay algunas recetas que solo enseña Annora, {b}así que lleva oro suficiente para aprender todas las recetas y materiales suficientes para llegar a Encantamiento 250{/b}; si no, tendrás que volver a Uldaman para las recetas más altas. Con unos 50 {i:11137:inv_enchant_dustvision:Vision Dust} llegas a 250.",
  ["How to enter Uldaman"] = "Cómo entrar en Uldaman",
  ["Uldaman is in the Badlands and it has two entrances, use the back entrance. You can't solo it at level 35, so go with a party or ask a level 60 to help."] = "Uldaman está en las Tierras Inhóspitas y tiene dos entradas; usa la entrada trasera. No puedes hacerla solo a nivel 35, así que ve en grupo o pide ayuda a un nivel 60.",
  ["How to find Annora"] = "Cómo encontrar a Annora",
  ["Annora only spawns once you {b}kill every mob in the area she is in!{/b}"] = "Annora solo aparece cuando {b}matas a todos los enemigos de la zona en la que está.{/b}",
  ["{b}Don't forget to learn everything from Annora before you leave Uldaman!{/b} The recipes from 230 up are taught nowhere else."] = "{b}¡No olvides aprender todo de Annora antes de salir de Uldaman!{/b} Las recetas a partir de 230 no se enseñan en ningún otro sitio.",
  ["Recipe"] = "Receta",
  ["Skill"] = "Habilidad",
  ["Cost"] = "Coste",
  ["{b}Artisan Enchanting{/b}"] = "{b}Encantamiento de Artesano{/b}",
  ["37x {s:13815:spell_holy_greaterheal:Enchant Gloves - Agility} - 37 Vision Dust"] = "37x {s:13815:spell_holy_greaterheal:Enchant Gloves - Agility} - 37 Polvo de visión",
  ["20x {s:25127:inv_potion_99:Lesser Mana Oil} - 20 Dream Dust, 20 Purple Lotus, 20 Crystal Vial"] = "20x {s:25127:inv_potion_99:Lesser Mana Oil} - 20 Polvo onírico, 20 Loto cárdeno, 20 Vial de cristal",
  ["{i:20754:inv_misc_note_01:Formula: Lesser Mana Oil} is sold by {n:0::Kania} in Silithus, she is upstairs in the inn. {i:8925:inv_potion_86:Crystal Vial} is sold by {n:0::Mishta} in Silithus or any Alchemy Supply vendor."] = "{i:20754:inv_misc_note_01:Formula: Lesser Mana Oil} lo vende {n:0::Kania} en Silithus, está en el piso de arriba de la posada. El {i:8925:inv_potion_86:Crystal Vial} lo vende {n:0::Mishta} en Silithus o cualquier vendedor de suministros de alquimia.",
  ["If you don't have Purple Lotus, make {s:13939:spell_holy_greaterheal:Enchant Bracer - Greater Strength} instead (1 Dream Dust, 2 Lesser Nether Essence each), Annora teaches it."] = "Si no tienes Loto cárdeno, haz {s:13939:spell_holy_greaterheal:Enchant Bracer - Greater Strength} en su lugar (1 Polvo onírico y 2 Esencia abisal menor cada uno); Annora lo enseña.",
  ["40x {s:20017:spell_holy_greaterheal:Enchant Shield - Greater Stamina} - 240 Dream Dust"] = "40x {s:20017:spell_holy_greaterheal:Enchant Shield - Greater Stamina} - 240 Polvo onírico",
  ["{i:16217:inv_misc_note_01:Formula: Enchant Shield - Greater Stamina} is sold by {n:0:horde:Daniel Bartlett} in Undercity and {n:0:alliance:Mythrin'dir} in Darnassus. It's bind on pickup, so don't buy it on an alt."] = "{i:16217:inv_misc_note_01:Formula: Enchant Shield - Greater Stamina} lo venden {n:0:horde:Daniel Bartlett} en Entrañas y {n:0:alliance:Mythrin'dir} en Darnassus. Se liga al recogerlo, así que no lo compres con un alter.",
  ["From 290 you can make the Runed Arcanite Rod, see the next step."] = "A partir de 290 puedes hacer la Vara de arcanita rúnica, mira el paso siguiente.",
  ["1x {s:20051:inv_wand_09:Runed Arcanite Rod} - 1 Arcanite Rod, 1 Golden Pearl, 10 Illusion Dust, 4 Greater Eternal Essence, 4 Small Brilliant Shard, 2 Large Brilliant Shard"] = "1x {s:20051:inv_wand_09:Runed Arcanite Rod} - 1 Vara de arcanita, 1 Perla dorada, 10 Polvo de ilusión, 4 Esencia eterna superior, 4 Fragmento brillante pequeño, 2 Fragmento brillante grande",
  ["{i:16243:inv_misc_note_01:Formula: Runed Arcanite Rod} is sold by {n:0::Lorelae Wintersong} in Moonglade at Nighthaven."] = "{i:16243:inv_misc_note_01:Formula: Runed Arcanite Rod} lo vende {n:0::Lorelae Wintersong} en Amparo de la Noche, Claro de la Luna.",
  ["{b}You need this rod for some recipes from 290 and for most recipes at 300{/b}, Crusader for example. You can make it from 290, but if you don't need it yet, you can make it later and make one more Shield for the last point instead."] = "{b}Necesitas esta vara para algunas recetas a partir de 290 y para la mayoría de las recetas de 300{/b}, por ejemplo Cruzado. Puedes hacerla a partir de 290, pero si aún no la necesitas, puedes hacerla más tarde y hacer un Escudo más para el último punto.",
  ["This WoW Forever Engineering leveling guide will show you the fastest and cheapest way to level your Engineering skill from 1 to 300. You will also find every trainer location and where to train Engineering past 75, 150 and 225."] = "Esta guía de Ingeniería para WoW Forever te mostrará la forma más rápida y barata de subir tu habilidad de Ingeniería de 1 a 300. También encontrarás la ubicación de todos los instructores y dónde aprender Ingeniería más allá de 75, 150 y 225.",
  ["Engineering is best combined with Mining, because almost everything you make needs stone and bars, and you can mine both. If you don't have Mining, you have to buy everything from the Auction House. Below you will find the shopping list, the Engineering trainers by starting zone and capital city, and the cheapest recipes for every skill range."] = "La Ingeniería combina mejor con Minería, porque casi todo lo que fabricas necesita piedra y barras, y puedes extraer ambas. Si no tienes Minería, tendrás que comprarlo todo en la casa de subastas. A continuación encontrarás la lista de la compra, los instructores de Ingeniería por zona inicial y capital, y las recetas más baratas para cada rango de habilidad.",
  ["Engineering Trainer Locations"] = "Ubicación de los instructores de Ingeniería",
  ["Apprentice Engineering has no level requirement in Forever, so you can learn it on a fresh character."] = "Ingeniería de Aprendiz no tiene requisito de nivel en Forever, así que puedes aprenderla con un personaje recién creado.",
  ["There is no Engineering trainer in Thunder Bluff and Darnassus, the other four capitals have one. You can also ask a guard, then it will be marked with a red flag on your map."] = "No hay instructor de Ingeniería en Cima del Trueno ni en Darnassus; las otras cuatro capitales tienen uno. También puedes preguntar a un guardia y quedará marcado con una bandera roja en tu mapa.",
  ["Undercity: {n:0:horde:Graham Van Talen}"] = "Entrañas: {n:0:horde:Graham Van Talen}",
  ["{n:0:horde:Mukdrak} in Razor Hill, near the forge next to the road to Orgrimmar"] = "{n:0:horde:Mukdrak} en Cerrotajo, cerca de la forja junto al camino a Orgrimmar",
  ["{n:0::Twizwick Sprocketgrind} on the plateau above the Venture Co. Mine, hard to reach at low level. There is no anvil near him and nobody there sells the Blacksmith Hammer, so it's probably best to go to {n:0:horde:Thund} in Orgrimmar instead."] = "{n:0::Twizwick Sprocketgrind} en la meseta sobre la mina de la Ventura y Cía., difícil de alcanzar a nivel bajo. No hay yunque cerca de él y nadie allí vende el Martillo de herrero, así que probablemente es mejor ir a ver a {n:0:horde:Thund} en Orgrimmar.",
  ["There is no Engineering trainer in Tirisfal Glades, go to {n:0:horde:Graham Van Talen} in the Rogues' Quarter in Undercity"] = "No hay instructor de Ingeniería en los Claros de Tirisfal, ve a ver a {n:0:horde:Graham Van Talen} en el Barrio de los Pícaros de Entrañas",
  ["{n:0::Strange Hermit} in Shadowgale Forest"] = "{n:0::Strange Hermit} en el Bosque Shadowgale",
  ["Stormwind City: {n:0:alliance:Sprite Jumpsprocket}"] = "Ventormenta: {n:0:alliance:Sprite Jumpsprocket}",
  ["Ironforge: {n:0:alliance:Jemma Quikswitch}"] = "Forjaz: {n:0:alliance:Jemma Quikswitch}",
  ["There is no Engineering trainer in Elwynn Forest, go to {n:0:alliance:Sprite Jumpsprocket} in the Dwarven District in Stormwind City"] = "No hay instructor de Ingeniería en el Bosque de Elwynn, ve a ver a {n:0:alliance:Sprite Jumpsprocket} en el Distrito de los Enanos de Ventormenta",
  ["{n:0:alliance:Bronk Guzzlegear} at Steelgrill's Depot"] = "{n:0:alliance:Bronk Guzzlegear} en el Almacén de Brasacerada",
  ["There is no Engineering trainer in Teldrassil or Darnassus, the closest one is {n:0:alliance:Jenna Lemkenilli} in Auberdine in Darkshore"] = "No hay instructor de Ingeniería en Teldrassil ni en Darnassus; el más cercano es {n:0:alliance:Jenna Lemkenilli} en Auberdine, en Costa Oscura",
  ["You can find every Engineering trainer for Horde and Alliance on my WoW Forever Engineering Trainers page."] = "Puedes encontrar todos los instructores de Ingeniería de la Horda y la Alianza en mi página de instructores de Ingeniería de WoW Forever.",
  ["Apprentice Engineering (1-50)"] = "Ingeniería de Aprendiz (1-50)",
  ["Buy a {i:5956:inv_hammer_20:Blacksmith Hammer}, most recipes need it. {b}Most trainers{/b} have a Blacksmithing or Engineering Supply vendor nearby that sells it, {b}except{/b} the trainers in Dun Morogh and on Zephras Isle. In Dun Morogh buy it in Kharanos from {n:0:alliance:Thrawn Boltar}, on Zephras Isle in Shen'dar Village from {n:0::Aedi Thriceforged}."] = "Compra un {i:5956:inv_hammer_20:Blacksmith Hammer}, la mayoría de las recetas lo necesitan. {b}La mayoría de los instructores{/b} tienen cerca un vendedor de suministros de herrería o de ingeniería que lo vende, {b}excepto{/b} los instructores de Dun Morogh y de la Isla Zephras. En Dun Morogh cómpralo en Kharanos a {n:0:alliance:Thrawn Boltar}; en la Isla Zephras, en la Aldea Shen'dar a {n:0::Aedi Thriceforged}.",
  ["The {b}Gnome{/b} racial changed in Forever. Instead of +15 Engineering skill, Engineering Specialization now makes your devices fail or backfire 20% less often, so Gnomes level Engineering exactly like everyone else."] = "El rasgo racial de los {b}gnomos{/b} cambió en Forever. En lugar de +15 a la habilidad de Ingeniería, Especialización en ingeniería ahora hace que tus dispositivos fallen o se vuelvan en tu contra un 20% menos a menudo, así que los gnomos suben Ingeniería exactamente igual que los demás.",
  ["66x {s:3918:inv_misc_dust_01:Rough Blasting Powder} - 66 Rough Stone"] = "66x {s:3918:inv_misc_dust_01:Rough Blasting Powder} - 66 Piedra en bruto",
  ["Keep all of them, you need 66 for the bombs at 51."] = "Guárdalos todos, necesitas 66 para las bombas de 51.",
  ["33x {s:3922:inv_misc_gear_06:Handful of Copper Bolts} - 33 Copper Bar"] = "33x {s:3922:inv_misc_gear_06:Handful of Copper Bolts} - 33 Barra de cobre",
  ["Keep these too, you will need all 33 for the bombs."] = "Guarda también estos, necesitarás los 33 para las bombas.",
  ["1x {s:7430:inv_misc_wrench_01:Arclight Spanner} - 6 Copper Bar"] = "1x {s:7430:inv_misc_wrench_01:Arclight Spanner} - 6 Barra de cobre",
  ["You will use this to craft Engineering recipes, so keep it."] = "La usarás para fabricar recetas de Ingeniería, así que guárdala.",
  ["Journeyman Engineering (50-150)"] = "Ingeniería de Oficial (50-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Engineering. You need {b}Engineering 50{/b} and {b}level 10{/b}:"] = "Para entrenar más allá de 75, visita a uno de estos instructores y aprende Ingeniería de Oficial. Necesitas {b}Ingeniería 50{/b} y {b}nivel 10{/b}:",
  ["Undercity: {n:0:horde:Franklin Lloyd}"] = "Entrañas: {n:0:horde:Franklin Lloyd}",
  ["Stormwind City: {n:0:alliance:Lilliam Sparkspindle}"] = "Ventormenta: {n:0:alliance:Lilliam Sparkspindle}",
  ["Ironforge: {n:0:alliance:Trixie Quikswitch}"] = "Forjaz: {n:0:alliance:Trixie Quikswitch}",
  ["Duskwood: {n:0:alliance:Finbus Geargrind}"] = "Bosque del Ocaso: {n:0:alliance:Finbus Geargrind}",
  ["33x {s:3923:inv_misc_bomb_09:Rough Copper Bomb} - 33 Copper Bar, 33 Handful of Copper Bolts, 66 Rough Blasting Powder, 33 Linen Cloth"] = "33x {s:3923:inv_misc_bomb_09:Rough Copper Bomb} - 33 Barra de cobre, 33 Puñado de tornillos de cobre, 66 Polvo explosivo en bruto, 33 Paño de lino",
  ["{b}It's possible that you reach further than 75 with these{/b}, so it's best not to afk craft them unless you already learned Journeyman Engineering. Either make sure you learn it first, or just don't afk craft them. (Depends on luck, sometimes you don't even reach 75.)"] = "{b}Es posible que con estas pases de 75{/b}, así que es mejor no fabricarlas ausente (afk) a menos que ya hayas aprendido Ingeniería de Oficial. O te aseguras de aprenderla antes, o simplemente no las fabriques en afk. (Depende de la suerte, a veces ni siquiera llegas a 75.)",
  ["60x {s:3929:inv_misc_dust_02:Coarse Blasting Powder} - 60 Coarse Stone"] = "60x {s:3929:inv_misc_dust_02:Coarse Blasting Powder} - 60 Piedra basta",
  ["Keep them, you will need all 60 for the dynamite at 90."] = "Guárdalos, necesitarás los 60 para la dinamita de 90.",
  ["20x {s:3931:inv_misc_bomb_06:Coarse Dynamite} - 60 Coarse Blasting Powder, 20 Linen Cloth"] = "20x {s:3931:inv_misc_bomb_06:Coarse Dynamite} - 60 Polvo explosivo basto, 20 Paño de lino",
  ["5x {s:3973:inv_ingot_04:Silver Contact} - 5 Silver Bar"] = "5x {s:3973:inv_ingot_04:Silver Contact} - 5 Barra de plata",
  ["If Silver Bar is expensive, make this instead:"] = "Si la Barra de plata está cara, haz esto en su lugar:",
  ["5x {s:3934:inv_helmet_47:Flying Tiger Goggles} - 30 Light Leather, 10 Tigerseye."] = "5x {s:3934:inv_helmet_47:Flying Tiger Goggles} - 30 Cuero ligero, 10 Ojo de tigre.",
  ["25x {s:3938:inv_gizmo_pipe_01:Bronze Tube} - 50 Bronze Bar, 25 Weak Flux"] = "25x {s:3938:inv_gizmo_pipe_01:Bronze Tube} - 50 Barra de bronce, 25 Flujo débil",
  ["Keep 10 of them, you will need them at 125."] = "Guarda 10, los necesitarás en 125.",
  ["{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} is sold by Engineering Supply vendors near your trainer."] = "El {i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} lo venden los vendedores de suministros de ingeniería cerca de tu instructor.",
  ["If you end up a few points short of 125, don't make more tubes, just start the scopes."] = "Si te quedas a unos pocos puntos de 125, no hagas más tubos, empieza ya con las miras.",
  ["10x {s:3978:inv_misc_spyglass_02:Standard Scope} - 10 Bronze Tube, 10 Moss Agate"] = "10x {s:3978:inv_misc_spyglass_02:Standard Scope} - 10 Tubo de bronce, 10 Ágata musgosa",
  ["Start making {s:3945:inv_misc_dust_06:Heavy Blasting Powder} instead if you don't have any Moss Agate, or it's really expensive."] = "Empieza a hacer {s:3945:inv_misc_dust_06:Heavy Blasting Powder} en su lugar si no tienes Ágata musgosa o si está muy cara.",
  ["Make both of these:"] = "Haz estos dos:",
  ["30x {s:3945:inv_misc_dust_06:Heavy Blasting Powder} - 30 Heavy Stone"] = "30x {s:3945:inv_misc_dust_06:Heavy Blasting Powder} - 30 Piedra pesada",
  ["15x {s:3942:inv_gizmo_02:Whirring Bronze Gizmo} - 30 Bronze Bar, 15 Wool Cloth"] = "15x {s:3942:inv_gizmo_02:Whirring Bronze Gizmo} - 30 Barra de bronce, 15 Paño de lana",
  ["{b}Make sure to make them in the same order.{/b} You need both for the sheep at 160, so make them now and you should reach 150 with them."] = "{b}Asegúrate de hacerlos en este mismo orden.{/b} Necesitas ambos para las ovejas de 160, así que hazlos ahora; deberías llegar a 150 con ellos.",
  ["Expert Engineering (150-200)"] = "Ingeniería de Experto (150-200)",
  ["To train past 150, visit {n:0:horde:Roxxik} in Orgrimmar (Horde) or {n:0:alliance:Springspindle Fizzlegear} in Ironforge (Alliance) and learn Expert Engineering. You need {b}Engineering 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Para entrenar más allá de 150, visita a {n:0:horde:Roxxik} en Orgrimmar (Horda) o a {n:0:alliance:Springspindle Fizzlegear} en Forjaz (Alianza) y aprende Ingeniería de Experto. Necesitas {b}Ingeniería 125{/b} y {b}nivel 20{/b}, y cuesta 50 de plata.",
  ["15x {s:3953:inv_gizmo_bronzeframework_01:Bronze Framework} - 30 Bronze Bar, 15 Medium Leather, 15 Wool Cloth"] = "15x {s:3953:inv_gizmo_bronzeframework_01:Bronze Framework} - 30 Barra de bronce, 15 Cuero medio, 15 Paño de lana",
  ["Keep these too, you will need all 15 for the sheep."] = "Guarda también estos, necesitarás los 15 para las ovejas.",
  ["The 15 will probably take you past 160, that's fine."] = "Probablemente los 15 te lleven más allá de 160, no pasa nada.",
  ["15x {s:3955:spell_nature_polymorph:Explosive Sheep} - 30 Heavy Blasting Powder, 15 Whirring Bronze Gizmo, 15 Bronze Framework, 30 Wool Cloth"] = "15x {s:3955:spell_nature_polymorph:Explosive Sheep} - 30 Polvo explosivo pesado, 15 Artilugio de bronce zumbador, 15 Armazón de bronce, 30 Paño de lana",
  ["Keep 5 of them, you might need them if you choose Goblin Engineering at 200."] = "Guarda 5, puede que las necesites si eliges Ingeniería goblin en 200.",
  ["60x {s:12585:inv_misc_powder_black:Solid Blasting Powder} - 120 Solid Stone"] = "60x {s:12585:inv_misc_powder_black:Solid Blasting Powder} - 120 Piedra sólida",
  ["Save these, you will need them later."] = "Guárdalos, los necesitarás más adelante.",
  ["1x {s:12590:inv_misc_screwdriver_02:Gyromatic Micro-Adjustor} - 4 Steel Bar"] = "1x {s:12590:inv_misc_screwdriver_02:Gyromatic Micro-Adjustor} - 4 Barra de acero",
  ["Keep this, you will need it to craft some of the Engineering recipes."] = "Guárdalo, lo necesitarás para fabricar algunas recetas de Ingeniería.",
  ["If you were unlucky with the skill points and didn't reach 195, craft a few {s:3962:inv_misc_bomb_08:Iron Grenade} or any other recipe that gives skill points."] = "Si tuviste mala suerte con los puntos de habilidad y no llegaste a 195, fabrica unas cuantas {s:3962:inv_misc_bomb_08:Iron Grenade} o cualquier otra receta que dé puntos de habilidad.",
  ["6x {s:12589:inv_musket_01:Mithril Tube} - 18 Mithril Bar"] = "6x {s:12589:inv_musket_01:Mithril Tube} - 18 Barra de mitril",
  ["Keep all 6, you might need them if you choose Gnomish Engineering at 200."] = "Guarda los 6, puede que los necesites si eliges Ingeniería gnómica en 200.",
  ["Engineering Specializations"] = "Especializaciones de Ingeniería",
  ["At {b}Engineering 200{/b} and {b}level 30{/b}, you can specialize in Gnomish or Goblin Engineering. Some items require a specific specialization to use, while other items are crafted by one specialization but are usable by any engineer. Fortunately, most recipes that are crafted by one specialization can be used by both."] = "Con {b}Ingeniería 200{/b} y {b}nivel 30{/b} puedes especializarte en Ingeniería gnómica o goblin. Algunos objetos requieren una especialización concreta para usarlos, mientras que otros los fabrica una especialización pero los puede usar cualquier ingeniero. Por suerte, la mayoría de las recetas que fabrica una especialización las pueden usar ambas.",
  ["For information on how to choose a specialization, please see my separate guide:"] = "Para saber cómo elegir una especialización, consulta mi guía aparte:",
  ["Artisan Engineering (200-300)"] = "Ingeniería de Artesano (200-300)",
  ["To train Engineering past 225 you need {b}Engineering 200{/b} and {b}level 35{/b}, then learn Artisan Engineering from {n:0::Buzzek Bracketswing} in Tanaris at Gadgetzan, he is right outside the inn near the mailbox. He also teaches the recipes above 200, so go there as soon as you reach 200."] = "Para entrenar Ingeniería más allá de 225 necesitas {b}Ingeniería 200{/b} y {b}nivel 35{/b}; después aprende Ingeniería de Artesano con {n:0::Buzzek Bracketswing} en Gadgetzan, Tanaris, que está justo fuera de la posada cerca del buzón. También enseña las recetas por encima de 200, así que ve en cuanto llegues a 200.",
  ["20x {s:12591:inv_battery_01:Unstable Trigger} - 20 Mithril Bar, 20 Mageweave Cloth, 20 Solid Blasting Powder"] = "20x {s:12591:inv_battery_01:Unstable Trigger} - 20 Barra de mitril, 20 Paño de tejido mágico, 20 Polvo explosivo sólido",
  ["Keep them, you will need all 20 for the bombs at 238."] = "Guárdalos, necesitarás los 20 para las bombas de 238.",
  ["40x {s:12599:inv_gizmo_mithrilcasing_01:Mithril Casing} - 120 Mithril Bar"] = "40x {s:12599:inv_gizmo_mithrilcasing_01:Mithril Casing} - 120 Barra de mitril",
  ["Keep these too, you will need 40 for the bombs."] = "Guarda también estas, necesitarás 40 para las bombas.",
  ["20x {s:12619:inv_misc_bomb_07:Hi-Explosive Bomb} - 40 Mithril Casing, 20 Unstable Trigger, 40 Solid Blasting Powder"] = "20x {s:12619:inv_misc_bomb_07:Hi-Explosive Bomb} - 40 Cubierta de mitril, 20 Gatillo inestable, 40 Polvo explosivo sólido",
  ["44x {s:19788:inv_misc_ammo_gunpowder_01:Dense Blasting Powder} - 88 Dense Stone"] = "44x {s:19788:inv_misc_ammo_gunpowder_01:Dense Blasting Powder} - 88 Piedra densa",
  ["35x {s:19791:inv_gizmo_04:Thorium Widget} - 105 Thorium Bar, 35 Runecloth"] = "35x {s:19791:inv_gizmo_04:Thorium Widget} - 105 Barra de torio, 35 Paño rúnico",
  ["{i:16042:inv_scroll_03:Schematic: Thorium Widget} is sold by {n:0:horde:Sovik} in Orgrimmar and {n:0:alliance:Gearcutter Cogspinner} in Ironforge."] = "{i:16042:inv_scroll_03:Schematic: Thorium Widget} lo venden {n:0:horde:Sovik} en Orgrimmar y {n:0:alliance:Gearcutter Cogspinner} en Forjaz.",
  ["20x {s:19795:inv_gizmo_pipe_04:Thorium Tube} - 120 Thorium Bar"] = "20x {s:19795:inv_gizmo_pipe_04:Thorium Tube} - 120 Barra de torio",
  ["{i:16047:inv_scroll_03:Schematic: Thorium Tube} is sold by {n:0::Xizzer Fizzbolt} in Winterspring at Everlook, in the first building on the right after the gate. It's bind on pickup in Forever, so buy it with the character that levels Engineering."] = "{i:16047:inv_scroll_03:Schematic: Thorium Tube} lo vende {n:0::Xizzer Fizzbolt} en Vista Eterna, Cuna del Invierno, en el primer edificio a la derecha tras la puerta. En Forever se liga al recogerlo, así que cómpralo con el personaje que sube Ingeniería.",
  ["This WoW Forever Leatherworking leveling guide will show you the fastest and cheapest way to level your Leatherworking skill from 1 to 300. You will also find every trainer location and where to train Leatherworking past 75, 150 and 225."] = "Esta guía de Peletería para WoW Forever te mostrará la forma más rápida y barata de subir tu habilidad de Peletería de 1 a 300. También encontrarás la ubicación de todos los instructores y dónde aprender Peletería más allá de 75, 150 y 225.",
  ["Below you will find the full shopping list, the Leatherworking trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Leatherworking is best combined with Skinning because leather is most of the cost, but you can also buy everything in the guide from the Auction House."] = "A continuación encontrarás la lista de la compra completa, los instructores de Peletería por zona inicial y capital, y las recetas más baratas para cada rango de habilidad, de Aprendiz a Artesano. La Peletería combina mejor con Desuello porque el cuero es la mayor parte del coste, pero también puedes comprar todo lo de la guía en la casa de subastas.",
  ["When a recipe is yellow or green, a craft doesn't always give you a skill point, so nobody can tell exactly how many materials you will need. That's why the counts that depend a lot on luck are a range. {b}With the bigger number 9 out of 10 players have enough, with the smaller one it's 50/50.{/b} If you buy the smaller number, be ready to buy more later."] = "Cuando una receta está en amarillo o verde, una creación no siempre te da un punto de habilidad, así que nadie puede saber exactamente cuántos materiales necesitarás. Por eso las cantidades que dependen mucho de la suerte se dan como un rango. {b}Con la cifra más alta, 9 de cada 10 jugadores tienen suficiente; con la más baja, es 50/50.{/b} Si compras la cifra más baja, prepárate para comprar más después.",
  ["Leatherworking Trainer Locations"] = "Ubicación de los instructores de Peletería",
  ["Apprentice Leatherworking has no level requirement in Forever, so you can learn it on a fresh character."] = "Peletería de Aprendiz no tiene requisito de nivel en Forever, así que puedes aprenderla con un personaje recién creado.",
  ["Undercity: {n:0:horde:Dan Golthas}"] = "Entrañas: {n:0:horde:Dan Golthas}",
  ["Thunder Bluff: {n:0:horde:Mak}"] = "Cima del Trueno: {n:0:horde:Mak}",
  ["There is no Leatherworking trainer in Durotar, go to {n:0:horde:Kamari} in the Drag in Orgrimmar"] = "No hay instructor de Peletería en Durotar, ve a ver a {n:0:horde:Kamari} en El Arrastre de Orgrimmar",
  ["{n:0:horde:Chaw Stronghide} in Bloodhoof Village"] = "{n:0:horde:Chaw Stronghide} en el Poblado Pezuña de Sangre",
  ["{n:0:horde:Shelene Rhobart} at the road junction southeast of Brill"] = "{n:0:horde:Shelene Rhobart} en el cruce de caminos al sureste de Rémol",
  ["{n:0::Emerii Tallgust} in Valanaar, {n:0::Indari Sunseam} in Shen'dar Village"] = "{n:0::Emerii Tallgust} en Valanaar, {n:0::Indari Sunseam} en la Aldea Shen'dar",
  ["Stormwind City: {n:0:alliance:Randal Worth}"] = "Ventormenta: {n:0:alliance:Randal Worth}",
  ["Ironforge: {n:0:alliance:Gretta Finespindle}"] = "Forjaz: {n:0:alliance:Gretta Finespindle}",
  ["{n:0:alliance:Adele Fielder} in the small house by Crystal Lake, northeast of Goldshire"] = "{n:0:alliance:Adele Fielder} en la casita junto al Lago de Cristal, al noreste de Villadorada",
  ["There is no Leatherworking trainer in Dun Morogh, go to {n:0:alliance:Gretta Finespindle} at the Great Forge in Ironforge"] = "No hay instructor de Peletería en Dun Morogh, ve a ver a {n:0:alliance:Gretta Finespindle} en La Gran Fundición de Forjaz",
  ["{n:0:alliance:Nadyia Maneweaver} in the small house near the road to Darnassus"] = "{n:0:alliance:Nadyia Maneweaver} en la casita cerca del camino a Darnassus",
  ["You can find every Leatherworking trainer for Horde and Alliance on my WoW Forever Leatherworking Trainers page."] = "Puedes encontrar todos los instructores de Peletería de la Horda y la Alianza en mi página de instructores de Peletería de WoW Forever.",
  ["Apprentice Leatherworking (1-55)"] = "Peletería de Aprendiz (1-55)",
  ["35x {s:2881:inv_misc_leatherscrap_03:Light Leather} - 105 Ruined Leather Scraps"] = "35x {s:2881:inv_misc_leatherscrap_03:Light Leather} - 105 Restos de cuero estropeado",
  ["27x {s:3816:inv_misc_pelt_wolf_01:Cured Light Hide} - 27 Light Hide, 27 Salt"] = "27x {s:3816:inv_misc_pelt_wolf_01:Cured Light Hide} - 27 Pellejo ligero, 27 Sal",
  ["{b}NOTE:{/b} {b}Most trainers{/b} have a Leatherworking Supply vendor nearby that sells the threads, dyes, and salt, {b}except{/b} the trainers in Elwynn Forest and Tirisfal Glades. For those, buy the Salt and Coarse Thread in Goldshire from {n:0:alliance:Tharynn Bouden} or in Brill from {n:0:horde:Abigail Shiel}."] = "{b}NOTA:{/b} {b}La mayoría de los instructores{/b} tienen cerca un vendedor de suministros de peletería que vende los hilos, tintes y sal, {b}excepto{/b} los instructores del Bosque de Elwynn y de los Claros de Tirisfal. Para esos, compra la Sal y el Hilo basto en Villadorada a {n:0:alliance:Tharynn Bouden} o en Rémol a {n:0:horde:Abigail Shiel}.",
  ["Keep 24 of the hides, you will need them for the Light Leather Pants at 100."] = "Guarda 24 pellejos, los necesitarás para los Pantalones de cuero ligero en 100.",
  ["Alternative recipes"] = "Recetas alternativas",
  ["If you farm your own leather and don't have 27 Light Hides, make Light Armor Kits until 45, then Embossed Leather Gloves until 55:"] = "Si consigues tu propio cuero y no tienes 27 Pellejos ligeros, haz Kits de armadura ligera hasta 45 y luego Guantes de cuero repujado hasta 55:",
  ["24x {s:2152:inv_misc_armorkit_17:Light Armor Kit} - 24 Light Leather"] = "24x {s:2152:inv_misc_armorkit_17:Light Armor Kit} - 24 Cuero ligero",
  ["10x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 30 Light Leather, 20 Coarse Thread"] = "10x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 30 Cuero ligero, 20 Hilo basto",
  ["You still need 24 Cured Light Hide for the Light Leather Pants at 100, so keep the Light Hides you skin until then."] = "Aun así necesitas 24 Pellejo ligero curtido para los Pantalones de cuero ligero en 100, así que guarda los Pellejos ligeros que desuelles hasta entonces.",
  ["Journeyman Leatherworking (55-130)"] = "Peletería de Oficial (55-130)",
  ["To train past 75, visit one of these trainers and learn Journeyman Leatherworking. You need {b}Leatherworking 50{/b} and {b}level 10{/b}:"] = "Para entrenar más allá de 75, visita a uno de estos instructores y aprende Peletería de Oficial. Necesitas {b}Peletería 50{/b} y {b}nivel 10{/b}:",
  ["Undercity: {n:0:horde:Arthur Moore}"] = "Entrañas: {n:0:horde:Arthur Moore}",
  ["Thunder Bluff: {n:0:horde:Tarn}"] = "Cima del Trueno: {n:0:horde:Tarn}",
  ["Stormwind City: {n:0:alliance:Simon Tanner}"] = "Ventormenta: {n:0:alliance:Simon Tanner}",
  ["Ironforge: {n:0:alliance:Fimble Finespindle}"] = "Forjaz: {n:0:alliance:Fimble Finespindle}",
  ["21x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 63 Light Leather, 42 Coarse Thread"] = "21x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 63 Cuero ligero, 42 Hilo basto",
  ["8x {s:20648:inv_misc_leatherscrap_05:Medium Leather} - 32 Light Leather"] = "8x {s:20648:inv_misc_leatherscrap_05:Medium Leather} - 32 Cuero ligero",
  ["10x {s:3817:inv_misc_pelt_bear_02:Cured Medium Hide} - 10 Medium Hide, 10 Salt"] = "10x {s:3817:inv_misc_pelt_bear_02:Cured Medium Hide} - 10 Pellejo medio, 10 Sal",
  ["Keep the Cured Medium Hides, you will need them for the Dark Leather Belts at 115."] = "Guarda los Pellejos medios curtidos, los necesitarás para los Cinturones de cuero oscuro en 115.",
  ["19x {s:3763:inv_belt_04:Fine Leather Belt} - 114 Light Leather, 38 Coarse Thread"] = "19x {s:3763:inv_belt_04:Fine Leather Belt} - 114 Cuero ligero, 38 Hilo basto",
  ["Keep 10 of the belts for the Dark Leather Belts at 115."] = "Guarda 10 cinturones para los Cinturones de cuero oscuro en 115.",
  ["24x {s:9068:inv_pants_02:Light Leather Pants} - 240 Light Leather, 24 Cured Light Hide, 24 Fine Thread"] = "24x {s:9068:inv_pants_02:Light Leather Pants} - 240 Cuero ligero, 24 Pellejo ligero curtido, 24 Hilo fino",
  ["10x {s:3766:inv_belt_03:Dark Leather Belt} - 10 Fine Leather Belt, 10 Cured Medium Hide, 20 Fine Thread, 10 Gray Dye"] = "10x {s:3766:inv_belt_03:Dark Leather Belt} - 10 Cinturón de cuero fino, 10 Pellejo medio curtido, 20 Hilo fino, 10 Tinte gris",
  ["7x {s:20649:inv_misc_leatherscrap_07:Heavy Leather} - 35 Medium Leather"] = "7x {s:20649:inv_misc_leatherscrap_07:Heavy Leather} - 35 Cuero medio",
  ["Expert Leatherworking (130-205)"] = "Peletería de Experto (130-205)",
  ["To train past 150, visit {n:0:horde:Una} in Thunder Bluff (Horde) or {n:0:alliance:Telonis} in Darnassus (Alliance) and learn Expert Leatherworking. You need {b}Leatherworking 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Para entrenar más allá de 150, visita a {n:0:horde:Una} en Cima del Trueno (Horda) o a {n:0:alliance:Telonis} en Darnassus (Alianza) y aprende Peletería de Experto. Necesitas {b}Peletería 125{/b} y {b}nivel 20{/b}, y cuesta 50 de plata.",
  ["30x {s:3818:inv_misc_pelt_wolf_02:Cured Heavy Hide} - 30 Heavy Hide, 90 Salt"] = "30x {s:3818:inv_misc_pelt_wolf_02:Cured Heavy Hide} - 30 Pellejo pesado, 90 Sal",
  ["Keep the Cured Heavy Hides, you will need 10 for the Barbaric Shoulders at 155 and 20 for the Guardian Gloves at 165."] = "Guarda los Pellejos pesados curtidos, necesitarás 10 para las Hombreras bárbaras en 155 y 20 para los Guantes de guardián en 165.",
  ["17x {s:3764:inv_gauntlets_05:Hillman's Leather Gloves} - 238 Medium Leather, 68 Fine Thread"] = "17x {s:3764:inv_gauntlets_05:Hillman's Leather Gloves} - 238 Cuero medio, 68 Hilo fino",
  ["10x {s:7151:inv_shoulder_08:Barbaric Shoulders} - 80 Heavy Leather, 10 Cured Heavy Hide, 20 Fine Thread"] = "10x {s:7151:inv_shoulder_08:Barbaric Shoulders} - 80 Cuero pesado, 10 Pellejo pesado curtido, 20 Hilo fino",
  ["20x {s:7156:inv_gauntlets_05:Guardian Gloves} - 80 Heavy Leather, 20 Cured Heavy Hide, 20 Silken Thread"] = "20x {s:7156:inv_gauntlets_05:Guardian Gloves} - 80 Cuero pesado, 20 Pellejo pesado curtido, 20 Hilo de seda",
  ["22x {s:10507:inv_belt_24:Nightscape Headband} - 110 Thick Leather, 44 Silken Thread"] = "22x {s:10507:inv_belt_24:Nightscape Headband} - 110 Cuero grueso, 44 Hilo de seda",
  ["Leatherworking Specializations"] = "Especializaciones de Peletería",
  ["Once you reach {b}Leatherworking 225{/b} and {b}level 40{/b}, you can choose one of the three Leatherworking specializations: Dragonscale, Elemental, or Tribal. Each specialization gives access to a specific set of patterns."] = "Cuando llegues a {b}Peletería 225{/b} y {b}nivel 40{/b}, puedes elegir una de las tres especializaciones de Peletería: Escamas de dragón, Elemental o Tribal. Cada especialización da acceso a un conjunto concreto de patrones.",
  ["Dragonscale - Mail-type gear"] = "Escamas de dragón - equipo de malla",
  ["Elemental - elemental resistance and Leather-type agility gear"] = "Elemental - equipo de resistencia elemental y de cuero con agilidad",
  ["Tribal - Leather-type intellect & agility gear and the Devilsaur Armor set"] = "Tribal - equipo de cuero con intelecto y agilidad y el conjunto Armadura de demosaurio",
  ["For information on how to become a Dragonscale, Elemental, or Tribal Leatherworker, please see my separate guides:"] = "Para saber cómo convertirte en peletero de escamas de dragón, elemental o tribal, consulta mis guías aparte:",
  ["Artisan Leatherworking (205-300)"] = "Peletería de Artesano (205-300)",
  ["To train past 225, visit {n:0:horde:Hahrana Ironhide} in Camp Mojache, Feralas (Horde) or {n:0:alliance:Drakk Stonehand} in Aerie Peak, The Hinterlands (Alliance) and learn Artisan Leatherworking. You need {b}Leatherworking 200{/b} and {b}level 35{/b}."] = "Para entrenar más allá de 225, visita a {n:0:horde:Hahrana Ironhide} en el Campamento Mojache, Feralas (Horda) o a {n:0:alliance:Drakk Stonehand} en Pico Nidal, Tierras del Interior (Alianza) y aprende Peletería de Artesano. Necesitas {b}Peletería 200{/b} y {b}nivel 35{/b}.",
  ["36x {s:10548:inv_pants_11:Nightscape Pants} - 504 Thick Leather, 144 Silken Thread"] = "36x {s:10548:inv_pants_11:Nightscape Pants} - 504 Cuero grueso, 144 Hilo de seda",
  ["{b}The Expert trainers in Thunder Bluff and Darnassus don't teach this recipe{/b}, you can only learn it from the two trainers above."] = "{b}Los instructores de Experto de Cima del Trueno y Darnassus no enseñan esta receta{/b}, solo puedes aprenderla con los dos instructores de arriba.",
  ["I recommend these over the Nightscape Boots because they sell for more to a vendor, so they end up cheaper."] = "Te recomiendo estos en lugar de las Botas de paisaje nocturno porque se venden por más a un vendedor, así que al final salen más baratos.",
  ["36x {s:19049:inv_gauntlets_31:Wicked Leather Gauntlets} - 288 Rugged Leather, 36 Black Dye, 36 Rune Thread"] = "36x {s:19049:inv_gauntlets_31:Wicked Leather Gauntlets} - 288 Cuero basto, 36 Tinte negro, 36 Hilo rúnico",
  ["The pattern is sold by {n:0:horde:Werg Thickblade} in Tirisfal Glades (Horde) and {n:0:alliance:Leonard Porter} in Western Plaguelands (Alliance)."] = "El patrón lo venden {n:0:horde:Werg Thickblade} en los Claros de Tirisfal (Horda) y {n:0:alliance:Leonard Porter} en las Tierras de la Peste del Oeste (Alianza).",
  ["Blue Suede Shoes use the same leather but sell for more to a vendor, so they save you about 13 gold on this step. If the pattern costs less than that on the Auction House, make these instead:"] = "Los Zapatos de ante azul usan el mismo cuero pero se venden por más a un vendedor, así que te ahorran unos 13 de oro en este paso. Si el patrón cuesta menos que eso en la casa de subastas, haz estos en su lugar:",
  ["36x {s:1255048:inv_boots_leather_12:Blue Suede Shoes} - 288 Rugged Leather, 36 Blue Dye, 36 Rune Thread."] = "36x {s:1255048:inv_boots_leather_12:Blue Suede Shoes} - 288 Cuero basto, 36 Tinte azul, 36 Hilo rúnico.",
  ["53x {s:19082:inv_misc_bandage_11:Runic Leather Headband} - 742 Rugged Leather, 530 Runecloth, 53 Rune Thread"] = "53x {s:19082:inv_misc_bandage_11:Runic Leather Headband} - 742 Cuero basto, 530 Paño rúnico, 53 Hilo rúnico",
  ["The pattern is sold by {n:0::Jase Farlane} at Light's Hope Chapel in Eastern Plaguelands."] = "El patrón lo vende {n:0::Jase Farlane} en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.",
  ["If you have the pattern, make these from 275 instead:"] = "Si tienes el patrón, haz estos a partir de 275:",
  ["27x {s:1255019:inv_bracer_22a:Blue Suede Bracers} - 270 Rugged Leather, 27 Blue Dye, 27 Rune Thread."] = "27x {s:1255019:inv_bracer_22a:Blue Suede Bracers} - 270 Cuero basto, 27 Tinte azul, 27 Hilo rúnico.",
  ["Blue Suede Hat"] = "Sombrero de ante azul",
  ["{b}Someone with Leatherworking 300 has to place the Sewing Machine for you.{/b} You can't place a Sewing Machine yourself before 300, even if you buy one. I'm not sure if this is an oversight by Blizzard, so they might change it."] = "{b}Alguien con Peletería 300 tiene que colocarte la Máquina de coser.{/b} No puedes colocar una Máquina de coser tú mismo antes de 300, aunque la compres. No sé si es un descuido de Blizzard, así que puede que lo cambien.",
  ["If you can use one and have the pattern, you can make these from 280:"] = "Si puedes usar una y tienes el patrón, puedes hacer estos a partir de 280:",
  ["20x {s:1255017:inv_helm_armor_buckledhat_b_01_blue:Blue Suede Hat} - 320 Rugged Leather, 80 Blue Dye, 20 Rune Thread."] = "20x {s:1255017:inv_helm_armor_buckledhat_b_01_blue:Blue Suede Hat} - 320 Cuero basto, 80 Tinte azul, 20 Hilo rúnico.",
  ["This WoW Forever Tailoring leveling guide will show you the fastest and cheapest way to level your Tailoring skill from 1 to 300. You will also find every trainer location and where to train Tailoring past 75, 150 and 225."] = "Esta guía de Sastrería para WoW Forever te mostrará la forma más rápida y barata de subir tu habilidad de Sastrería de 1 a 300. También encontrarás la ubicación de todos los instructores y dónde aprender Sastrería más allá de 75, 150 y 225.",
  ["Below you will find the full shopping list, the Tailoring trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Tailoring uses cloth as its main material, but cloth drops from humanoids, so you don't need a gathering profession and you can combine Tailoring with anything. Enchanting is a popular choice because you can disenchant the things you make while leveling and use the dust to level Enchanting."] = "A continuación encontrarás la lista de la compra completa, los instructores de Sastrería por zona inicial y capital, y las recetas más baratas para cada rango de habilidad, de Aprendiz a Artesano. La Sastrería usa paño como material principal, pero el paño lo sueltan los humanoides, así que no necesitas una profesión de recolección y puedes combinar Sastrería con cualquier cosa. Encantamiento es una opción popular porque puedes desencantar lo que fabricas mientras subes y usar el polvo para subir Encantamiento.",
  ["{b}NOTE:{/b} {b}Most trainers{/b} have a Tailoring Supply vendor nearby that sells the threads and dyes, {b}except{/b} the trainer in Tirisfal Glades. For that one, buy the Coarse Thread in Brill from {n:0:horde:Abigail Shiel}."] = "{b}NOTA:{/b} {b}La mayoría de los instructores{/b} tienen cerca un vendedor de suministros de sastrería que vende los hilos y tintes, {b}excepto{/b} el instructor de los Claros de Tirisfal. Para ese, compra el Hilo basto en Rémol a {n:0:horde:Abigail Shiel}.",
  ["Alternative (if cheaper)"] = "Alternativa (si es más barata)",
  ["This list is not final yet, but the skill ranges come from the game data, so it should be pretty close. The 280-300 part is not included here yet."] = "Esta lista aún no es definitiva, pero los rangos de habilidad salen de los datos del juego, así que debería ser bastante aproximada. La parte 280-300 aún no está incluida aquí.",
  ["Tailoring Trainer Locations"] = "Ubicación de los instructores de Sastrería",
  ["Apprentice Tailoring has no level requirement in Forever, so you can learn it on a fresh character."] = "Sastrería de Aprendiz no tiene requisito de nivel en Forever, así que puedes aprenderla con un personaje recién creado.",
  ["Undercity: {n:0:horde:Victor Ward}"] = "Entrañas: {n:0:horde:Victor Ward}",
  ["Thunder Bluff: {n:0:horde:Vhan}"] = "Cima del Trueno: {n:0:horde:Vhan}",
  ["There is no Tailoring trainer in Durotar, go to {n:0:horde:Snang} in the Drag in Orgrimmar"] = "No hay instructor de Sastrería en Durotar, ve a ver a {n:0:horde:Snang} en El Arrastre de Orgrimmar",
  ["There is no Tailoring trainer in Mulgore, go to {n:0:horde:Vhan} on the middle rise in Thunder Bluff"] = "No hay instructor de Sastrería en Mulgore, ve a ver a {n:0:horde:Vhan} en la meseta central de Cima del Trueno",
  ["{n:0:horde:Bowen Brisboise} in the small house at Cold Hearth Manor, southwest of Brill"] = "{n:0:horde:Bowen Brisboise} en la casita de la Mansión Corazón Frío, al suroeste de Rémol",
  ["{n:0::Othesia Evengale} in Valanaar, {n:0::Taleen Shimmerthread} in Shen'dar Village"] = "{n:0::Othesia Evengale} en Valanaar, {n:0::Taleen Shimmerthread} en la Aldea Shen'dar",
  ["Stormwind City: {n:0:alliance:Lawrence Schneider}"] = "Ventormenta: {n:0:alliance:Lawrence Schneider}",
  ["Ironforge: {n:0:alliance:Uthrar Threx}"] = "Forjaz: {n:0:alliance:Uthrar Threx}",
  ["{n:0:alliance:Eldrin} in a house at the Eastvale Logging Camp"] = "{n:0:alliance:Eldrin} en una casa del Aserradero del Valle del Este",
  ["There is no Tailoring trainer in Dun Morogh, go to {n:0:alliance:Uthrar Threx} at the Great Forge in Ironforge"] = "No hay instructor de Sastrería en Dun Morogh, ve a ver a {n:0:alliance:Uthrar Threx} en La Gran Fundición de Forjaz",
  ["There is no Tailoring trainer in Teldrassil, go to {n:0:alliance:Trianna} at the Craftsmen's Terrace in Darnassus"] = "No hay instructor de Sastrería en Teldrassil, ve a ver a {n:0:alliance:Trianna} en el Bancal del Artesano de Darnassus",
  ["You can find every Tailoring trainer for Horde and Alliance on my WoW Forever Tailoring Trainers page."] = "Puedes encontrar todos los instructores de Sastrería de la Horda y la Alianza en mi página de instructores de Sastrería de WoW Forever.",
  ["Apprentice Tailoring (1-55)"] = "Sastrería de Aprendiz (1-55)",
  ["30x {s:2963:inv_fabric_linen_02:Bolt of Linen Cloth} - 60 Linen Cloth"] = "30x {s:2963:inv_fabric_linen_02:Bolt of Linen Cloth} - 60 Paño de lino",
  ["Keep the bolts, you need all of them for the belts."] = "Guarda los rollos, los necesitas todos para los cinturones.",
  ["28x {s:8776:inv_belt_05:Linen Belt} - 28 Bolt of Linen Cloth, 28 Coarse Thread"] = "28x {s:8776:inv_belt_05:Linen Belt} - 28 Rollo de paño de lino, 28 Hilo basto",
  ["Journeyman Tailoring (55-140)"] = "Sastrería de Oficial (55-140)",
  ["To train past 75, visit one of these trainers and learn Journeyman Tailoring. You need {b}Tailoring 50{/b} and {b}level 10{/b}:"] = "Para entrenar más allá de 75, visita a uno de estos instructores y aprende Sastrería de Oficial. Necesitas {b}Sastrería 50{/b} y {b}nivel 10{/b}:",
  ["Undercity: {n:0:horde:Rhiannon Davis}"] = "Entrañas: {n:0:horde:Rhiannon Davis}",
  ["Thunder Bluff: {n:0:horde:Tepa}"] = "Cima del Trueno: {n:0:horde:Tepa}",
  ["Stormwind City: {n:0:alliance:Sellandus}"] = "Ventormenta: {n:0:alliance:Sellandus}",
  ["Ironforge: {n:0:alliance:Jormund Stonebrow}"] = "Forjaz: {n:0:alliance:Jormund Stonebrow}",
  ["{b}Learn Journeyman Tailoring before you make these.{/b} You can reach past 75 with them, but you won't get any skill points above 75 until you learn it, so don't go AFK while crafting before you have it."] = "{b}Aprende Sastrería de Oficial antes de hacer estos.{/b} Puedes pasar de 75 con ellos, pero no obtendrás puntos de habilidad por encima de 75 hasta que la aprendas, así que no te pongas AFK fabricando antes de tenerla.",
  ["45x {s:2964:inv_fabric_wool_03:Bolt of Woolen Cloth} - 135 Wool Cloth"] = "45x {s:2964:inv_fabric_wool_03:Bolt of Woolen Cloth} - 135 Paño de lana",
  ["Keep the bolts, you will need them later. In total you will need 153 {i:2997:inv_fabric_wool_03:Bolt of Woolen Cloth} (459 {i:2592:inv_fabric_wool_01:Wool Cloth}) until 140, so you can also make all of them now."] = "Guarda los rollos, los necesitarás más adelante. En total necesitarás 153 {i:2997:inv_fabric_wool_03:Bolt of Woolen Cloth} (459 {i:2592:inv_fabric_wool_01:Wool Cloth}) hasta 140, así que también puedes hacerlos todos ahora.",
  ["22x {s:2402:inv_misc_cape_10:Woolen Cape} - 22 Bolt of Woolen Cloth, 22 Fine Thread"] = "22x {s:2402:inv_misc_cape_10:Woolen Cape} - 22 Rollo de paño de lana, 22 Hilo fino",
  ["If the bolts already took you past 80, just make capes until 95."] = "Si los rollos ya te llevaron más allá de 80, haz capas hasta 95.",
  ["5x {s:3848:inv_shoulder_06:Double-stitched Woolen Shoulders} - 15 Bolt of Woolen Cloth, 10 Fine Thread"] = "5x {s:3848:inv_shoulder_06:Double-stitched Woolen Shoulders} - 15 Rollo de paño de lana, 10 Hilo fino",
  ["54x {s:3839:inv_fabric_silk_03:Bolt of Silk Cloth} - 216 Silk Cloth"] = "54x {s:3839:inv_fabric_silk_03:Bolt of Silk Cloth} - 216 Paño de seda",
  ["Keep the bolts, you will need them later. In total you will need 184 {i:4305:inv_fabric_silk_03:Bolt of Silk Cloth} (736 {i:4306:inv_fabric_silk_01:Silk Cloth}) until 190, so you can also make all of them now."] = "Guarda los rollos, los necesitarás más adelante. En total necesitarás 184 {i:4305:inv_fabric_silk_03:Bolt of Silk Cloth} (736 {i:4306:inv_fabric_silk_01:Silk Cloth}) hasta 190, así que también puedes hacerlos todos ahora.",
  ["29x {s:3852:inv_gauntlets_05:Gloves of Meditation} - 116 Bolt of Woolen Cloth, 87 Fine Thread, 29 Elixir of Wisdom"] = "29x {s:3852:inv_gauntlets_05:Gloves of Meditation} - 116 Rollo de paño de lana, 87 Hilo fino, 29 Elixir de sabiduría",
  ["You can buy {i:3383:inv_potion_06:Elixir of Wisdom} from the Auction House or ask an Alchemist."] = "Puedes comprar el {i:3383:inv_potion_06:Elixir of Wisdom} en la casa de subastas o pedírselo a un alquimista.",
  ["Expert Tailoring (140-200)"] = "Sastrería de Experto (140-200)",
  ["To train past 150, visit {n:0:horde:Josef Gregorian} in Undercity (Horde) or {n:0:alliance:Georgio Bolero} in Stormwind City (Alliance) and learn Expert Tailoring. You need {b}Tailoring 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Para entrenar más allá de 150, visita a {n:0:horde:Josef Gregorian} en Entrañas (Horda) o a {n:0:alliance:Georgio Bolero} en Ventormenta (Alianza) y aprende Sastrería de Experto. Necesitas {b}Sastrería 125{/b} y {b}nivel 20{/b}, y cuesta 50 de plata.",
  ["23x {s:3865:inv_fabric_mageweave_03:Bolt of Mageweave} - 115 Mageweave Cloth"] = "23x {s:3865:inv_fabric_mageweave_03:Bolt of Mageweave} - 115 Paño de tejido mágico",
  ["Keep the bolts, you will need them later. In total you will need 157 {i:4339:inv_fabric_mageweave_03:Bolt of Mageweave} (785 {i:4338:inv_fabric_mageweave_01:Mageweave Cloth}) until 225, so you can also make all of them now."] = "Guarda los rollos, los necesitarás más adelante. En total necesitarás 157 {i:4339:inv_fabric_mageweave_03:Bolt of Mageweave} (785 {i:4338:inv_fabric_mageweave_01:Mageweave Cloth}) hasta 225, así que también puedes hacerlos todos ahora.",
  ["20x {s:8791:inv_shirt_04:Crimson Silk Vest} - 80 Bolt of Silk Cloth, 40 Red Dye, 40 Fine Thread"] = "20x {s:8791:inv_shirt_04:Crimson Silk Vest} - 80 Rollo de paño de seda, 40 Tinte rojo, 40 Hilo fino",
  ["26x {s:8799:inv_pants_06:Crimson Silk Pantaloons} - 104 Bolt of Silk Cloth, 52 Red Dye, 52 Silken Thread"] = "26x {s:8799:inv_pants_06:Crimson Silk Pantaloons} - 104 Rollo de paño de seda, 52 Tinte rojo, 52 Hilo de seda",
  ["19x {s:12049:inv_pants_09:Black Mageweave Leggings} - 38 Bolt of Mageweave, 57 Silken Thread"] = "19x {s:12049:inv_pants_09:Black Mageweave Leggings} - 38 Rollo de tejido mágico, 57 Hilo de seda",
  ["Artisan Tailoring (200-300)"] = "Sastrería de Artesano (200-300)",
  ["To train past 225, visit {n:0:horde:Daryl Stack} in Tarren Mill, Hillsbrad Foothills (Horde) or {n:0:alliance:Timothy Worthington} in Theramore Isle, Dustwallow Marsh (Alliance) and learn Artisan Tailoring. You need {b}Tailoring 200{/b} and {b}level 35{/b}."] = "Para entrenar más allá de 225, visita a {n:0:horde:Daryl Stack} en Molino Tarren, Laderas de Trabalomas (Horda) o a {n:0:alliance:Timothy Worthington} en Isla Theramore, Marjal Revolcafango (Alianza) y aprende Sastrería de Artesano. Necesitas {b}Sastrería 200{/b} y {b}nivel 35{/b}.",
  ["5x {s:12074:inv_shoulder_25:Black Mageweave Shoulders} - 15 Bolt of Mageweave, 10 Heavy Silken Thread"] = "5x {s:12074:inv_shoulder_25:Black Mageweave Shoulders} - 15 Rollo de tejido mágico, 10 Hilo de seda grueso",
  ["{b}The Expert trainers in Undercity and Stormwind don't teach this recipe{/b}, you can only learn it from the two trainers above."] = "{b}Los instructores de Experto de Entrañas y Ventormenta no enseñan esta receta{/b}, solo puedes aprenderla con los dos instructores de arriba.",
  ["23x {s:18401:inv_fabric_purplefire_02:Bolt of Runecloth} - 115 Runecloth"] = "23x {s:18401:inv_fabric_purplefire_02:Bolt of Runecloth} - 115 Paño rúnico",
  ["Keep the bolts, you will need them later. In total you will need 311 {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth} (1555 {i:14047:inv_fabric_purplefire_01:Runecloth}) until 280, so you can also make all of them now."] = "Guarda los rollos, los necesitarás más adelante. En total necesitarás 311 {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth} (1555 {i:14047:inv_fabric_purplefire_01:Runecloth}) hasta 280, así que también puedes hacerlos todos ahora.",
  ["26x {s:12065:inv_misc_bag_10_black:Mageweave Bag} - 104 Bolt of Mageweave, 52 Silken Thread"] = "26x {s:12065:inv_misc_bag_10_black:Mageweave Bag} - 104 Rollo de tejido mágico, 52 Hilo de seda",
  ["I recommend the bags right now simply because they are more useful. You can use them yourself, sell some, give them to friends or use them in your bank."] = "Ahora mismo te recomiendo las bolsas simplemente porque son más útiles. Puedes usarlas tú, vender algunas, regalarlas a tus amigos o usarlas en tu banco.",
  ["If you don't need the bags and don't want to sell them, make these instead."] = "Si no necesitas las bolsas y no quieres venderlas, haz estos en su lugar.",
  ["10x {s:18402:inv_belt_15:Runecloth Belt} - 30 Bolt of Runecloth, 10 Rune Thread."] = "10x {s:18402:inv_belt_15:Runecloth Belt} - 30 Rollo de paño rúnico, 10 Hilo rúnico.",
  ["24x {s:18402:inv_belt_15:Runecloth Belt} - 72 Bolt of Runecloth, 24 Rune Thread"] = "24x {s:18402:inv_belt_15:Runecloth Belt} - 72 Rollo de paño rúnico, 24 Hilo rúnico",
  ["11x {s:18417:inv_gauntlets_25:Runecloth Gloves} - 44 Bolt of Runecloth, 44 Rugged Leather, 11 Rune Thread"] = "11x {s:18417:inv_gauntlets_25:Runecloth Gloves} - 44 Rollo de paño rúnico, 44 Cuero basto, 11 Hilo rúnico",
  ["The pattern is sold by {n:0::Qia} in Winterspring."] = "El patrón lo vende {n:0::Qia} en Cuna del Invierno.",
  ["39x {s:1257487:inv_bracer_13:Runecloth Cuffs} - 195 Bolt of Runecloth, 39 Ironweb Spider Silk, 39 Rune Thread"] = "39x {s:1257487:inv_bracer_13:Runecloth Cuffs} - 195 Rollo de paño rúnico, 39 Seda de araña de hierro, 39 Hilo rúnico",
  ["The pattern is sold by {n:0::Pexmit} in Mount Hyjal. It's bind on pickup, so buy it with the character that levels Tailoring."] = "El patrón lo vende {n:0::Pexmit} en el Monte Hyjal. Se liga al recogerlo, así que cómpralo con el personaje que sube Sastrería.",
  ["Horde players can also get it as the reward for {q:95769::Threading a Solution}, a quest from {n:265788::Kal'tinzan} in Elderwild, Mount Hyjal. It needs level 54 and 6 Bolt of Runecloth. It's probably a Tailoring quest, but I don't know yet what skill it needs."] = "Los jugadores de la Horda también pueden conseguirlo como recompensa de {q:95769::Threading a Solution}, una misión de {n:265788::Kal'tinzan} en Elderwild, Monte Hyjal. Requiere nivel 54 y 6 Rollo de paño rúnico. Probablemente sea una misión de Sastrería, pero aún no sé qué habilidad necesita.",
  ["Make the {s:18449:inv_shoulder_21:Runecloth Shoulders} if you can get the pattern. These are all the recipes I found so far that still give points after 280. I left out the ones that aren't worth it for leveling, and there might be new ones that nobody has found yet."] = "Haz las {s:18449:inv_shoulder_21:Runecloth Shoulders} si puedes conseguir el patrón. Estas son todas las recetas que he encontrado hasta ahora que siguen dando puntos después de 280. He dejado fuera las que no merecen la pena para subir, y puede que haya otras nuevas que nadie haya encontrado aún.",
  ["Range"] = "Rango",
  ["Materials"] = "Materiales",
  ["Pattern"] = "Patrón",
  ["World drop, on the Auction House"] = "Botín del mundo, en la casa de subastas",
  ["Rare, grab it if you see it on the Auction House"] = "Raro, cógelo si lo ves en la casa de subastas",
  ["You can get a few more points with these, but they stop giving skill points before 300, so you can't reach 300 with them:"] = "Puedes conseguir unos cuantos puntos más con estos, pero dejan de dar puntos de habilidad antes de 300, así que no puedes llegar a 300 con ellos:",
  ["{n:0::Pexmit} in Mount Hyjal"] = "{n:0::Pexmit} en el Monte Hyjal",
  ["Recipes that need a Loom"] = "Recetas que necesitan un Telar",
  ["{b}These recipes need a Loom, and you can only make a Loom at Tailoring 300.{/b} They could be used for leveling, but for now you would need a camp where another tailor already placed a Loom. I'm not sure if this is an oversight by Blizzard, so they might change it."] = "{b}Estas recetas necesitan un Telar, y solo puedes hacer un Telar con Sastrería 300.{/b} Se podrían usar para subir, pero de momento necesitarías un campamento donde otro sastre ya haya colocado un Telar. No sé si es un descuido de Blizzard, así que puede que lo cambien.",
  ["These are the Cenarion Circle patterns from {n:0::Mishta} in Silithus:"] = "Estos son los patrones del Círculo Cenarion de {n:0::Mishta} en Silithus:",
  ["Requires"] = "Requiere",
  ["5x {s:1297123:inv_gauntlets_17:Swarmtender's Gloves} or {s:1297120:inv_gauntlets_18:Venomspew Gloves}"] = "5x {s:1297123:inv_gauntlets_17:Swarmtender's Gloves} o {s:1297120:inv_gauntlets_18:Venomspew Gloves}",
  ["20x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "20x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} o {i:7082:spell_nature_earthbind:Essence of Air}",
  ["Cenarion Circle Friendly"] = "Círculo Cenarion: Amistoso",
  ["5x {s:1297124:inv_belt_03:Swarmtender's Cord} or {s:1297121:inv_belt_25:Venomspew Cord}"] = "5x {s:1297124:inv_belt_03:Swarmtender's Cord} o {s:1297121:inv_belt_25:Venomspew Cord}",
  ["30x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "30x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} o {i:7082:spell_nature_earthbind:Essence of Air}",
  ["Cenarion Circle Honored"] = "Círculo Cenarion: Honorable",
  ["18x {s:1297125:inv_boots_cloth_01:Swarmtender's Footpads} or {s:1297122:inv_boots_cloth_04:Venomspew Footpads}"] = "18x {s:1297125:inv_boots_cloth_01:Swarmtender's Footpads} o {s:1297122:inv_boots_cloth_04:Venomspew Footpads}",
  ["90x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 18x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 54x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "90x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 18x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 54x {i:7080:spell_nature_acid_01:Essence of Water} o {i:7082:spell_nature_earthbind:Essence of Air}",
  ["This WoW Forever Mining leveling guide will show you the fastest way to level Mining from 1 to 300. You will also find every trainer location and where to train Mining past 75, 150 and 225."] = "Esta guía de Minería para WoW Forever te mostrará la forma más rápida de subir Minería de 1 a 300. También encontrarás la ubicación de todos los instructores y dónde aprender Minería más allá de 75, 150 y 225.",
  ["Below you will find the Mining trainers by starting zone and capital city, and the best zones to mine in for every skill range. Mining serves two professions, Blacksmithing and Engineering, so it's really good combined with these two. Check out my Forever Blacksmithing leveling guide or my Forever Engineering leveling guide if you want to level one of them."] = "A continuación encontrarás los instructores de Minería por zona inicial y capital, y las mejores zonas para minar en cada rango de habilidad. La Minería abastece a dos profesiones, Herrería e Ingeniería, así que combina muy bien con ellas. Echa un vistazo a mi guía de Herrería para Forever o a mi guía de Ingeniería para Forever si quieres subir alguna de ellas.",
  ["WoW Forever added a couple of new ores, bars and recipes. You can check them out here:"] = "WoW Forever añadió un par de minerales, barras y recetas nuevos. Puedes verlos aquí:",
  ["Mining Trainer Locations"] = "Ubicación de los instructores de Minería",
  ["Every capital city except Darnassus has a Mining trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "Todas las capitales excepto Darnassus tienen un instructor de Minería. También puedes preguntar a un guardia y quedará marcado con una bandera roja en tu mapa.",
  ["{b}Capital cities:{/b}"] = "{b}Capitales:{/b}",
  ["Undercity: {n:0:horde:Brom Killian}"] = "Entrañas: {n:0:horde:Brom Killian}",
  ["Thunder Bluff: {n:0:horde:Brek Stonehoof}"] = "Cima del Trueno: {n:0:horde:Brek Stonehoof}",
  ["{b}Starting zones:{/b}"] = "{b}Zonas iniciales:{/b}",
  ["{n:0:horde:Norzsh} in the Valley of Trials (only up to 75) {n:0:horde:Krunn} in Razor Hill"] = "{n:0:horde:Norzsh} en el Valle de los Retos (solo hasta 75) {n:0:horde:Krunn} en Cerrotajo",
  ["{n:0:horde:Vartha Rockmane} in Camp Narache (only up to 75) {n:0:horde:Brek Stonehoof} in Thunder Bluff"] = "{n:0:horde:Vartha Rockmane} en el Campamento Narache (solo hasta 75) {n:0:horde:Brek Stonehoof} en Cima del Trueno",
  ["{n:0:horde:Walter Mason} in Deathknell (only up to 75) {n:0:horde:Brom Killian} in Undercity"] = "{n:0:horde:Walter Mason} en Camposanto (solo hasta 75) {n:0:horde:Brom Killian} en Entrañas",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} as your reward, it teaches you Mining. The trainers on the island are {n:0::Halavuul Cragwind} in Valanaar and {n:0::Messana Crestwind} in Shen'dar Village."] = "No hay instructor en la Aldea Thendal, donde empiezas, pero no lo necesitas. {q:93552::Harvesting Windstones} es una de las primeras misiones que recibes en la Aldea Thendal. Elige {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} como recompensa, te enseña Minería. Los instructores de la isla son {n:0::Halavuul Cragwind} en Valanaar y {n:0::Messana Crestwind} en la Aldea Shen'dar.",
  ["Stormwind City: {n:0:alliance:Gelman Stonehand}"] = "Ventormenta: {n:0:alliance:Gelman Stonehand}",
  ["Ironforge: {n:0:alliance:Geofram Bouldertoe}"] = "Forjaz: {n:0:alliance:Geofram Bouldertoe}",
  ["Darnassus: no trainer, the closest one is {n:0:alliance:Kurdram Stonehammer} in Auberdine, Darkshore"] = "Darnassus: sin instructor, el más cercano es {n:0:alliance:Kurdram Stonehammer} en Auberdine, Costa Oscura",
  ["{n:0:alliance:Kelsey Fargo} (only up to 75) {n:0:alliance:Gelman Stonehand} in Stormwind City"] = "{n:0:alliance:Kelsey Fargo} (solo hasta 75) {n:0:alliance:Gelman Stonehand} en Ventormenta",
  ["{n:0:alliance:Sally Swiftwrench} (only up to 75) {n:0:alliance:Yarr Hammerstone} at Steelgrill's Depot {n:0:alliance:Dank Drizzlecut} at Gol'Bolar Quarry"] = "{n:0:alliance:Sally Swiftwrench} (solo hasta 75) {n:0:alliance:Yarr Hammerstone} en el Almacén de Brasacerada {n:0:alliance:Dank Drizzlecut} en la Cantera de Gol'Bolar",
  ["{n:0:alliance:Fanorran Stilloak} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Kurdram Stonehammer} in Auberdine, Darkshore"] = "{n:0:alliance:Fanorran Stilloak} en Aldrassil, Cañada Umbría (solo hasta 75) {n:0:alliance:Kurdram Stonehammer} en Auberdine, Costa Oscura",
  ["You can find every Mining trainer for Horde and Alliance on my WoW Forever Mining Trainers page."] = "Puedes encontrar todos los instructores de Minería de la Horda y la Alianza en mi página de instructores de Minería de WoW Forever.",
  ["Track Ore on Your Minimap"] = "Rastrea minerales en tu minimapa",
  ["You can only track one thing at a time, so {b}you can't track minerals and herbs together{/b}."] = "Solo puedes rastrear una cosa a la vez, así que {b}no puedes rastrear minerales y hierbas a la vez{/b}.",
  ["You learn {s:2580:spell_nature_earthquake:Find Minerals} together with Mining, but it's not turned on by default:"] = "Aprendes {s:2580:spell_nature_earthquake:Find Minerals} junto con Minería, pero no está activado por defecto:",
  ["Open the Professions window with the hammer and pick button, the 2nd button in the menu at the bottom of your screen."] = "Abre la ventana de Profesiones con el botón del martillo y el pico, el 2.º botón del menú de la parte inferior de tu pantalla.",
  ["Click Find Minerals in the Mining box. {b}I recommend dragging it to your action bar, close to the buffs you use after you die.{/b} This way you make a habit out of it and you are less likely to forget it."] = "Haz clic en Buscar minerales en el recuadro de Minería. {b}Te recomiendo arrastrarlo a tu barra de acción, cerca de los beneficios que usas después de morir.{/b} Así lo convertirás en un hábito y será menos probable que lo olvides.",
  ["The Find Minerals buff shows up next to your minimap. {b}Your tracking turns off every time you die, so don't forget to turn it back on!{/b}"] = "El beneficio de Buscar minerales aparece junto a tu minimapa. {b}Tu rastreo se desactiva cada vez que mueres, ¡así que no olvides volver a activarlo!{/b}",
  ["The Find Minerals button in the WoW Forever Professions window"] = "El botón Buscar minerales en la ventana de Profesiones de WoW Forever",
  ["Mining Skill Bonuses"] = "Bonificaciones a la habilidad de Minería",
  ["You don't need these, but they help when you are stuck between two ores. With +5 you can mine Iron Deposits from 120 instead of 125, so you can skip the last few slow points of Tin."] = "No las necesitas, pero ayudan cuando estás atascado entre dos minerales. Con +5 puedes minar Depósitos de hierro desde 120 en lugar de 125, así que puedes saltarte los últimos puntos lentos del Estaño.",
  ["Item"] = "Objeto",
  ["Mining"] = "Minería",
  ["How to get it"] = "Cómo conseguirlo",
  ["An enchanter"] = "Un encantador",
  ["Made by Engineers, you need Engineering 205 to wear it"] = "Lo fabrican los ingenieros, necesitas Ingeniería 205 para llevarlo",
  ["Reward of A Miner Problem, an Alliance quest in the Riverglades"] = "Recompensa de A Miner Problem, una misión de la Alianza en Riverglades",
  ["Drops from Miner Johnson in The Deadmines"] = "Lo suelta el Minero Johnson en las Minas de la Muerte",
  ["Smelting to 105"] = "Fundir hasta 105",
  ["You can skip the first 105 skill points by buying ores on the Auction House and smelting them. If you prefer leveling Mining the normal way, scroll down to the mining routes. But I would recommend smelting if you have the gold, as it saves a lot of time. Sometimes the bars even sell for more than the ores or they are very close in price, so it's not like you are losing much by doing this."] = "Puedes saltarte los primeros 105 puntos de habilidad comprando minerales en la casa de subastas y fundiéndolos. Si prefieres subir Minería de la forma normal, baja hasta las rutas de minería. Pero te recomiendo fundir si tienes el oro, porque ahorra mucho tiempo. A veces las barras incluso se venden por más que los minerales o tienen un precio muy parecido, así que no pierdes mucho haciéndolo.",
  ["Buy around 140 {i:2770:inv_ore_copper_01:Copper Ore} and 70 {i:2771:inv_ore_tin_01:Tin Ore}. Smelting is mostly yellow and green, so you might need a few more if you are unlucky."] = "Compra unos 140 {i:2770:inv_ore_copper_01:Copper Ore} y 70 {i:2771:inv_ore_tin_01:Tin Ore}. Fundir es casi todo amarillo y verde, así que puede que necesites algunos más si tienes mala suerte.",
  ["Notes"] = "Notas",
  ["120-140x {s:2657:inv_ingot_02:Smelt Copper} until you reach 65. Keep 70 Copper Bars, you will need them for Bronze."] = "120-140x {s:2657:inv_ingot_02:Smelt Copper} hasta llegar a 65. Guarda 70 Barras de cobre, las necesitarás para el bronce.",
  ["Learn Journeyman Mining, Smelt Tin and Smelt Bronze from your trainer. Make 70x {s:3304:inv_ingot_05:Smelt Tin}. It turns grey at 75, but you need all 70 Tin Bars for Bronze anyway."] = "Aprende Minería de Oficial, Fundir estaño y Fundir bronce con tu instructor. Haz 70x {s:3304:inv_ingot_05:Smelt Tin}. Se vuelve gris en 75, pero de todas formas necesitas las 70 Barras de estaño para el bronce.",
  ["Make 70x {s:2659:inv_ingot_bronze:Smelt Bronze} from the Copper Bars and Tin Bars you made. You will end up somewhere between 100 and 110, so you might need a few more."] = "Haz 70x {s:2659:inv_ingot_bronze:Smelt Bronze} con las Barras de cobre y de estaño que hiciste. Acabarás entre 100 y 110, así que puede que necesites algunas más.",
  ["Learn Smelt Silver from your trainer. Check the price of Silver Ore and Silver Bar first, because this part can get expensive. If you don't mind the cost, make 35-45x {s:2658:inv_ingot_01:Smelt Silver} until you reach 120. The last 5 points to 125 could take around 50 more Silver Ore, so I recommend mining from 120. (or keep smelting if you have the gold) Iron Deposits need Mining 125, but with +5 from the Mining Skill Bonuses above you can mine them from 120, so you can skip Tin and go straight to Iron."] = "Aprende Fundir plata con tu instructor. Mira primero el precio del Mineral de plata y de la Barra de plata, porque esta parte puede salir cara. Si no te importa el coste, haz 35-45x {s:2658:inv_ingot_01:Smelt Silver} hasta llegar a 120. Los últimos 5 puntos hasta 125 podrían costar unos 50 Minerales de plata más, así que te recomiendo minar a partir de 120 (o seguir fundiendo si tienes el oro). Los Depósitos de hierro necesitan Minería 125, pero con +5 de las bonificaciones a la habilidad de Minería de arriba puedes minarlos desde 120, así que puedes saltarte el estaño e ir directamente al hierro.",
  ["{b}Don't forget to buy{/b} a {i:2901:inv_pick_02:Mining Pick} from the Mining Supplier near your trainer or from the trainer!"] = "{b}¡No olvides comprar{/b} un {i:2901:inv_pick_02:Mining Pick} al proveedor de minería cerca de tu instructor o al propio instructor!",
  ["You can buy one from these vendors:"] = "Puedes comprar uno a estos vendedores:",
  ["{n:0:horde:Norzsh} in the Valley of Trials, {n:0:horde:Flakk} in Razor Hill"] = "{n:0:horde:Norzsh} en el Valle de los Retos, {n:0:horde:Flakk} en Cerrotajo",
  ["{n:0:horde:Vartha Rockmane} in Camp Narache, {n:0:horde:Wunna Darkmane} in Bloodhoof Village"] = "{n:0:horde:Vartha Rockmane} en el Campamento Narache, {n:0:horde:Wunna Darkmane} en el Poblado Pezuña de Sangre",
  ["{n:0:horde:Walter Mason} in Deathknell, {n:0:horde:Abigail Shiel} in Brill"] = "{n:0:horde:Walter Mason} en Camposanto, {n:0:horde:Abigail Shiel} en Rémol",
  ["{n:0::Uualia Suncrest} in Thendal Village, {n:0::Belandiel Farflight} in Shen'dar Village"] = "{n:0::Uualia Suncrest} en la Aldea Thendal, {n:0::Belandiel Farflight} en la Aldea Shen'dar",
  ["{n:0:horde:Gorina} in the Valley of Honor"] = "{n:0:horde:Gorina} en el Valle del Honor",
  ["{n:0:horde:Elizabeth Van Talen} in the Rogues' Quarter"] = "{n:0:horde:Elizabeth Van Talen} en el Barrio de los Pícaros",
  ["{n:0:alliance:Brother Danil} in Northshire Valley, {n:0:alliance:Tharynn Bouden} in Goldshire"] = "{n:0:alliance:Brother Danil} en el Valle de Villanorte, {n:0:alliance:Tharynn Bouden} en Villadorada",
  ["{n:0:alliance:Thrawn Boltar} in Kharanos"] = "{n:0:alliance:Thrawn Boltar} en Kharanos",
  ["{n:0:alliance:Fanorran Stilloak} at Aldrassil in Shadowglen, {n:0:alliance:Narret Shadowgrove} in Dolanaar"] = "{n:0:alliance:Fanorran Stilloak} en Aldrassil, Cañada Umbría, {n:0:alliance:Narret Shadowgrove} en Dolanaar",
  ["{n:0:alliance:Brooke Stonebraid} in the Dwarven District"] = "{n:0:alliance:Brooke Stonebraid} en el Distrito de los Enanos",
  ["{n:0:alliance:Thurgrum Deepforge} in The Great Forge"] = "{n:0:alliance:Thurgrum Deepforge} en La Gran Fundición",
  ["Like I said above, for most high level players I think it's best to skip this part and smelt your way up to at least 105. But if you prefer mining and you can choose your zone, I think {b}Durotar{/b} is the best for Horde and {b}Elwynn Forest{/b} for Alliance."] = "Como dije arriba, para la mayoría de los jugadores de nivel alto creo que es mejor saltarse esta parte y fundir hasta al menos 105. Pero si prefieres minar y puedes elegir tu zona, creo que {b}Durotar{/b} es la mejor para la Horda y el {b}Bosque de Elwynn{/b} para la Alianza.",
  ["One or two laps around the zone will get you enough Copper Ore to reach 65 with smelting."] = "Con una o dos vueltas por la zona conseguirás suficiente Mineral de cobre para llegar a 65 fundiendo.",
  ["After you do one lap, {b}stop at Razor Hill and smelt your Copper Ore{/b} into Copper Bars."] = "Después de dar una vuelta, {b}para en Cerrotajo y funde tu Mineral de cobre{/b} en Barras de cobre.",
  ["Mining route in Durotar"] = "Ruta de minería en Durotar",
  ["The cave marked with the red circle has 5 Copper Veins inside, {b}the respawn rate is so fast that you can basically stay inside the cave and level there{/b}. The cave layout is also very good because there is a drop down at the end, so you can quickly return to the start and continue mining. If the respawn rate is not enough for you or there is competition, just run outside, mine a couple of Copper Veins and go back to the cave."] = "La cueva marcada con el círculo rojo tiene 5 Filones de cobre dentro; {b}reaparecen tan rápido que básicamente puedes quedarte dentro de la cueva y subir allí{/b}. La forma de la cueva también es muy buena porque hay un desnivel al final, así que puedes volver rápido al principio y seguir minando. Si la reaparición no te basta o hay competencia, sal fuera, mina un par de Filones de cobre y vuelve a la cueva.",
  ["You can also just do a full lap in Mulgore, the route is very easy to follow, it's basically a loop around the edge of the zone. But I found the cave to be better without a mount."] = "También puedes dar una vuelta completa por Mulgore; la ruta es muy fácil de seguir, básicamente un circuito por el borde de la zona. Pero sin montura me pareció mejor la cueva.",
  ["{b}You can smelt your ore at the Bael'dun Digsite{/b}, the dwarf camp just north of the cave has a forge and an anvil. (marked on the map) The dwarves there are hostile."] = "{b}Puedes fundir tu mineral en la Excavación de Bael'dun{/b}: el campamento enano justo al norte de la cueva tiene una forja y un yunque (marcados en el mapa). Los enanos de allí son hostiles.",
  ["Mining route in Mulgore with the forge and anvil at the Bael'dun Digsite"] = "Ruta de minería en Mulgore con la forja y el yunque de la Excavación de Bael'dun",
  ["Both routes are good. The route on the east side of the zone will probably have fewer people, because there are fewer quest hubs there."] = "Las dos rutas son buenas. La ruta del lado este de la zona probablemente tenga menos gente, porque allí hay menos centros de misiones.",
  ["{b}Stop at Brill after one lap{/b} to smelt your Copper Ore."] = "{b}Para en Rémol después de una vuelta{/b} para fundir tu Mineral de cobre.",
  ["Mining route in Tirisfal Glades"] = "Ruta de minería en los Claros de Tirisfal",
  ["{q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} as your reward, it teaches you Mining."] = "{q:93552::Harvesting Windstones} es una de las primeras misiones que recibes en la Aldea Thendal. Elige {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} como recompensa, te enseña Minería.",
  ["The respawn rate is very fast around this area, sometimes the veins spawned right on top of me. You can do a larger route, but without a mount and with the fast respawn rate I found it wasn't needed."] = "Los filones reaparecen muy rápido en esta zona; a veces aparecían justo encima de mí. Puedes hacer una ruta más grande, pero sin montura y con una reaparición tan rápida vi que no hacía falta.",
  ["{b}Stop at Shen'dar Village after one lap{/b} to smelt your Copper Ore."] = "{b}Para en la Aldea Shen'dar después de una vuelta{/b} para fundir tu Mineral de cobre.",
  ["Mining route on Zephras Isle"] = "Ruta de minería en la Isla Zephras",
  ["Just move back and forth along the marked route, and clear the cave if you are high enough level. The respawn rate is quite fast inside the cave, so you might not even have to leave it, it depends on your level. You can also just skip the cave, the respawn rate seems to be fast enough on the route, but then do the small detour to the north too."] = "Simplemente ve y vuelve por la ruta marcada, y limpia la cueva si tienes nivel suficiente. Dentro de la cueva la reaparición es bastante rápida, así que puede que ni siquiera tengas que salir, depende de tu nivel. También puedes saltarte la cueva, la reaparición parece suficientemente rápida en la ruta, pero entonces haz también el pequeño desvío hacia el norte.",
  ["{b}Stop at Goldshire after one lap{/b} to smelt your Copper Ore."] = "{b}Para en Villadorada después de una vuelta{/b} para fundir tu Mineral de cobre.",
  ["Mining route in Elwynn Forest"] = "Ruta de minería en el Bosque de Elwynn",
  ["Not much to say about this one, just do loops around this area. You don't have to go inside the cave, it's optional and the respawn rate outside is quite fast."] = "No hay mucho que decir de esta, simplemente da vueltas por esta zona. No tienes que entrar en la cueva, es opcional y fuera la reaparición es bastante rápida.",
  ["{b}Stop at Kharanos after one lap{/b} to smelt your Copper Ore."] = "{b}Para en Kharanos después de una vuelta{/b} para fundir tu Mineral de cobre.",
  ["Mining route in Dun Morogh"] = "Ruta de minería en Dun Morogh",
  ["These two caves have an insanely fast respawn rate. I don't know if it stays like this, but right now you can just stay inside the caves and level there."] = "Estas dos cuevas tienen una reaparición rapidísima. No sé si seguirá así, pero ahora mismo puedes quedarte dentro de las cuevas y subir allí.",
  ["There is no forge in Teldrassil, {b}the closest one is at the Warrior's Terrace in Darnassus{/b}."] = "No hay forja en Teldrassil, {b}la más cercana está en el Bancal del Guerrero de Darnassus{/b}.",
  ["Mining route in Teldrassil"] = "Ruta de minería en Teldrassil",
  ["Visit your trainer and learn Journeyman Mining, it requires Mining 50. The new Junior Mining Trainers in the starting areas won't teach you Journeyman Mining."] = "Visita a tu instructor y aprende Minería de Oficial, requiere Minería 50. Los nuevos instructores júnior de Minería de las zonas iniciales no enseñan Minería de Oficial.",
  ["If you have any Copper Ore or Tin Ore at this point, smelt them and make Bronze Bars before you head out, because Bronze stops giving skill points around 105."] = "Si a estas alturas tienes Mineral de cobre o de estaño, fúndelos y haz Barras de bronce antes de salir, porque el bronce deja de dar puntos de habilidad hacia 105.",
  ["For Alliance, the {b}Wetlands{/b} is the best one by far if you can manage the cave. For Horde it's the {b}Silverpine Forest{/b} cave or {b}Hillsbrad Foothills{/b}. The rest are pretty even, hard to judge."] = "Para la Alianza, {b}Los Humedales{/b} es con diferencia la mejor si puedes con la cueva. Para la Horda es la cueva del {b}Bosque de Argénteos{/b} o las {b}Laderas de Trabalomas{/b}. Las demás están bastante igualadas, es difícil decidir.",
  ["Ores in these zones: {i:2771:inv_ore_tin_01:Tin Ore}, {i:2770:inv_ore_copper_01:Copper Ore}, {i:2775:inv_stone_16:Silver Ore}"] = "Minerales en estas zonas: {i:2771:inv_ore_tin_01:Tin Ore}, {i:2770:inv_ore_copper_01:Copper Ore}, {i:2775:inv_stone_16:Silver Ore}",
  ["Tin Veins need Mining 65 and Silver Veins 75."] = "Los Filones de estaño necesitan Minería 65 y los Filones de plata 75.",
  ["Wetlands"] = "Los Humedales",
  ["Silverpine Forest"] = "Bosque de Argénteos",
  ["Westfall"] = "Páramos de Poniente",
  ["Hillsbrad Foothills"] = "Laderas de Trabalomas",
  ["The Barrens"] = "Los Baldíos",
  ["Ashenvale"] = "Vallefresno",
  ["Stonetalon Mountains"] = "Sierra Espolón",
  ["This cave in the Wetlands is the best place for Alliance players to level Mining. The cave is full of Tin Veins and Incendicite Mineral Veins with a very fast respawn time."] = "Esta cueva de Los Humedales es el mejor sitio para que los jugadores de la Alianza suban Minería. La cueva está llena de Filones de estaño y Filones de incendicita con un tiempo de reaparición muy rápido.",
  ["The mobs are around level 20 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "Los enemigos son de nivel 20 aproximadamente y {b}en Forever reaparecen mucho más rápido, así que necesitas superarlos en bastantes niveles{/b}, o seguirán reapareciendo justo encima de ti.",
  ["Mining route in the Wetlands"] = "Ruta de minería en Los Humedales",
  ["This cave has 3 vein spawn points with a very fast respawn time, just mine the veins and wait for the respawn. (around 2 minutes)"] = "Esta cueva tiene 3 puntos de aparición de filones con un tiempo de reaparición muy rápido; mina los filones y espera a que reaparezcan (unos 2 minutos).",
  ["The mobs are around level 21-22 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "Los enemigos son de nivel 21-22 aproximadamente y {b}en Forever reaparecen mucho más rápido, así que necesitas superarlos en bastantes niveles{/b}, o seguirán reapareciendo justo encima de ti.",
  ["Mining route in Silverpine Forest"] = "Ruta de minería en el Bosque de Argénteos",
  ["This cave has several Tin Veins that respawn very fast. There are also veins outside, so if you clear it too fast you can just run outside and mine a few there too."] = "Esta cueva tiene varios Filones de estaño que reaparecen muy rápido. También hay filones fuera, así que si la limpias demasiado rápido puedes salir y minar unos cuantos allí también.",
  ["The mobs are around level 13-15 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "Los enemigos son de nivel 13-15 aproximadamente y {b}en Forever reaparecen mucho más rápido, así que necesitas superarlos en bastantes niveles{/b}, o seguirán reapareciendo justo encima de ti.",
  ["Mining route in Westfall"] = "Ruta de minería en los Páramos de Poniente",
  ["This is the best if you prefer mining the normal way, but you might have more competition from other players because this is a popular area. The route goes around a Horde town, so I'm not sure how it works for Alliance. I think you can probably avoid the guards, but I only tested this one with a Horde character."] = "Esta es la mejor si prefieres minar de la forma normal, pero puede que tengas más competencia de otros jugadores porque es una zona popular. La ruta rodea un pueblo de la Horda, así que no sé bien cómo funciona para la Alianza. Creo que probablemente puedes evitar a los guardias, pero solo la probé con un personaje de la Horda.",
  ["Mining route in Hillsbrad Foothills"] = "Ruta de minería en las Laderas de Trabalomas",
  ["The mobs are around level 22-26 here, so it's best to farm here if you are above those levels. But the respawn rate is fast."] = "Aquí los enemigos son de nivel 22-26 aproximadamente, así que es mejor farmear aquí si estás por encima de esos niveles. Pero la reaparición es rápida.",
  ["Mining route in The Barrens"] = "Ruta de minería en Los Baldíos",
  ["A very straightforward route that is easy to follow. This is the best if you prefer mining the normal way, but you might have more competition from other players because this is a popular area."] = "Una ruta muy sencilla y fácil de seguir. Esta es la mejor si prefieres minar de la forma normal, pero puede que tengas más competencia de otros jugadores porque es una zona popular.",
  ["Mining route in Ashenvale"] = "Ruta de minería en Vallefresno",
  ["This route might not work if more than one player is leveling Mining there, because when I tested it there were very few people around. But this place usually has fewer people, so I think it's a good alternative if you don't want to level in caves. The only downside is that sometimes an Iron Deposit spawns instead of a Tin Vein, and you can't mine it yet."] = "Puede que esta ruta no funcione si más de un jugador está subiendo Minería allí, porque cuando la probé había muy poca gente. Pero este sitio suele tener menos gente, así que creo que es una buena alternativa si no quieres subir en cuevas. La única pega es que a veces aparece un Depósito de hierro en lugar de un Filón de estaño, y aún no puedes minarlo.",
  ["Mining route in Stonetalon Mountains"] = "Ruta de minería en la Sierra Espolón",
  ["From this point the guide follows the standard Classic Mining routes. The beta cap was 30, so I couldn't properly test Arathi and Desolace. I'll revise this section once I level my character higher on live, but the main change is the ore respawn rate, so most routes should work and you can probably take shorter routes in most zones."] = "A partir de aquí la guía sigue las rutas de minería estándar de Classic. El nivel máximo de la beta era 30, así que no pude probar bien Arathi y Desolace. Revisaré esta sección cuando suba más mi personaje en el servidor real, pero el cambio principal es la reaparición de los minerales, así que la mayoría de las rutas deberían funcionar y probablemente puedas hacer rutas más cortas en la mayoría de las zonas.",
  ["{b}Visit your trainer and learn Expert Mining{/b}, it requires Mining 125."] = "{b}Visita a tu instructor y aprende Minería de Experto{/b}, requiere Minería 125.",
  ["Smelting Iron and Gold (optional)"] = "Fundir hierro y oro (opcional)",
  ["If you want to save some time and have the gold, buy around 20 {i:2772:inv_ore_iron_01:Iron Ore} and make {s:3307:inv_ingot_iron:Smelt Iron} until 135 before you head out mining. After 135 it rarely gives a point, so don't count on reaching 140."] = "Si quieres ahorrar algo de tiempo y tienes el oro, compra unos 20 {i:2772:inv_ore_iron_01:Iron Ore} y haz {s:3307:inv_ingot_iron:Smelt Iron} hasta 135 antes de salir a minar. Después de 135 rara vez da un punto, así que no cuentes con llegar a 140.",
  ["At 155 you can learn {s:3308:inv_ingot_03:Smelt Gold} from your trainer. It gives a point every time until 170, so around 22 Gold Ore takes you from 155 to 175 and you can start on Mithril right away. I recommend checking the price of Gold Ore and Gold Bar first."] = "En 155 puedes aprender {s:3308:inv_ingot_03:Smelt Gold} con tu instructor. Da un punto cada vez hasta 170, así que unos 22 Minerales de oro te llevan de 155 a 175 y puedes empezar con el mitril enseguida. Te recomiendo mirar primero el precio del Mineral de oro y de la Barra de oro.",
  ["If you have a {b}lower level character{/b} around level 30, stick to the {b}Thousand Needles{/b} route, that's the safest. If you have a {b}higher level character or a mount{/b} already, I recommend {b}Arathi Highlands{/b}."] = "Si tienes un {b}personaje de nivel más bajo{/b}, alrededor del nivel 30, quédate con la ruta de {b}Las Mil Agujas{/b}, es la más segura. Si ya tienes un {b}personaje de nivel más alto o una montura{/b}, te recomiendo las {b}Tierras Altas de Arathi{/b}.",
  ["Ores in these zones: {i:2772:inv_ore_iron_01:Iron Ore}, {i:2771:inv_ore_tin_01:Tin Ore}, {i:2776:inv_ore_gold_01:Gold Ore}"] = "Minerales en estas zonas: {i:2772:inv_ore_iron_01:Iron Ore}, {i:2771:inv_ore_tin_01:Tin Ore}, {i:2776:inv_ore_gold_01:Gold Ore}",
  ["Iron Deposits need Mining 125 and Gold Veins 155."] = "Los Depósitos de hierro necesitan Minería 125 y los Filones de oro 155.",
  ["Arathi Highlands"] = "Tierras Altas de Arathi",
  ["Thousand Needles"] = "Las Mil Agujas",
  ["There are 4 caves marked with red circles on the map. Make sure to go all the way to the end of each cave because you won't see all the mining veins from the entrance."] = "Hay 4 cuevas marcadas con círculos rojos en el mapa. Asegúrate de llegar hasta el fondo de cada cueva, porque desde la entrada no verás todos los filones.",
  ["Low level players should skip all 4 caves, and low level Alliance players should take a detour and go south of Hammerfall!"] = "Los jugadores de nivel bajo deberían saltarse las 4 cuevas, ¡y los jugadores de la Alianza de nivel bajo deberían dar un rodeo e ir al sur de Sentencia!",
  ["Mining route in Arathi Highlands"] = "Ruta de minería en las Tierras Altas de Arathi",
  ["Mining route in Thousand Needles"] = "Ruta de minería en Las Mil Agujas",
  ["Mining route in Desolace"] = "Ruta de minería en Desolace",
  ["To train past 225, visit your trainer and learn Artisan Mining, it requires Mining 200."] = "Para entrenar más allá de 225, visita a tu instructor y aprende Minería de Artesano, requiere Minería 200.",
  ["Ores in these zones: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}"] = "Minerales en estas zonas: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}",
  ["Mithril Deposits need Mining 175 and Truesilver Deposits 230."] = "Los Depósitos de mitril necesitan Minería 175 y los Depósitos de veraplata 230.",
  ["The Hinterlands"] = "Tierras del Interior",
  ["The red route should be skipped by lower level players because the area is filled with level 62 elites. Lower level players might also want to consider skipping the cave marked with a red circle on the map. (depends on your gear/class)"] = "Los jugadores de nivel bajo deberían saltarse la ruta roja, porque la zona está llena de élites de nivel 62. Los jugadores de nivel bajo quizá también deberían saltarse la cueva marcada con un círculo rojo en el mapa (depende de tu equipo/clase).",
  ["Mining route in The Hinterlands"] = "Ruta de minería en las Tierras del Interior",
  ["Players below level 60 should skip the 4 caves marked with red circles."] = "Los jugadores por debajo del nivel 60 deberían saltarse las 4 cuevas marcadas con círculos rojos.",
  ["Mining route in Tanaris"] = "Ruta de minería en Tanaris",
  ["Ores in these zones: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}, {i:10620:inv_ore_thorium_02:Thorium Ore}"] = "Minerales en estas zonas: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}, {i:10620:inv_ore_thorium_02:Thorium Ore}",
  ["Small Thorium Veins need Mining 245."] = "Los Filones pequeños de torio necesitan Minería 245.",
  ["Un'Goro Crater"] = "Cráter de Un'Goro",
  ["Blasted Lands"] = "Las Tierras Devastadas",
  ["Felwood"] = "Frondavil",
  ["You will find 2-3 veins in the two caves marked with red circles on the map."] = "Encontrarás 2-3 filones en las dos cuevas marcadas con círculos rojos en el mapa.",
  ["Lower level players should probably skip the cave to the south. It really depends on your level, gear and class."] = "Los jugadores de nivel más bajo probablemente deberían saltarse la cueva del sur. Depende mucho de tu nivel, equipo y clase.",
  ["Mining route in Un'Goro Crater"] = "Ruta de minería en el Cráter de Un'Goro",
  ["Both caves marked with red circles have a lot of mobs inside, so I only recommend this zone to level 60 players with good gear, or to Druids and Rogues with stealth."] = "Las dos cuevas marcadas con círculos rojos tienen muchos enemigos dentro, así que solo recomiendo esta zona a jugadores de nivel 60 con buen equipo, o a druidas y pícaros con sigilo.",
  ["It's really hard to navigate inside the Garrison Armory mine, so I included a small map. {b}Alliance{/b} players can't mine inside the Garrison Armory!"] = "Es muy difícil orientarse dentro de la mina del Arsenal de la Guarnición, así que he incluido un pequeño mapa. ¡Los jugadores de la {b}Alianza{/b} no pueden minar dentro del Arsenal de la Guarnición!",
  ["Mining route in the Blasted Lands"] = "Ruta de minería en Las Tierras Devastadas",
  ["There are usually 2 veins inside the cave marked with a red circle. It's worth going in because the cave is small and there aren't many mobs inside, and if you are high level, you can pass some of them without aggro."] = "Suele haber 2 filones dentro de la cueva marcada con un círculo rojo. Merece la pena entrar porque la cueva es pequeña y no hay muchos enemigos dentro, y si tienes nivel alto puedes pasar junto a algunos sin llamar su atención.",
  ["I recommend skipping the other two caves at Jaedenar, especially Shadow Hold. (if you have stealth, they might be worth going into)"] = "Te recomiendo saltarte las otras dos cuevas de Jaedenar, sobre todo el Bastión Sombrío (si tienes sigilo, puede que merezca la pena entrar).",
  ["Mining route in Felwood"] = "Ruta de minería en Frondavil",
  ["Ores in these zones: {i:10620:inv_ore_thorium_02:Thorium Ore}, {i:3858:inv_ore_mithril_02:Mithril Ore}"] = "Minerales en estas zonas: {i:10620:inv_ore_thorium_02:Thorium Ore}, {i:3858:inv_ore_mithril_02:Mithril Ore}",
  ["At 275 you can mine Rich Thorium Veins too."] = "En 275 también puedes minar Filones de torio enriquecido.",
  ["Eastern Plaguelands"] = "Tierras de la Peste del Este",
  ["Winterspring"] = "Cuna del Invierno",
  ["Burning Steppes"] = "Las Estepas Ardientes",
  ["Almost the same as the previous Un'Goro route, but now it includes Rich Thorium Veins."] = "Casi igual que la ruta anterior de Un'Goro, pero ahora incluye los Filones de torio enriquecido.",
  ["Mining route with Rich Thorium Veins in Un'Goro Crater"] = "Ruta de minería con Filones de torio enriquecido en el Cráter de Un'Goro",
  ["The red line is full of level 57-58 elites, so if your gear is bad, you should probably skip that part unless you have stealth. With some practice you can usually get through and only pull a few of them."] = "La línea roja está llena de élites de nivel 57-58, así que si tu equipo es malo, probablemente deberías saltarte esa parte a menos que tengas sigilo. Con algo de práctica normalmente puedes pasar atrayendo solo a unos pocos.",
  ["Mining route in the Eastern Plaguelands"] = "Ruta de minería en las Tierras de la Peste del Este",
  ["The mobs in this cave are not that hard, so most classes can clear it. (depends on your gear)"] = "Los enemigos de esta cueva no son muy difíciles, así que la mayoría de las clases pueden limpiarla (depende de tu equipo).",
  ["Most classes can get into at least the first part of the cave without pulling aggro. You can try going deeper depending on your gear."] = "La mayoría de las clases pueden entrar al menos en la primera parte de la cueva sin llamar la atención de los enemigos. Puedes intentar adentrarte más según tu equipo.",
  ["A lot of elites patrol this gorge, but you can usually pass most of them without pulling aggro. Sometimes you have to kill 1 or 2."] = "Muchos élites patrullan este desfiladero, pero normalmente puedes pasar junto a la mayoría sin llamar su atención. A veces tendrás que matar 1 o 2.",
  ["I don't recommend this area for most players because it's hard to farm here without dying. It really depends on your class and how good you are at avoiding mobs."] = "No recomiendo esta zona a la mayoría de los jugadores porque es difícil farmear aquí sin morir. Depende mucho de tu clase y de lo bien que esquives a los enemigos.",
  ["Mining route in Winterspring"] = "Ruta de minería en Cuna del Invierno",
  ["The two caves marked with red circles are full of level 50 mobs, so lower level players might want to skip them. (depends on your gear and level)"] = "Las dos cuevas marcadas con círculos rojos están llenas de enemigos de nivel 50, así que los jugadores de nivel más bajo quizá quieran saltárselas (depende de tu equipo y nivel).",
  ["Mining route in the Burning Steppes"] = "Ruta de minería en Las Estepas Ardientes",
  ["This WoW Forever Herbalism leveling guide will show you the fastest way to level Herbalism from 1 to 300. You will also find a route map for every zone, every trainer location and where to train Herbalism past 75, 150 and 225."] = "Esta guía de Herboristería para WoW Forever te mostrará la forma más rápida de subir Herboristería de 1 a 300. También encontrarás un mapa de ruta para cada zona, la ubicación de todos los instructores y dónde aprender Herboristería más allá de 75, 150 y 225.",
  ["Below you will find the Herbalism trainers by starting zone and capital city, and the best zones to pick herbs in for every skill range. Herbalism goes well with Alchemy because you can use the herbs you pick to make potions and elixirs, so check out my Forever Alchemy leveling guide if you want to level Alchemy. But keep in mind, this guide is made to level Herbalism as fast as possible, so sometimes the herbs you pick are not the best ones for Alchemy."] = "A continuación encontrarás los instructores de Herboristería por zona inicial y capital, y las mejores zonas para recoger hierbas en cada rango de habilidad. La Herboristería combina bien con Alquimia porque puedes usar las hierbas que recoges para hacer pociones y elixires, así que echa un vistazo a mi guía de Alquimia para Forever si quieres subir Alquimia. Pero ten en cuenta que esta guía está hecha para subir Herboristería lo más rápido posible, así que a veces las hierbas que recoges no son las mejores para Alquimia.",
  ["WoW Forever added a couple of new herbs, seeds and recipes. You can check them out here:"] = "WoW Forever añadió un par de hierbas, semillas y recetas nuevas. Puedes verlas aquí:",
  ["Herbalism Trainer Locations"] = "Ubicación de los instructores de Herboristería",
  ["Every capital city has a Herbalism trainer. You can also ask a guard where the herbalist is, then it will be marked with a red flag on your map."] = "Todas las capitales tienen un instructor de Herboristería. También puedes preguntar a un guardia dónde está el herborista y quedará marcado con una bandera roja en tu mapa.",
  ["Undercity: {n:0:horde:Martha Alliestar}"] = "Entrañas: {n:0:horde:Martha Alliestar}",
  ["Thunder Bluff: {n:0:horde:Komin Winterhoof}"] = "Cima del Trueno: {n:0:horde:Komin Winterhoof}",
  ["{n:0:horde:Zor'la} in the Valley of Trials (only up to 75) {n:0:horde:Mishiki} in Sen'jin Village"] = "{n:0:horde:Zor'la} en el Valle de los Retos (solo hasta 75) {n:0:horde:Mishiki} en la Aldea Sen'jin",
  ["{n:0:horde:Garan Sunstrider} in Camp Narache (only up to 75) {n:0:horde:Komin Winterhoof} in Thunder Bluff"] = "{n:0:horde:Garan Sunstrider} en el Campamento Narache (solo hasta 75) {n:0:horde:Komin Winterhoof} en Cima del Trueno",
  ["{n:0:horde:Florence Nightshade} in Deathknell (only up to 75) {n:0:horde:Faruza} in Brill"] = "{n:0:horde:Florence Nightshade} en Camposanto (solo hasta 75) {n:0:horde:Faruza} en Rémol",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} as your reward, it teaches you Herbalism. The trainers on the island are {n:0::Syriel Nightrain} in Valanaar and {n:0::Halassa Fernbreeze} in Shen'dar Village."] = "No hay instructor en la Aldea Thendal, donde empiezas, pero no lo necesitas. {q:93552::Harvesting Windstones} es una de las primeras misiones que recibes en la Aldea Thendal. Elige {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} como recompensa, te enseña Herboristería. Los instructores de la isla son {n:0::Syriel Nightrain} en Valanaar y {n:0::Halassa Fernbreeze} en la Aldea Shen'dar.",
  ["Stormwind City: {n:0:alliance:Tannysa}"] = "Ventormenta: {n:0:alliance:Tannysa}",
  ["Ironforge: {n:0:alliance:Reyna Stonebranch}"] = "Forjaz: {n:0:alliance:Reyna Stonebranch}",
  ["{n:0:alliance:Nancy Songflower} (only up to 75) {n:0:alliance:Herbalist Pomeroy}"] = "{n:0:alliance:Nancy Songflower} (solo hasta 75) {n:0:alliance:Herbalist Pomeroy}",
  ["{n:0:alliance:Emrys Flintbeard} (only up to 75) {n:0:alliance:Reyna Stonebranch} in Ironforge"] = "{n:0:alliance:Emrys Flintbeard} (solo hasta 75) {n:0:alliance:Reyna Stonebranch} en Forjaz",
  ["{n:0:alliance:Eleyna Duskbreeze} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Malorne Bladeleaf} in Dolanaar"] = "{n:0:alliance:Eleyna Duskbreeze} en Aldrassil, Cañada Umbría (solo hasta 75) {n:0:alliance:Malorne Bladeleaf} en Dolanaar",
  ["You can find every Herbalism trainer for Horde and Alliance on my WoW Forever Herbalism Trainers page."] = "Puedes encontrar todos los instructores de Herboristería de la Horda y la Alianza en mi página de instructores de Herboristería de WoW Forever.",
  ["Track Herbs on Your Minimap"] = "Rastrea hierbas en tu minimapa",
  ["You can only track one thing at a time, so {b}you can't track herbs and minerals together{/b}."] = "Solo puedes rastrear una cosa a la vez, así que {b}no puedes rastrear hierbas y minerales a la vez{/b}.",
  ["You learn {s:2383:inv_misc_flower_02:Find Herbs} together with Herbalism, but it's not turned on by default:"] = "Aprendes {s:2383:inv_misc_flower_02:Find Herbs} junto con Herboristería, pero no está activado por defecto:",
  ["Click Find Herbs in the Herbalism box. {b}I recommend dragging it to your action bar, close to the buffs you use after you die.{/b} This way you make a habit out of it and you are less likely to forget it."] = "Haz clic en Buscar hierbas en el recuadro de Herboristería. {b}Te recomiendo arrastrarlo a tu barra de acción, cerca de los beneficios que usas después de morir.{/b} Así lo convertirás en un hábito y será menos probable que lo olvides.",
  ["The Find Herbs buff shows up next to your minimap. {b}Your tracking turns off every time you die, so don't forget to turn it back on!{/b}"] = "El beneficio de Buscar hierbas aparece junto a tu minimapa. {b}Tu rastreo se desactiva cada vez que mueres, ¡así que no olvides volver a activarlo!{/b}",
  ["Herbalism Skill Bonuses"] = "Bonificaciones a la habilidad de Herboristería",
  ["You don't need these, but they help when you are stuck between two herbs. With +5 you can pick Kingsblood from 120 instead of 125, so you can move on earlier."] = "No las necesitas, pero ayudan cuando estás atascado entre dos hierbas. Con +5 puedes recoger Sangrerregia desde 120 en lugar de 125, así que puedes avanzar antes.",
  ["Herbalism"] = "Herboristería",
  ["A world drop, check the Auction House"] = "Botín aleatorio del mundo, mira en la casa de subastas",
  ["Henry Stern in Razorfen Downs teaches the recipe, it {b}requires Cooking 175{/b}. Take the left path at the start of the instance and go all the way to the end, to the stables, knock down the walls and talk to him."] = "Henry Stern, en Zahúrda Rajacieno, enseña la receta; {b}requiere Cocina 175{/b}. Toma el camino de la izquierda al principio de la instancia y ve hasta el final, a los establos, derriba los muros y habla con él.",
  ["can be very handy when you find a herb you can't pick yet and you are only a few points short. It will probably be pretty expensive early on because of the Goldthorn prices, but it's worth keeping a few with you while you level Herbalism."] = "puede ser muy útil cuando encuentras una hierba que aún no puedes recoger y te faltan solo unos pocos puntos. Probablemente sea bastante cara al principio por los precios de la Espina de oro, pero merece la pena llevar unas cuantas encima mientras subes Herboristería.",
  ["Every starting zone is full of herbs, so it doesn't really matter which one you choose. The respawn rate is so fast that without a mount you often can't even finish a full lap, you just run around in circles and pick the herbs as you see them."] = "Todas las zonas iniciales están llenas de hierbas, así que no importa mucho cuál elijas. La reaparición es tan rápida que sin montura muchas veces ni siquiera puedes terminar una vuelta completa; simplemente corres en círculos y recoges las hierbas según las ves.",
  ["Herbs in these zones: {i:2447:inv_misc_flower_02:Peacebloom}, {i:765:inv_misc_herb_10:Silverleaf}, {i:2449:inv_misc_herb_07:Earthroot}"] = "Hierbas en estas zonas: {i:2447:inv_misc_flower_02:Peacebloom}, {i:765:inv_misc_herb_10:Silverleaf}, {i:2449:inv_misc_herb_07:Earthroot}",
  ["Earthroot requires Herbalism 15."] = "La Raíz de tierra requiere Herboristería 15.",
  ["Herbalism route in Durotar"] = "Ruta de herboristería en Durotar",
  ["Herbalism route in Mulgore"] = "Ruta de herboristería en Mulgore",
  ["Herbalism route in Tirisfal Glades"] = "Ruta de herboristería en los Claros de Tirisfal",
  ["{q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} as your reward, it teaches you Herbalism."] = "{q:93552::Harvesting Windstones} es una de las primeras misiones que recibes en la Aldea Thendal. Elige {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} como recompensa, te enseña Herboristería.",
  ["Herbalism route on Zephras Isle"] = "Ruta de herboristería en la Isla Zephras",
  ["Herbalism route in Elwynn Forest"] = "Ruta de herboristería en el Bosque de Elwynn",
  ["Herbalism route in Dun Morogh"] = "Ruta de herboristería en Dun Morogh",
  ["Herbalism route in Teldrassil"] = "Ruta de herboristería en Teldrassil",
  ["Visit your trainer and learn Journeyman Herbalism, it requires Herbalism 50. The new Junior Herbalism Trainers in the starting areas won't teach you Journeyman Herbalism."] = "Visita a tu instructor y aprende Herboristería de Oficial, requiere Herboristería 50. Los nuevos instructores júnior de Herboristería de las zonas iniciales no enseñan Herboristería de Oficial.",
  ["Herbs in these zones: {i:785:inv_jewelry_talisman_03:Mageroyal}, {i:2450:inv_misc_root_01:Briarthorn}, {i:3820:inv_misc_herb_11:Stranglekelp}"] = "Hierbas en estas zonas: {i:785:inv_jewelry_talisman_03:Mageroyal}, {i:2450:inv_misc_root_01:Briarthorn}, {i:3820:inv_misc_herb_11:Stranglekelp}",
  ["Stranglekelp requires Herbalism 85, so you can't pick it right away."] = "El Alga estranguladora requiere Herboristería 85, así que no puedes recogerla enseguida.",
  ["The respawn rate in the lower part of Silverpine Forest is fast enough that you can basically run in small circles in the marked area. I tested this without a mount, so with a mount it might be different, but then running up and down the main road to the loop should work fine as well."] = "En la parte baja del Bosque de Argénteos la reaparición es lo bastante rápida como para que básicamente puedas correr en pequeños círculos por la zona marcada. Lo probé sin montura, así que con montura puede ser diferente, pero entonces correr arriba y abajo por el camino principal hasta el circuito también debería funcionar bien.",
  ["Herbalism route in Silverpine Forest"] = "Ruta de herboristería en el Bosque de Argénteos",
  ["A very easy route to follow, but there might be a bit fewer herbs than in Darkshore."] = "Una ruta muy fácil de seguir, pero puede que haya algunas hierbas menos que en Costa Oscura.",
  ["Herbalism route in Loch Modan"] = "Ruta de herboristería en Loch Modan",
  ["Darkshore has herbs everywhere. I used this loop, but you can also expand it to the upper part of the map. The respawn rate is fast, so you can do smaller circles in different areas. I just found this route pretty easy and chill to follow."] = "Costa Oscura tiene hierbas por todas partes. Yo usé este circuito, pero también puedes ampliarlo a la parte superior del mapa. La reaparición es rápida, así que puedes hacer círculos más pequeños en distintas zonas. A mí esta ruta me pareció bastante fácil y tranquila de seguir.",
  ["Herbalism route in Darkshore"] = "Ruta de herboristería en Costa Oscura",
  ["To train past 150, visit your trainer and learn Expert Herbalism, it requires Herbalism 125."] = "Para entrenar más allá de 150, visita a tu instructor y aprende Herboristería de Experto, requiere Herboristería 125.",
  ["Herbs in these zones: {i:2453:inv_misc_herb_01:Bruiseweed}, {i:3355:inv_misc_flower_01:Wild Steelbloom}, {i:3820:inv_misc_herb_11:Stranglekelp}, {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}"] = "Hierbas en estas zonas: {i:2453:inv_misc_herb_01:Bruiseweed}, {i:3355:inv_misc_flower_01:Wild Steelbloom}, {i:3820:inv_misc_herb_11:Stranglekelp}, {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}",
  ["Kingsblood requires Herbalism 125 and Liferoot 150, so you can't pick them right away."] = "La Sangrerregia requiere Herboristería 125 y la Vidarraíz 150, así que no puedes recogerlas enseguida.",
  ["Running this loop in Hillsbrad Foothills gives the herbs enough time to respawn, but I tested it without a mount, so with a mount it might be different."] = "Hacer este circuito en las Laderas de Trabalomas da a las hierbas tiempo suficiente para reaparecer, pero lo probé sin montura, así que con montura puede ser diferente.",
  ["Herbalism route in Hillsbrad Foothills"] = "Ruta de herboristería en las Laderas de Trabalomas",
  ["All three areas are good here:"] = "Aquí las tres zonas son buenas:",
  ["The mobs here are only around level 14-15, so this is the lowest level area where you can safely farm these herbs."] = "Los enemigos aquí son solo de nivel 14-15, así que es la zona de nivel más bajo donde puedes recoger estas hierbas con seguridad.",
  ["A good alternative if someone is already farming the first area. The mobs are higher level here, around 25."] = "Una buena alternativa si alguien ya está recogiendo en la primera zona. Aquí los enemigos son de nivel más alto, alrededor de 25.",
  ["This area is usually pretty crowded and full of mobs. {b}I only recommend it if you are over 125 already{/b}, because there is more Kingsblood here."] = "Esta zona suele estar bastante concurrida y llena de enemigos. {b}Solo la recomiendo si ya estás por encima de 125{/b}, porque aquí hay más Sangrerregia.",
  ["Herbalism route in Stonetalon Mountains"] = "Ruta de herboristería en la Sierra Espolón",
  ["From this point the guide follows the standard Classic Herbalism routes. The beta cap was 30, so I couldn't test the higher level routes. I'll revise this section once I level my character higher on live, but the main change is the herb respawn rate, so most routes should work."] = "A partir de aquí la guía sigue las rutas de herboristería estándar de Classic. El nivel máximo de la beta era 30, así que no pude probar las rutas de nivel más alto. Revisaré esta sección cuando suba más mi personaje en el servidor real, pero el cambio principal es la reaparición de las hierbas, así que la mayoría de las rutas deberían funcionar.",
  ["Herbs in these zones: {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}, {i:3818:inv_misc_herb_12:Fadeleaf}, {i:3821:inv_misc_herb_15:Goldthorn}, {i:3358:inv_misc_herb_08:Khadgar's Whisker}"] = "Hierbas en estas zonas: {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}, {i:3818:inv_misc_herb_12:Fadeleaf}, {i:3821:inv_misc_herb_15:Goldthorn}, {i:3358:inv_misc_herb_08:Khadgar's Whisker}",
  ["Khadgar's Whisker requires Herbalism 185, so you can't pick it right away."] = "El Mostacho de Khadgar requiere Herboristería 185, así que no puedes recogerlo enseguida.",
  ["Stranglethorn Vale"] = "Vega de Tuercespina",
  ["Herbalism route in Stranglethorn Vale"] = "Ruta de herboristería en la Vega de Tuercespina",
  ["Herbalism route in Arathi Highlands"] = "Ruta de herboristería en las Tierras Altas de Arathi",
  ["{b}Learn Artisan Herbalism before you leave for these zones{/b}, it requires Herbalism 200. There is no trainer in Tanaris or Searing Gorge, so if you skip it, you have to fly back at 225."] = "{b}Aprende Herboristería de Artesano antes de ir a estas zonas{/b}, requiere Herboristería 200. No hay instructor en Tanaris ni en La Garganta de Fuego, así que si te lo saltas tendrás que volver volando en 225.",
  ["Herbs in these zones: {i:8831:inv_misc_herb_17:Purple Lotus}, {i:4625:inv_misc_herb_19:Firebloom}"] = "Hierbas en estas zonas: {i:8831:inv_misc_herb_17:Purple Lotus}, {i:4625:inv_misc_herb_19:Firebloom}",
  ["Searing Gorge"] = "La Garganta de Fuego",
  ["Herbalism route in Tanaris"] = "Ruta de herboristería en Tanaris",
  ["Herbalism route in Searing Gorge"] = "Ruta de herboristería en La Garganta de Fuego",
  ["Herbs in The Hinterlands: {i:8838:inv_misc_herb_18:Sungrass}, {i:8831:inv_misc_herb_17:Purple Lotus}, {i:8845:inv_mushroom_08:Ghost Mushroom}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}"] = "Hierbas en las Tierras del Interior: {i:8838:inv_misc_herb_18:Sungrass}, {i:8831:inv_misc_herb_17:Purple Lotus}, {i:8845:inv_mushroom_08:Ghost Mushroom}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}",
  ["I marked a cave with a red X, there are a lot of Ghost Mushrooms in the cave, but you can only pick them with Herbalism 245."] = "He marcado una cueva con una X roja; dentro hay muchos Champiñones fantasma, pero solo puedes recogerlos con Herboristería 245.",
  ["Herbalism route in The Hinterlands"] = "Ruta de herboristería en las Tierras del Interior",
  ["Herbs in Felwood: {i:8838:inv_misc_herb_18:Sungrass}, {i:8846:inv_misc_herb_16:Gromsblood}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}, {i:13463:inv_misc_herb_dreamfoil:Dreamfoil}, {i:13465:inv_misc_herb_mountainsilversage:Mountain Silversage}, {i:13466:inv_misc_herb_plaguebloom:Plaguebloom}"] = "Hierbas en Frondavil: {i:8838:inv_misc_herb_18:Sungrass}, {i:8846:inv_misc_herb_16:Gromsblood}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}, {i:13463:inv_misc_herb_dreamfoil:Dreamfoil}, {i:13465:inv_misc_herb_mountainsilversage:Mountain Silversage}, {i:13466:inv_misc_herb_plaguebloom:Plaguebloom}",
  ["Herbalism route in Felwood"] = "Ruta de herboristería en Frondavil",
  ["This WoW Forever Skinning leveling guide will show you the fastest way to level Skinning from 1 to 300. You will also find every trainer location and the best places to skin for each skill range."] = "Esta guía de Desuello para WoW Forever te mostrará la forma más rápida de subir Desuello de 1 a 300. También encontrarás la ubicación de todos los instructores y los mejores sitios para desollar en cada rango de habilidad.",
  ["This guide is aimed at higher level players who want to switch their profession, but it's good for lower level players too. Leveling Skinning is easy but really boring, you will have to run around and skin hundreds of mobs. Skinning goes well with Leatherworking because you can use the leather you skin, so check out my Forever Leatherworking leveling guide if you want to level Leatherworking."] = "Esta guía está pensada para jugadores de nivel alto que quieren cambiar de profesión, pero también sirve para jugadores de nivel bajo. Subir Desuello es fácil pero muy aburrido: tendrás que ir de un lado a otro desollando cientos de enemigos. El Desuello combina bien con Peletería porque puedes usar el cuero que desuellas, así que echa un vistazo a mi guía de Peletería para Forever si quieres subir Peletería.",
  ["Skinning Trainer Locations"] = "Ubicación de los instructores de Desuello",
  ["Every capital city has a Skinning trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "Todas las capitales tienen un instructor de Desuello. También puedes preguntar a un guardia y quedará marcado con una bandera roja en tu mapa.",
  ["Undercity: {n:0:horde:Killian Hagey}"] = "Entrañas: {n:0:horde:Killian Hagey}",
  ["Thunder Bluff: {n:0:horde:Mooranta}"] = "Cima del Trueno: {n:0:horde:Mooranta}",
  ["{n:0:horde:Kagil} in the Valley of Trials (only up to 75) {n:0:horde:Thuwd} in Orgrimmar"] = "{n:0:horde:Kagil} en el Valle de los Retos (solo hasta 75) {n:0:horde:Thuwd} en Orgrimmar",
  ["{n:0:horde:Nawka Wildsong} in Camp Narache (only up to 75) {n:0:horde:Yonn Deepcut} in Bloodhoof Village"] = "{n:0:horde:Nawka Wildsong} en el Campamento Narache (solo hasta 75) {n:0:horde:Yonn Deepcut} en el Poblado Pezuña de Sangre",
  ["{n:0:horde:Margaret Weaver} in Deathknell (only up to 75) {n:0:horde:Rand Rhobart} in Tirisfal Glades"] = "{n:0:horde:Margaret Weaver} en Camposanto (solo hasta 75) {n:0:horde:Rand Rhobart} en los Claros de Tirisfal",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247846:inv_10_specialization_professionbook_skinning_color1:Pelt Collecting for Beginners} as your reward, it teaches you Skinning. The trainers on the island are {n:0::Ishlee Breezewhisper} in Valanaar and {n:0::Mendalass Tattermend} in Shen'dar Village."] = "No hay instructor en la Aldea Thendal, donde empiezas, pero no lo necesitas. {q:93552::Harvesting Windstones} es una de las primeras misiones que recibes en la Aldea Thendal. Elige {i:247846:inv_10_specialization_professionbook_skinning_color1:Pelt Collecting for Beginners} como recompensa, te enseña Desuello. Los instructores de la isla son {n:0::Ishlee Breezewhisper} en Valanaar y {n:0::Mendalass Tattermend} en la Aldea Shen'dar.",
  ["Stormwind City: {n:0:alliance:Maris Granger}"] = "Ventormenta: {n:0:alliance:Maris Granger}",
  ["Ironforge: {n:0:alliance:Balthus Stoneflayer}"] = "Forjaz: {n:0:alliance:Balthus Stoneflayer}",
  ["{n:0:alliance:Riley Peltskinner} in Northshire Valley (only up to 75) {n:0:alliance:Helene Peltskinner} in Goldshire"] = "{n:0:alliance:Riley Peltskinner} en el Valle de Villanorte (solo hasta 75) {n:0:alliance:Helene Peltskinner} en Villadorada",
  ["{n:0:alliance:Brighid Stormflayer} (only up to 75) {n:0:alliance:Balthus Stoneflayer} in Ironforge"] = "{n:0:alliance:Brighid Stormflayer} (solo hasta 75) {n:0:alliance:Balthus Stoneflayer} en Forjaz",
  ["{n:0:alliance:Terunne Bearshaper} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Radnaal Maneweaver} in Teldrassil"] = "{n:0:alliance:Terunne Bearshaper} en Aldrassil, Cañada Umbría (solo hasta 75) {n:0:alliance:Radnaal Maneweaver} en Teldrassil",
  ["You can find every Skinning trainer for Horde and Alliance on my WoW Forever Skinning Trainers page."] = "Puedes encontrar todos los instructores de Desuello de la Horda y la Alianza en mi página de instructores de Desuello de WoW Forever.",
  ["Skinning Skill Requirements"] = "Requisitos de habilidad de Desuello",
  ["You need 5 times the mob's level in Skinning to skin it, so a level 30 mob needs Skinning 150. Below level 20 it's less, if you follow the guide you don't have to worry about this."] = "Necesitas 5 veces el nivel del enemigo en Desuello para desollarlo, así que un enemigo de nivel 30 necesita Desuello 150. Por debajo del nivel 20 es menos; si sigues la guía no tienes que preocuparte por esto.",
  ["Mob level"] = "Nivel del enemigo",
  ["Skinning needed"] = "Desuello necesario",
  ["10 for a level 11 mob, 10 more for every level (level 15 needs 50, level 19 needs 90)"] = "10 para un enemigo de nivel 11, 10 más por cada nivel (nivel 15 necesita 50, nivel 19 necesita 90)",
  ["20 and up"] = "20 y más",
  ["5 times the level"] = "5 veces el nivel",
  ["If you enchant your gloves with {s:13698:spell_holy_greaterheal:Enchant Gloves - Skinning}, you can skin mobs 1 level higher than normal."] = "Si encantas tus guantes con {s:13698:spell_holy_greaterheal:Enchant Gloves - Skinning}, puedes desollar enemigos 1 nivel más alto de lo normal.",
  ["Horde players can also pick the {i:269716:inv_weapon_shortblade_05:Keen Skinning Knife} (+3 Skinning) as a reward from Unwelcome Guests in The Barrens."] = "Los jugadores de la Horda también pueden elegir el {i:269716:inv_weapon_shortblade_05:Keen Skinning Knife} (+3 Desuello) como recompensa de Unwelcome Guests en Los Baldíos.",
  ["In WoW Forever you can skin the mobs in the starting areas, and they give skill points all the way up to 75."] = "En WoW Forever puedes desollar a los enemigos de las zonas iniciales, y dan puntos de habilidad hasta 75.",
  ["{b}Any starting zone is good{/b} for this. If you are leveling a new character, you can skin any mob in your starting zone, so you don't need a recommendation until around level 10, when you leave the zone. The two places below are for players who already have a higher level character and want to catch up on Skinning. A lot of players will be leveling new characters there, so there is always something to skin."] = "{b}Cualquier zona inicial sirve{/b} para esto. Si estás subiendo un personaje nuevo, puedes desollar a cualquier enemigo de tu zona inicial, así que no necesitas recomendaciones hasta alrededor del nivel 10, cuando dejas la zona. Los dos sitios de abajo son para jugadores que ya tienen un personaje de nivel más alto y quieren ponerse al día con Desuello. Muchos jugadores estarán subiendo personajes nuevos allí, así que siempre hay algo que desollar.",
  ["{b}Don't forget to buy a {i:7005:inv_weapon_shortblade_01:Skinning Knife}!{/b} The Leatherworking Supply vendors near your trainer and most General Goods vendors sell it. You don't have to equip it, but you can't skin without one in your bags."] = "{b}¡No olvides comprar un {i:7005:inv_weapon_shortblade_01:Skinning Knife}!{/b} Lo venden los vendedores de suministros de peletería cerca de tu instructor y la mayoría de los vendedores de víveres. No tienes que equipártelo, pero no puedes desollar sin uno en tus bolsas.",
  ["Skin the {n:3098::Mottled Boars} in the Valley of Trials in Durotar."] = "Desuella a los {n:3098::Mottled Boars} del Valle de los Retos, en Durotar.",
  ["{b}Mob level:{/b} 1-2"] = "{b}Nivel del enemigo:{/b} 1-2",
  ["The Mottled Boars in the Valley of Trials in Durotar"] = "Los jabalíes moteados del Valle de los Retos, en Durotar",
  ["Skin the {n:299::Young Wolves} and {n:69::Timber Wolves} in Northshire Valley in Elwynn Forest."] = "Desuella a los {n:299::Young Wolves} y {n:69::Timber Wolves} del Valle de Villanorte, en el Bosque de Elwynn.",
  ["The wolves in Northshire Valley in Elwynn Forest"] = "Los lobos del Valle de Villanorte, en el Bosque de Elwynn",
  ["Visit your trainer and learn Journeyman Skinning if you haven't yet, it requires Skinning 50. The new Junior Skinning Trainers in the starting areas won't teach you Journeyman Skinning."] = "Visita a tu instructor y aprende Desuello de Oficial si aún no lo has hecho, requiere Desuello 50. Los nuevos instructores júnior de Desuello de las zonas iniciales no enseñan Desuello de Oficial.",
  ["To train past 150, visit your trainer again and learn Expert Skinning when you reach 125."] = "Para entrenar más allá de 150, vuelve a visitar a tu instructor y aprende Desuello de Experto cuando llegues a 125.",
  ["Kill and skin {n:3256::Sunscale Scytheclaw}, {n:3426::Zhevra Charger}, {n:3245::Ornery Plainstrider}."] = "Mata y desuella {n:3256::Sunscale Scytheclaw}, {n:3426::Zhevra Charger}, {n:3245::Ornery Plainstrider}.",
  ["Go to the small raptor camp just west of Northwatch Hold. Skin the level 16-17 ones until 80, from 80 you can skin the level 18 ones too. Stay here until 150, the last 10 points are green but the respawn is fast."] = "Ve al pequeño campamento de raptores justo al oeste del Bastión Vigía del Norte. Desuella a los de nivel 16-17 hasta 80; a partir de 80 también puedes desollar a los de nivel 18. Quédate aquí hasta 150; los últimos 10 puntos están en verde, pero la reaparición es rápida.",
  ["{b}Mob level:{/b} 16-18"] = "{b}Nivel del enemigo:{/b} 16-18",
  ["The Sunscale Scytheclaws west of Northwatch Hold in the Barrens"] = "Las Guadañas Escamasol al oeste del Bastión Vigía del Norte, en Los Baldíos",
  ["Kill and skin {n:1192::Elder Mountain Boar}, {n:1189::Black Bear Patriarch}."] = "Mata y desuella {n:1192::Elder Mountain Boar}, {n:1189::Black Bear Patriarch}.",
  ["{n:1693::Loch Crocolisk} are also skinnable, make sure to pull them when you get to the shore."] = "Los {n:1693::Loch Crocolisk} también se pueden desollar, asegúrate de atraerlos cuando llegues a la orilla.",
  ["Stay here until around 125, then head north to the Wetlands, it is on the way to Hillsbrad."] = "Quédate aquí hasta alrededor de 125 y luego ve al norte, a Los Humedales, que está de camino a Trabalomas.",
  ["{b}Mob level:{/b} 16-17"] = "{b}Nivel del enemigo:{/b} 16-17",
  ["Skinning spot in Loch Modan"] = "Sitio de desuello en Loch Modan",
  ["125-150 Wetlands"] = "125-150 Los Humedales",
  ["Kill and skin {n:1022::Mottled Scytheclaw}, {n:1023::Mottled Razormaw}."] = "Mata y desuella {n:1022::Mottled Scytheclaw}, {n:1023::Mottled Razormaw}.",
  ["There are always a few of them at Whelgar's Excavation Site, so you never run out of mobs to kill."] = "Siempre hay unos cuantos en la Excavación de Whelgar, así que nunca te quedarás sin enemigos que matar.",
  ["{b}Mob level:{/b} 25-27"] = "{b}Nivel del enemigo:{/b} 25-27",
  ["Whelgar's Excavation Site in the Wetlands"] = "La Excavación de Whelgar, en Los Humedales",
  ["From 150, go to the Foothill Caverns in Hillsbrad Foothills, the yeti cave on the border of Alterac Mountains, or to the Rotting Orchard in Duskwood."] = "A partir de 150, ve a las Cavernas de las Laderas, en las Laderas de Trabalomas (la cueva de yetis en la frontera con las Montañas de Alterac), o al Huerto Podrido, en el Bosque del Ocaso.",
  ["Duskwood"] = "Bosque del Ocaso",
  ["Both factions can get there, Horde from Tarren Mill and Alliance from Southshore."] = "Ambas facciones pueden llegar: la Horda desde Molino Tarren y la Alianza desde Costasur.",
  ["Kill and skin {n:2248::Cave Yeti}, {n:2249::Ferocious Yeti}."] = "Mata y desuella {n:2248::Cave Yeti}, {n:2249::Ferocious Yeti}.",
  ["The yetis respawn so fast that you can stay inside the cave the whole time."] = "Los yetis reaparecen tan rápido que puedes quedarte dentro de la cueva todo el tiempo.",
  ["{b}Mob level:{/b} 30-32"] = "{b}Nivel del enemigo:{/b} 30-32",
  ["The Foothill Caverns in Hillsbrad Foothills"] = "Las Cavernas de las Laderas, en las Laderas de Trabalomas",
  ["Duskwood is an Alliance zone, but Grom'gol is close, so Horde players can get there too."] = "El Bosque del Ocaso es una zona de la Alianza, pero Grom'gol está cerca, así que los jugadores de la Horda también pueden llegar.",
  ["Kill and skin {n:898::Nightbane Worgen}, {n:533::Nightbane Shadow Weaver}, {n:205::Nightbane Dark Runner}."] = "Mata y desuella {n:898::Nightbane Worgen}, {n:533::Nightbane Shadow Weaver}, {n:205::Nightbane Dark Runner}.",
  ["Start at the area marked with 1, clear the mobs outside and inside Roland's Doom cave, then go to the Rotting Orchard until the mobs respawn."] = "Empieza en la zona marcada con el 1, limpia a los enemigos de fuera y de dentro de la cueva de la Condena de Roland y luego ve al Huerto Podrido hasta que reaparezcan.",
  ["{b}Mob level:{/b} 26-29"] = "{b}Nivel del enemigo:{/b} 26-29",
  ["Roland's Doom and the Rotting Orchard in Duskwood"] = "La Condena de Roland y el Huerto Podrido, en el Bosque del Ocaso",
  ["Visit your trainer and learn Artisan Skinning, it requires Skinning 200."] = "Visita a tu instructor y aprende Desuello de Artesano, requiere Desuello 200.",
  ["Mount up and go to the yeti cave at Feral Scar Vale in the south of Feralas. Both factions can get there, Horde from Camp Mojache and Alliance from Feathermoon Stronghold."] = "Móntate y ve a la cueva de yetis del Valle Cicatriz Feral, al sur de Feralas. Ambas facciones pueden llegar: la Horda desde el Campamento Mojache y la Alianza desde el Bastión Plumaluna.",
  ["Kill and skin {n:5292::Feral Scar Yeti}, {n:5295::Enraged Feral Scar}, {n:5293::Hulking Feral Scar}."] = "Mata y desuella {n:5292::Feral Scar Yeti}, {n:5295::Enraged Feral Scar}, {n:5293::Hulking Feral Scar}.",
  ["{b}Mob level:{/b} 43-46"] = "{b}Nivel del enemigo:{/b} 43-46",
  ["The yeti cave at Feral Scar Vale in Feralas"] = "La cueva de yetis del Valle Cicatriz Feral, en Feralas",
  ["From 280, fly to Marshal's Refuge and skin the dinosaurs in the western part of Un'Goro Crater."] = "A partir de 280, vuela al Refugio del Mariscal y desuella a los dinosaurios de la parte oeste del Cráter de Un'Goro.",
  ["Kill and skin {n:9163::Diemetradon}, {n:9166::Pterrordax}, {n:9164::Elder Diemetradon}, {n:9167::Frenzied Pterrordax}."] = "Mata y desuella {n:9163::Diemetradon}, {n:9166::Pterrordax}, {n:9164::Elder Diemetradon}, {n:9167::Frenzied Pterrordax}.",
  ["{b}Mob level:{/b} 50-55"] = "{b}Nivel del enemigo:{/b} 50-55",
  ["The dinosaur area in the west of Un'Goro Crater"] = "La zona de dinosaurios al oeste del Cráter de Un'Goro",
  ["This WoW Forever Fishing and Cooking leveling guide will show you the fastest way to level Fishing and Cooking together from 1 to 300."] = "Esta guía de Pesca y Cocina para WoW Forever te mostrará la forma más rápida de subir Pesca y Cocina juntas de 1 a 300.",
  ["Leveling Fishing takes a long time, so it's best to level these two together, because every fish you catch is also a Cooking recipe and your Cooking goes up for free while you fish. You will still need a lot of patience because you have to catch a lot of fish to get from start to finish. If you only want one of them, use my Fishing guide or my Cooking guide instead."] = "Subir Pesca lleva mucho tiempo, así que es mejor subir estas dos juntas, porque cada pez que pescas es también una receta de Cocina y tu Cocina sube gratis mientras pescas. Aun así necesitarás mucha paciencia, porque tienes que pescar muchísimos peces para llegar de principio a fin. Si solo quieres una de las dos, usa mi guía de Pesca o mi guía de Cocina.",
  ["Level Fishing to 75"] = "Sube Pesca a 75",
  ["If you can choose, {b}level Fishing in Mulgore{/b}, because everything is close together there. {n:0::Harn Longcast} in Bloodhoof Village sells both recipes and the pole, and the Fishing trainer stands at Stonebull Lake. Thunder Bluff, where you fish after 75, is right next to it."] = "Si puedes elegir, {b}sube Pesca en Mulgore{/b}, porque allí todo está cerca. {n:0::Harn Longcast}, en el Poblado Pezuña de Sangre, vende las dos recetas y la caña, y el instructor de Pesca está en el Lago Toro de Piedra. Cima del Trueno, donde pescas después de 75, está justo al lado.",
  ["If you haven't learned Fishing yet, learn it from {n:0::Lau'Tiki} on the coast south of Sen'jin Village."] = "Si aún no has aprendido Pesca, apréndela con {n:0::Lau'Tiki} en la costa al sur de la Aldea Sen'jin.",
  ["Buy {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} from {n:0::Zansoa} in Sen'jin Village. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Compra {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} a {n:0::Zansoa} en la Aldea Sen'jin. Compra allí también una {i:6256:inv_fishingpole_02:Fishing Pole} y un {i:6529:inv_misc_orb_03:Shiny Bauble}. (Compra cualquier {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que veas y guárdalo para más tarde.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish on the coast next to {n:0::Lau'Tiki}, south of Sen'jin Village, until your Fishing skill reaches 75. Almost everything you catch there is {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel}, about 70 of them."] = "Equípate la caña de pescar, ponle un {i:6529:inv_misc_orb_03:Shiny Bauble} y pesca en la costa junto a {n:0::Lau'Tiki}, al sur de la Aldea Sen'jin, hasta que tu habilidad de Pesca llegue a 75. Casi todo lo que pesques allí será {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel}, unos 70.",
  ["Learn Journeyman Fishing from {n:0::Lau'Tiki}, it requires level 10."] = "Aprende Pesca de Oficial con {n:0::Lau'Tiki}, requiere nivel 10.",
  ["The coast south of Sen'jin Village in Durotar, where to fish from 1 to 75"] = "La costa al sur de la Aldea Sen'jin, en Durotar, donde pescar de 1 a 75",
  ["If you haven't learned Fishing yet, learn it from {n:0::Uthan Stillwater} at Stonebull Lake."] = "Si aún no has aprendido Pesca, apréndela con {n:0::Uthan Stillwater} en el Lago Toro de Piedra.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Harn Longcast} in Bloodhoof Village. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Compra {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} y {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} a {n:0::Harn Longcast} en el Poblado Pezuña de Sangre. Compra allí también una {i:6256:inv_fishingpole_02:Fishing Pole} y un {i:6529:inv_misc_orb_03:Shiny Bauble}. (Compra cualquier {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que veas y guárdalo para más tarde.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Stonebull Lake until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "Equípate la caña de pescar, ponle un {i:6529:inv_misc_orb_03:Shiny Bauble} y pesca en el Lago Toro de Piedra hasta que tu habilidad de Pesca llegue a 75. Pescarás unos 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} y 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}.",
  ["Learn Journeyman Fishing from {n:0::Uthan Stillwater}, it requires level 10."] = "Aprende Pesca de Oficial con {n:0::Uthan Stillwater}, requiere nivel 10.",
  ["Stonebull Lake around Bloodhoof Village in Mulgore, where to fish from 1 to 75"] = "El Lago Toro de Piedra, alrededor del Poblado Pezuña de Sangre en Mulgore, donde pescar de 1 a 75",
  ["If you haven't learned Fishing yet, learn it from {n:0::Clyde Kellen} at Brightwater Lake."] = "Si aún no has aprendido Pesca, apréndela con {n:0::Clyde Kellen} en el Lago Aguasclaras.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Martine Tramblay} at the Death's Watch Waystation, south-east of Brill. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Compra {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} a {n:0::Martine Tramblay} en la parada de Death's Watch, al sureste de Rémol. Compra allí también una {i:6256:inv_fishingpole_02:Fishing Pole} y un {i:6529:inv_misc_orb_03:Shiny Bauble}. (Compra cualquier {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que veas y guárdalo para más tarde.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Brightwater Lake until your Fishing skill reaches 75. You will catch about 30 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 20 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, plus some {i:6299:inv_misc_fish_28:Sickly Looking Fish} and junk."] = "Equípate la caña de pescar, ponle un {i:6529:inv_misc_orb_03:Shiny Bauble} y pesca en el Lago Aguasclaras hasta que tu habilidad de Pesca llegue a 75. Pescarás unos 30 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} y 20 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, además de algunos {i:6299:inv_misc_fish_28:Sickly Looking Fish} y chatarra.",
  ["Learn Journeyman Fishing from {n:0::Clyde Kellen}, it requires level 10."] = "Aprende Pesca de Oficial con {n:0::Clyde Kellen}, requiere nivel 10.",
  ["Brightwater Lake east of Brill in Tirisfal Glades, where to fish from 1 to 75"] = "El Lago Aguasclaras al este de Rémol, en los Claros de Tirisfal, donde pescar de 1 a 75",
  ["If you haven't learned Fishing yet, learn it from {n:0::Fenn Fairweather} in Shen'dar Village or {n:0::Baelann Swiftcurrent} in Valanaar."] = "Si aún no has aprendido Pesca, apréndela con {n:0::Fenn Fairweather} en la Aldea Shen'dar o con {n:0::Baelann Swiftcurrent} en Valanaar.",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} from {n:0::Belandiel Farflight} in Shen'dar Village or {n:0::Baelann Swiftcurrent} in Valanaar. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Compra una {i:6256:inv_fishingpole_02:Fishing Pole} y un {i:6529:inv_misc_orb_03:Shiny Bauble} a {n:0::Belandiel Farflight} en la Aldea Shen'dar o a {n:0::Baelann Swiftcurrent} en Valanaar. (Compra cualquier {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que veas y guárdalo para más tarde.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in any lake or river on Zephras Isle until your Fishing skill reaches 75, for example next to the Fishing trainers in Shen'dar Village and Valanaar. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}. Keep all the fish you catch."] = "Equípate la caña de pescar, ponle un {i:6529:inv_misc_orb_03:Shiny Bauble} y pesca en cualquier lago o río de la Isla Zephras hasta que tu habilidad de Pesca llegue a 75, por ejemplo junto a los instructores de Pesca de la Aldea Shen'dar y Valanaar. Pescarás unos 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} y 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}. Guarda todos los peces que pesques.",
  ["Learn Journeyman Fishing from {n:0::Fenn Fairweather} or {n:0::Baelann Swiftcurrent}, it requires level 10."] = "Aprende Pesca de Oficial con {n:0::Fenn Fairweather} o {n:0::Baelann Swiftcurrent}, requiere nivel 10.",
  ["When you get to Thunder Bluff, buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Sewa Mistrunner} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Naal Mistrunner}. They stand next to each other."] = "Cuando llegues a Cima del Trueno, compra {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} a {n:0::Sewa Mistrunner} y {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} a {n:0::Naal Mistrunner}. Están uno al lado del otro.",
  ["The water at Shen'dar Village and Valanaar on Zephras Isle, where to fish from 1 to 75"] = "El agua de la Aldea Shen'dar y Valanaar, en la Isla Zephras, donde pescar de 1 a 75",
  ["If you can choose, {b}level Fishing in Elwynn Forest{/b}, because everything is close together there. {n:0::Tharynn Bouden} in Goldshire sells both recipes and the pole, and the Fishing trainer stands at Crystal Lake. Stormwind City, where you fish after 75, is right next to it."] = "Si puedes elegir, {b}sube Pesca en el Bosque de Elwynn{/b}, porque allí todo está cerca. {n:0::Tharynn Bouden}, en Villadorada, vende las dos recetas y la caña, y el instructor de Pesca está en el Lago de Cristal. Ventormenta, donde pescas después de 75, está justo al lado.",
  ["If you haven't learned Fishing yet, learn it from {n:0::Lee Brown} at Crystal Lake."] = "Si aún no has aprendido Pesca, apréndela con {n:0::Lee Brown} en el Lago de Cristal.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Tharynn Bouden} in Goldshire. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Compra {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} y {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} a {n:0::Tharynn Bouden} en Villadorada. Compra allí también una {i:6256:inv_fishingpole_02:Fishing Pole} y un {i:6529:inv_misc_orb_03:Shiny Bauble}. (Compra cualquier {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que veas y guárdalo para más tarde.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Crystal Lake, east of Goldshire, until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "Equípate la caña de pescar, ponle un {i:6529:inv_misc_orb_03:Shiny Bauble} y pesca en el Lago de Cristal, al este de Villadorada, hasta que tu habilidad de Pesca llegue a 75. Pescarás unos 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} y 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}.",
  ["Learn Journeyman Fishing from {n:0::Lee Brown}, it requires level 10."] = "Aprende Pesca de Oficial con {n:0::Lee Brown}, requiere nivel 10.",
  ["Crystal Lake east of Goldshire in Elwynn Forest, where to fish from 1 to 75"] = "El Lago de Cristal al este de Villadorada, en el Bosque de Elwynn, donde pescar de 1 a 75",
  ["If you haven't learned Fishing yet, learn it from {n:0::Paxton Ganter} at Iceflow Lake."] = "Si aún no has aprendido Pesca, apréndela con {n:0::Paxton Ganter} en el Lago Flujohelado.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Gretta Ganter} at Iceflow Lake. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Compra {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} a {n:0::Gretta Ganter} en el Lago Flujohelado. Compra allí también una {i:6256:inv_fishingpole_02:Fishing Pole} y un {i:6529:inv_misc_orb_03:Shiny Bauble}. (Compra cualquier {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que veas y guárdalo para más tarde.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Iceflow Lake until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "Equípate la caña de pescar, ponle un {i:6529:inv_misc_orb_03:Shiny Bauble} y pesca en el Lago Flujohelado hasta que tu habilidad de Pesca llegue a 75. Pescarás unos 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} y 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}.",
  ["Learn Journeyman Fishing from {n:0::Paxton Ganter}, it requires level 10."] = "Aprende Pesca de Oficial con {n:0::Paxton Ganter}, requiere nivel 10.",
  ["Iceflow Lake in Dun Morogh, where to fish from 1 to 75"] = "El Lago Flujohelado, en Dun Morogh, donde pescar de 1 a 75",
  ["Learn Fishing from {n:0::Astaia} in Darnassus. There is no Fishing trainer in Dolanaar."] = "Aprende Pesca con {n:0::Astaia} en Darnassus. No hay instructor de Pesca en Dolanaar.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Nyoma} in Dolanaar."] = "Compra {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} y {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} a {n:0::Nyoma} en Dolanaar.",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} from {n:0::Narret Shadowgrove} in Dolanaar. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Compra una {i:6256:inv_fishingpole_02:Fishing Pole} y un {i:6529:inv_misc_orb_03:Shiny Bauble} a {n:0::Narret Shadowgrove} en Dolanaar. (Compra cualquier {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que veas y guárdalo para más tarde.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Lake Al'Ameth, south of Dolanaar, until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "Equípate la caña de pescar, ponle un {i:6529:inv_misc_orb_03:Shiny Bauble} y pesca en el Lago Al'Ameth, al sur de Dolanaar, hasta que tu habilidad de Pesca llegue a 75. Pescarás unos 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} y 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}.",
  ["Learn Journeyman Fishing from {n:0::Astaia} in Darnassus, it requires level 10."] = "Aprende Pesca de Oficial con {n:0::Astaia} en Darnassus, requiere nivel 10.",
  ["Lake Al'Ameth south of Dolanaar in Teldrassil, where to fish from 1 to 75"] = "El Lago Al'Ameth al sur de Dolanaar, en Teldrassil, donde pescar de 1 a 75",
  ["When you get to Stormwind City, buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Tharynn Bouden} in Goldshire, right outside the city."] = "Cuando llegues a Ventormenta, compra {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} y {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} a {n:0::Tharynn Bouden} en Villadorada, justo a las afueras de la ciudad.",
  ["Fishing (75-130) and Cooking (1-100)"] = "Pesca (75-130) y Cocina (1-100)",
  ["Fishing"] = "Pesca",
  ["Fish in the capital city closest to you until your Fishing skill reaches 130. From 75 no fish gets away in any of them. You should catch about 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "Pesca en la capital más cercana hasta que tu habilidad de Pesca llegue a 130. A partir de 75 no se escapa ningún pez en ninguna de ellas. Deberías pescar unos 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} y 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}.",
  ["{b}Thunder Bluff:{/b} the pond near the Auction House."] = "{b}Cima del Trueno:{/b} el estanque cerca de la casa de subastas.",
  ["{b}Undercity:{/b} the canals. About a third of what you catch here is junk, so you get fewer fish."] = "{b}Entrañas:{/b} los canales. Más o menos un tercio de lo que pescas aquí es chatarra, así que consigues menos peces.",
  ["{b}Orgrimmar:{/b} the pond in the Valley of Honor, where the Fishing trainer stands."] = "{b}Orgrimmar:{/b} el estanque del Valle del Honor, donde está el instructor de Pesca.",
  ["Recipes to buy"] = "Recetas que comprar",
  ["Buy {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} from {n:0::Naal Mistrunner} in Thunder Bluff or {n:0::Ronald Burch} in Undercity, you need it in the next part."] = "Compra {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} a {n:0::Naal Mistrunner} en Cima del Trueno o a {n:0::Ronald Burch} en Entrañas, la necesitas en la siguiente parte.",
  ["If you don't have {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} yet, buy it from {n:0::Naal Mistrunner} in Thunder Bluff or {n:0::Lizbeth Cromwell} in Undercity."] = "Si aún no tienes {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}, cómprala a {n:0::Naal Mistrunner} en Cima del Trueno o a {n:0::Lizbeth Cromwell} en Entrañas.",
  ["Nobody sells them in Orgrimmar, so buy them on the Auction House or in Thunder Bluff."] = "Nadie las vende en Orgrimmar, así que cómpralas en la casa de subastas o en Cima del Trueno.",
  ["Cooking"] = "Cocina",
  ["If you haven't learned Cooking yet, learn it from {n:0::Aska Mistrunner} in Thunder Bluff, {n:0::Eunice Burch} in Undercity or {n:0::Zamja} in Orgrimmar. Then learn {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and cook all your {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} into {s:7751:inv_misc_fish_07:Brilliant Smallfish}. If you caught {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel} in your starting zone, learn {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} and cook them into {s:7752:inv_misc_fish_24:Slitherskin Mackerel} instead. This should take your Cooking skill to 50."] = "Si aún no has aprendido Cocina, apréndela con {n:0::Aska Mistrunner} en Cima del Trueno, {n:0::Eunice Burch} en Entrañas o {n:0::Zamja} en Orgrimmar. Después aprende {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} y cocina todos tus {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} para hacer {s:7751:inv_misc_fish_07:Brilliant Smallfish}. Si pescaste {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel} en tu zona inicial, aprende {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} y cocínalos para hacer {s:7752:inv_misc_fish_24:Slitherskin Mackerel} en su lugar. Con esto tu habilidad de Cocina debería llegar a 50.",
  ["If you are a few points short of 50, catch and cook a few more."] = "Si te faltan unos pocos puntos para 50, pesca y cocina unos cuantos más.",
  ["Learn Journeyman Cooking from the same trainer. Then learn {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} and cook all your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Your Cooking skill should go above 100."] = "Aprende Cocina de Oficial con el mismo instructor. Después aprende {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} y cocina todos tus {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} para hacer {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Tu habilidad de Cocina debería pasar de 100.",
  ["Don't worry if you don't reach 100 Cooking with Longjaw Mud Snapper, you will catch more Raw Longjaw Mud Snapper later."] = "No te preocupes si no llegas a Cocina 100 con el Pargo del barro mandíbula larga; pescarás más Pargos del barro mandíbula larga crudos más adelante.",
  ["Fish in the canals of Stormwind City until your skill reaches 130. You should catch about 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, and 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "Pesca en los canales de Ventormenta hasta que tu habilidad llegue a 130. Deberías pescar unos 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} y 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}.",
  ["Find {n:0::Catherine Leland} in Stormwind City and buy {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish}. If you don't have {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} yet, buy it from {n:0::Tharynn Bouden} in Goldshire."] = "Busca a {n:0::Catherine Leland} en Ventormenta y compra {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish}. Si aún no tienes {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}, cómprala a {n:0::Tharynn Bouden} en Villadorada.",
  ["You should also find {n:0::Ben Trias} and buy 20 {i:8932:inv_misc_food_37:Alterac Swiss} from him. You will need these later for the Artisan Cooking quest."] = "También deberías buscar a {n:0::Ben Trias} y comprarle 20 {i:8932:inv_misc_food_37:Alterac Swiss}. Los necesitarás más adelante para la misión de Cocina de Artesano.",
  ["Learn Cooking from {n:0::Stephen Ryback} if you haven't yet. Then learn {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and cook all your {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} into {s:7751:inv_misc_fish_07:Brilliant Smallfish}. This should take your Cooking skill to 50."] = "Aprende Cocina con {n:0::Stephen Ryback} si aún no lo has hecho. Después aprende {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} y cocina todos tus {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} para hacer {s:7751:inv_misc_fish_07:Brilliant Smallfish}. Con esto tu habilidad de Cocina debería llegar a 50.",
  ["Learn Journeyman Cooking from {n:0::Stephen Ryback} in Stormwind City. Then learn {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} and cook all your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Your Cooking skill should go above 100."] = "Aprende Cocina de Oficial con {n:0::Stephen Ryback} en Ventormenta. Después aprende {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} y cocina todos tus {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} para hacer {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Tu habilidad de Cocina debería pasar de 100.",
  ["Fishing (130-205) and Cooking (100-175)"] = "Pesca (130-205) y Cocina (100-175)",
  ["Expert Fishing needs {b}level 20{/b} and {b}Fishing 125{/b}, Expert Cooking needs {b}Cooking 125{/b}."] = "Pesca de Experto requiere {b}nivel 20{/b} y {b}Pesca 125{/b}; Cocina de Experto requiere {b}Cocina 125{/b}.",
  ["Booty Bay"] = "Bahía del Botín",
  ["Go to Ratchet in The Barrens and take the boat to Booty Bay in Stranglethorn Vale."] = "Ve a Trinquete, en Los Baldíos, y toma el barco a Bahía del Botín, en la Vega de Tuercespina.",
  ["Find {n:0::Old Man Heming} in Booty Bay, buy {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} from him and read it."] = "Busca a {n:0::Old Man Heming} en Bahía del Botín, cómprale {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} y léelo.",
  ["Find {n:0::Kelsey Yance} and buy these two recipes: {i:17062:inv_scroll_03:Recipe: Mithril Head Trout}, {i:13941:inv_scroll_03:Recipe: Filet of Redgill}."] = "Busca a {n:0::Kelsey Yance} y compra estas dos recetas: {i:17062:inv_scroll_03:Recipe: Mithril Head Trout}, {i:13941:inv_scroll_03:Recipe: Filet of Redgill}.",
  ["Go back to The Barrens, then fly from Ratchet to Sun Rock Retreat in Stonetalon Mountains and buy 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0::Kulwia}. You need 2 until 150, keep the other 5 for later."] = "Vuelve a Los Baldíos, vuela desde Trinquete al Refugio Roca del Sol, en la Sierra Espolón, y compra 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} a {n:0::Kulwia}. Necesitas 2 hasta 150; guarda los otros 5 para más tarde.",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the open water until your Fishing skill reaches 205. You will catch about 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "Pon una {i:6530:inv_misc_monstertail_03:Nightcrawler} y pesca en aguas abiertas hasta que tu habilidad de Pesca llegue a 205. Pescarás unos 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} y 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}.",
  ["Fly to Shadowprey Village in Desolace."] = "Vuela a la Aldea Cazasombras, en Desolace.",
  ["Find {n:0::Wulan} and buy the {i:16072:inv_misc_book_08:Expert Cookbook}. He is on the top floor of the eastern-most building in the village."] = "Busca a {n:0::Wulan} y compra el {i:16072:inv_misc_book_08:Expert Cookbook}. Está en el piso de arriba del edificio situado más al este de la aldea.",
  ["Buy 20 {i:8932:inv_misc_food_37:Alterac Swiss} from {n:0::Innkeeper Sikewa}. You will need them for the Artisan Cooking quest."] = "Compra 20 {i:8932:inv_misc_food_37:Alterac Swiss} a {n:0::Innkeeper Sikewa}. Los necesitarás para la misión de Cocina de Artesano.",
  ["Leveling Cooking to 175"] = "Subir Cocina a 175",
  ["Cook your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper} if your Cooking skill is still below 100."] = "Cocina tus {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} para hacer {s:7753:inv_misc_fish_32:Longjaw Mud Snapper} si tu habilidad de Cocina sigue por debajo de 100.",
  ["{b}Read the {i:16072:inv_misc_book_08:Expert Cookbook} as soon as you reach 125{/b}, especially if you go AFK while cooking. Without it you stop getting skill points at 150 and keep cooking for nothing."] = "{b}Lee el {i:16072:inv_misc_book_08:Expert Cookbook} en cuanto llegues a 125{/b}, sobre todo si te pones AFK mientras cocinas. Sin él dejas de obtener puntos de habilidad en 150 y sigues cocinando para nada.",
  ["Learn {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} and cook all your {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} into {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}. Your Cooking skill will hopefully get close to 175."] = "Aprende {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} y cocina todos tus {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} para hacer {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}. Con suerte tu habilidad de Cocina se acercará a 175.",
  ["Don't worry if you don't reach 175 Cooking with Bristle Whisker Catfish, you will catch more Raw Bristle Whisker Catfish later."] = "No te preocupes si no llegas a Cocina 175 con el Bagre bigotes de cerda; pescarás más Bagres bigotes de cerda crudos más adelante.",
  ["Go to Booty Bay in Stranglethorn Vale."] = "Ve a Bahía del Botín, en la Vega de Tuercespina.",
  ["Go to The Barrens, then fly from Ratchet to Astranaar in Ashenvale. Ride south-east to Mystral Lake and buy the {i:16072:inv_misc_book_08:Expert Cookbook} and 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0::Shandrina}. You need 2 until 150, keep the other 5 for later."] = "Ve a Los Baldíos y vuela desde Trinquete a Astranaar, en Vallefresno. Cabalga hacia el sureste hasta el Lago Mystral y compra el {i:16072:inv_misc_book_08:Expert Cookbook} y 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} a {n:0::Shandrina}. Necesitas 2 hasta 150; guarda los otros 5 para más tarde.",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the open water of Mystral Lake until your Fishing skill reaches 205. You will catch about 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "Pon una {i:6530:inv_misc_monstertail_03:Nightcrawler} y pesca en las aguas abiertas del Lago Mystral hasta que tu habilidad de Pesca llegue a 205. Pescarás unos 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} y 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}.",
  ["Artisan Fishing Quest"] = "Misión de Pesca de Artesano",
  ["If you have no {i:6530:inv_misc_monstertail_03:Nightcrawlers} left, buy 5 from {n:0::Kilxx} in The Barrens or {n:0:alliance:Helenia Olden} in Dustwallow Marsh."] = "Si no te quedan {i:6530:inv_misc_monstertail_03:Nightcrawlers}, compra 5 a {n:0::Kilxx} en Los Baldíos o a {n:0:alliance:Helenia Olden} en el Marjal Revolcafango.",
  ["Go to Dustwallow Marsh and {b}fish anywhere in the swamp until your skill reaches 225{/b}. {b}Don't fish in the ocean.{/b} Keep a {i:6530:inv_misc_monstertail_03:Nightcrawler} on your pole until 225, otherwise a few fish get away."] = "Ve al Marjal Revolcafango y {b}pesca en cualquier parte del pantano hasta que tu habilidad llegue a 225{/b}. {b}No pesques en el mar.{/b} Lleva una {i:6530:inv_misc_monstertail_03:Nightcrawler} en la caña hasta 225, si no se escapan algunos peces.",
  ["Find {n:0::Nat Pagle} and accept the quest {q:6607::Nat Pagle, Angler Extreme}. It requires {b}level 35{/b} and {b}Fishing 225{/b}, and you need it to learn Artisan Fishing."] = "Busca a {n:0::Nat Pagle} y acepta la misión {q:6607::Nat Pagle, Angler Extreme}. Requiere {b}nivel 35{/b} y {b}Pesca 225{/b}, y la necesitas para aprender Pesca de Artesano.",
  ["Tidefury Cove, Dustwallow Marsh"] = "Cala Furiamarea, Marjal Revolcafango",
  ["To complete the quest you have to catch 4 quest fish in four different zones:"] = "Para completar la misión tienes que pescar 4 peces de misión en cuatro zonas distintas:",
  ["{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - Feralas (attach the {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you kept, or {i:6532:inv_misc_gem_variety_02:Bright Baubles} from {n:0::Sheendra Tallgrass} / {n:0::Vivianna} in Feralas, otherwise most of them get away)"] = "{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - Feralas (pon el {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que guardaste, o {i:6532:inv_misc_gem_variety_02:Bright Baubles} de {n:0::Sheendra Tallgrass} / {n:0::Vivianna} en Feralas; si no, la mayoría se escapan)",
  ["{i:16970:inv_misc_fish_21:Misty Reed Mahi Mahi} - Swamp of Sorrows"] = "{i:16970:inv_misc_fish_21:Misty Reed Mahi Mahi} - Pantano de las Penas",
  ["{i:16969:inv_misc_fish_08:Savage Coast Blue Sailfin} - Stranglethorn Vale"] = "{i:16969:inv_misc_fish_08:Savage Coast Blue Sailfin} - Vega de Tuercespina",
  ["Nat Pagle, Angler Extreme Quest Fishes"] = "Peces de la misión de Nat Pagle, pescador extremo",
  ["Where to catch the four Nat Pagle quest fish"] = "Dónde pescar los cuatro peces de la misión de Nat Pagle",
  ["Leveling Fishing to 255 and Cooking to 225"] = "Subir Pesca a 255 y Cocina a 225",
  ["After you completed the quest, {b}keep fishing in the swamp in Dustwallow Marsh until your Fishing skill reaches 255.{/b} {b}Don't fish in the ocean{/b}, because there you catch Raw Rockscale Cod instead of the Raw Mithril Head Trout you cook next."] = "Después de completar la misión, {b}sigue pescando en el pantano del Marjal Revolcafango hasta que tu habilidad de Pesca llegue a 255.{/b} {b}No pesques en el mar{/b}, porque allí pescas Bacalao escamarroca crudo en lugar de la Trucha cabeza de mitril cruda que cocinarás a continuación.",
  ["Go back to Brackenwall Village (Horde) / Theramore Isle (Alliance) to cook your fish, or put down a campfire if you have one."] = "Vuelve al Poblado Murohelecho (Horda) / Isla Theramore (Alianza) para cocinar tus peces, o enciende una hoguera si tienes una.",
  ["Cook your {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} into {s:7755:inv_misc_fish_30:Bristle Whisker Catfish} if your Cooking skill is still below 175."] = "Cocina tus {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} para hacer {s:7755:inv_misc_fish_30:Bristle Whisker Catfish} si tu habilidad de Cocina sigue por debajo de 175.",
  ["Learn {i:17062:inv_scroll_03:Recipe: Mithril Head Trout} and cook your {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} into {s:20916:inv_misc_fish_02:Mithril Headed Trout} until 225. Keep the rest, you cook them after the Artisan Cooking quest."] = "Aprende {i:17062:inv_scroll_03:Recipe: Mithril Head Trout} y cocina tus {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} para hacer {s:20916:inv_misc_fish_02:Mithril Headed Trout} hasta 225. Guarda el resto, los cocinarás después de la misión de Cocina de Artesano.",
  ["Artisan Cooking Quest"] = "Misión de Cocina de Artesano",
  ["Fly to Gadgetzan in Tanaris and pick up the quest {q:6610::Clamlette Surprise} from {n:0::Dirge Quikcleave}. The reward is Artisan Cooking. The quest requires {b}level 35{/b} and {b}Cooking 225{/b}. You will need these to complete the quest:"] = "Vuela a Gadgetzan, en Tanaris, y recoge la misión {q:6610::Clamlette Surprise} de {n:0::Dirge Quikcleave}. La recompensa es Cocina de Artesano. La misión requiere {b}nivel 35{/b} y {b}Cocina 225{/b}. Necesitarás esto para completarla:",
  ["12x {i:12207:inv_egg_03:Giant Egg} - dropped by the {n:5428::Rocs}, {n:5429::Fire Rocs} and {n:5430::Searing Rocs} in Tanaris."] = "12x {i:12207:inv_egg_03:Giant Egg} - los sueltan los {n:5428::Rocs}, {n:5429::Fire Rocs} y {n:5430::Searing Rocs} de Tanaris.",
  ["10x {i:7974:inv_misc_food_51:Zesty Clam Meat} - from Big-mouth Clams, dropped by {n:14123::Steeljaw Snappers} and {n:5431::Surf Gliders} in Tanaris."] = "10x {i:7974:inv_misc_food_51:Zesty Clam Meat} - de las Almejas bocazas, que sueltan los {n:14123::Steeljaw Snappers} y los {n:5431::Surf Gliders} de Tanaris.",
  ["20x {i:8932:inv_misc_food_37:Alterac Swiss} - you bought these earlier."] = "20x {i:8932:inv_misc_food_37:Alterac Swiss} - los compraste antes.",
  ["Find {n:0::Gikkix} at Steamwheedle Port in Tanaris and buy {i:13945:inv_scroll_03:Recipe: Nightfin Soup}."] = "Busca a {n:0::Gikkix} en Puerto Bonvapor, Tanaris, y compra {i:13945:inv_scroll_03:Recipe: Nightfin Soup}.",
  ["Fishing to 300 in Feralas"] = "Pesca hasta 300 en Feralas",
  ["Fly to Camp Mojache (Horde) / Feathermoon Stronghold (Alliance) in Feralas."] = "Vuela al Campamento Mojache (Horda) / Bastión Plumaluna (Alianza) en Feralas.",
  ["Buy 12 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0:horde:Sheendra Tallgrass} / {n:0:alliance:Vivianna}."] = "Compra 12 {i:6530:inv_misc_monstertail_03:Nightcrawlers} a {n:0:horde:Sheendra Tallgrass} / {n:0:alliance:Vivianna}.",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the marked lake until you reach Fishing 300, use a new one every 10 minutes. Any other lake or river in Feralas works too, {b}except Jademir Lake{/b}."] = "Pon una {i:6530:inv_misc_monstertail_03:Nightcrawler} y pesca en el lago marcado hasta llegar a Pesca 300; usa una nueva cada 10 minutos. Cualquier otro lago o río de Feralas también sirve, {b}excepto el Lago Jademir{/b}.",
  ["Where to fish in Feralas from 255 to 300"] = "Dónde pescar en Feralas de 255 a 300",
  ["Leveling Cooking to 300"] = "Subir Cocina a 300",
  ["Cook your remaining {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} into {s:20916:inv_misc_fish_02:Mithril Headed Trout} until 250."] = "Cocina las {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} que te quedan para hacer {s:20916:inv_misc_fish_02:Mithril Headed Trout} hasta 250.",
  ["Learn {i:13941:inv_scroll_03:Recipe: Filet of Redgill} and cook your {i:13758:inv_misc_fish_06:Raw Redgill} into {s:18241:inv_misc_fish_06:Filet of Redgill} until 285."] = "Aprende {i:13941:inv_scroll_03:Recipe: Filet of Redgill} y cocina tus {i:13758:inv_misc_fish_06:Raw Redgill} para hacer {s:18241:inv_misc_fish_06:Filet of Redgill} hasta 285.",
  ["Learn {i:13945:inv_scroll_03:Recipe: Nightfin Soup} and cook all your {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} into {s:18243:inv_drink_17:Nightfin Soup}. You also need a {i:159:inv_drink_07:Refreshing Spring Water} for each soup, buy 20 from the innkeeper."] = "Aprende {i:13945:inv_scroll_03:Recipe: Nightfin Soup} y cocina todos tus {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} para hacer {s:18243:inv_drink_17:Nightfin Soup}. También necesitas un {i:159:inv_drink_07:Refreshing Spring Water} por cada sopa; compra 20 al tabernero.",
  ["{i:13759:inv_misc_fish_23:Raw Nightfin Snapper} don't bite in the afternoon (12:00-18:00 game time). If you fished in the afternoon, you will probably not have enough, so cook the rest of your {i:13758:inv_misc_fish_06:Raw Redgill} into {s:18241:inv_misc_fish_06:Filet of Redgill} too, you might reach 300 with them."] = "Los {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} no pican por la tarde (12:00-18:00, hora del juego). Si pescaste por la tarde, probablemente no tengas suficientes, así que cocina también el resto de tus {i:13758:inv_misc_fish_06:Raw Redgill} para hacer {s:18241:inv_misc_fish_06:Filet of Redgill}; puede que llegues a 300 con ellos.",
  ["If you still don't reach 300, fish a bit more outside the afternoon, or buy a few {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} on the Auction House."] = "Si aun así no llegas a 300, pesca un poco más fuera de la franja de la tarde o compra unos cuantos {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} en la casa de subastas.",
  ["This WoW Forever Cooking leveling guide will show you the fastest way to level your Cooking skill from 1 to 300 as cheaply as possible. You will also find every trainer location, how the campfire works in Forever and where to train Cooking past 150 and 225."] = "Esta guía de Cocina para WoW Forever te mostrará la forma más rápida de subir tu habilidad de Cocina de 1 a 300 al menor coste posible. También encontrarás la ubicación de todos los instructores, cómo funciona la hoguera en Forever y dónde aprender Cocina más allá de 150 y 225.",
  ["Cooking doesn't take up one of your two profession slots, so every character can learn it. Most of the recipes below only need the meat or fish that drops while you level, so the guide lists a few recipes for every skill range and you can make the one you have the ingredients for. If you also want to level Fishing but haven't leveled it yet, use my Fishing and Cooking leveling guide instead:"] = "La Cocina no ocupa uno de tus dos huecos de profesión, así que todos los personajes pueden aprenderla. La mayoría de las recetas de abajo solo necesitan la carne o el pescado que consigues mientras subes de nivel, así que la guía da unas cuantas recetas para cada rango de habilidad y puedes hacer aquella para la que tengas ingredientes. Si también quieres subir Pesca pero aún no lo has hecho, usa mejor mi guía de Pesca y Cocina:",
  ["You need level 35 to go past 225, so I split the list in two. Buy this part first."] = "Necesitas nivel 35 para pasar de 225, así que he dividido la lista en dos. Compra primero esta parte.",
  ["The Giant Eggs and the Zesty Clam Meat are for the Artisan Cooking quest."] = "Los Huevos gigantes y la Carne de almeja sabrosa son para la misión de Cocina de Artesano.",
  ["Cooking Trainer Locations"] = "Ubicación de los instructores de Cocina",
  ["Apprentice Cooking has no level requirement, so you can learn it on a fresh character. Every trainer also teaches Journeyman Cooking, so you don't have to find a different trainer at 50."] = "Cocina de Aprendiz no tiene requisito de nivel, así que puedes aprenderla con un personaje recién creado. Todos los instructores también enseñan Cocina de Oficial, así que no tienes que buscar otro instructor en 50.",
  ["Undercity: {n:0:horde:Eunice Burch}"] = "Entrañas: {n:0:horde:Eunice Burch}",
  ["Thunder Bluff: {n:0:horde:Aska Mistrunner}"] = "Cima del Trueno: {n:0:horde:Aska Mistrunner}",
  ["Every starting zone has a Cooking trainer, most of them are inside the inn."] = "Todas las zonas iniciales tienen un instructor de Cocina; la mayoría están dentro de la posada.",
  ["{n:0:horde:Cook Torka} in Razor Hill"] = "{n:0:horde:Cook Torka} en Cerrotajo",
  ["{n:0:horde:Pyall Silentstride} inside the big tent in Bloodhoof Village"] = "{n:0:horde:Pyall Silentstride} dentro de la gran tienda del Poblado Pezuña de Sangre",
  ["{n:0:horde:William Pickman} inside the inn in Brill"] = "{n:0:horde:William Pickman} dentro de la posada de Rémol",
  ["{n:0::Nyalah Brightfire} in Valanaar, {n:0::Zerril Softbreeze} in Shen'dar Village"] = "{n:0::Nyalah Brightfire} en Valanaar, {n:0::Zerril Softbreeze} en la Aldea Shen'dar",
  ["Stormwind City: {n:0:alliance:Stephen Ryback}"] = "Ventormenta: {n:0:alliance:Stephen Ryback}",
  ["Ironforge: {n:0:alliance:Daryl Riknussun}"] = "Forjaz: {n:0:alliance:Daryl Riknussun}",
  ["{n:0:alliance:Tomas} in the kitchen of the inn in Goldshire"] = "{n:0:alliance:Tomas} en la cocina de la posada de Villadorada",
  ["{n:0:alliance:Gremlock Pilsnor} in the Thunderbrew Distillery in Kharanos"] = "{n:0:alliance:Gremlock Pilsnor} en la Destilería Cebatruenos de Kharanos",
  ["{n:0:alliance:Zarrin} in Dolanaar"] = "{n:0:alliance:Zarrin} en Dolanaar",
  ["You can find every Cooking trainer for Horde and Alliance on my WoW Forever Cooking Trainers page."] = "Puedes encontrar todos los instructores de Cocina de la Horda y la Alianza en mi página de instructores de Cocina de WoW Forever.",
  ["Campfire"] = "Hoguera",
  ["You need a campfire to cook. There is often one burning next to the Cooking trainer, so look around before you make your own."] = "Necesitas una hoguera para cocinar. A menudo hay una encendida junto al instructor de Cocina, así que mira alrededor antes de hacer la tuya.",
  ["In Forever the campfire is an item. You learn the {s:1229737:inv_camelot_camping_welcomingcampfire:Basic Campfire Kit} together with Cooking and place the fire from your bags, so you can make a stack of kits in advance. Other players can add their own camp items to your fire, you can read about the whole camping system in my WoW Forever Camping Guide."] = "En Forever la hoguera es un objeto. Aprendes el {s:1229737:inv_camelot_camping_welcomingcampfire:Basic Campfire Kit} junto con Cocina y colocas el fuego desde tus bolsas, así que puedes hacer un montón de kits por adelantado. Otros jugadores pueden añadir sus propios objetos de campamento a tu fuego; puedes leer sobre todo el sistema de acampada en mi guía de acampada de WoW Forever.",
  ["To craft the kits you need {i:4470:inv_tradeskillitem_01:Simple Wood} and a {i:4471:inv_stone_11:Flint and Tinder}. The Flint and Tinder is only for crafting the kits, you don't need it to place the fire. Open your faction below to see who sells them near your trainer:"] = "Para fabricar los kits necesitas {i:4470:inv_tradeskillitem_01:Simple Wood} y un {i:4471:inv_stone_11:Flint and Tinder}. El Pedernal y yesca solo sirve para fabricar los kits, no lo necesitas para colocar el fuego. Despliega tu facción abajo para ver quién los vende cerca de tu instructor:",
  ["{n:0:horde:Xen'to}, next to the trainer"] = "{n:0:horde:Xen'to}, junto al instructor",
  ["{n:0:horde:Ronald Burch}, next to the trainer"] = "{n:0:horde:Ronald Burch}, junto al instructor",
