  ["{n:0::Antelariaa Cloudgaze} in Valanaar {n:0::Zerril Softbreeze}, the Cooking trainer in Shen'dar Village"] = "{n:0::Antelariaa Cloudgaze} en Valanaar {n:0::Zerril Softbreeze}, el instructor de Cocina de la Aldea Shen'dar",
