  ["Recipe Source"] = "Origen de la receta",
  ["Mulgore: {n:0:horde:Harn Longcast} Thunder Bluff: {n:0:horde:Sewa Mistrunner} Tirisfal Glades: {n:0:horde:Martine Tramblay} Undercity: {n:0:horde:Lizbeth Cromwell} Dun Morogh: {n:0:alliance:Gretta Ganter} Elwynn Forest: {n:0:alliance:Tharynn Bouden} Loch Modan: {n:0:alliance:Khara Deepwater} Stormwind City: {n:0:alliance:Catherine Leland} Teldrassil: {n:0:alliance:Nyoma}"] = "Mulgore: {n:0:horde:Harn Longcast} Cima del Trueno: {n:0:horde:Sewa Mistrunner} Claros de Tirisfal: {n:0:horde:Martine Tramblay} Entrañas: {n:0:horde:Lizbeth Cromwell} Dun Morogh: {n:0:alliance:Gretta Ganter} Bosque de Elwynn: {n:0:alliance:Tharynn Bouden} Loch Modan: {n:0:alliance:Khara Deepwater} Ventormenta: {n:0:alliance:Catherine Leland} Teldrassil: {n:0:alliance:Nyoma}",
  ["Durotar: {n:0:horde:Zansoa} Tirisfal Glades: {n:0:horde:Martine Tramblay} Ironforge: {n:0:alliance:Tansy Puddlefizz} Teldrassil: {n:0:alliance:Nessa Shadowsong} Westfall: {n:0:alliance:Kriggon Talsone}"] = "Durotar: {n:0:horde:Zansoa} Claros de Tirisfal: {n:0:horde:Martine Tramblay} Forjaz: {n:0:alliance:Tansy Puddlefizz} Teldrassil: {n:0:alliance:Nessa Shadowsong} Páramos de Poniente: {n:0:alliance:Kriggon Talsone}",
  ["Trainer"] = "Instructor",
  ["(Horde only) Make {s:15935:inv_misc_food_46:Crispy Bat Wing} if you have some {i:12223:inv_misc_pelt_bear_ruin_05:Meaty Bat Wing}. The recipe is sold by {n:0:horde:Abigail Shiel} in Tirisfal Glades."] = "(Solo Horda) Haz {s:15935:inv_misc_food_46:Crispy Bat Wing} si tienes algunas {i:12223:inv_misc_pelt_bear_ruin_05:Meaty Bat Wing}. La receta la vende {n:0:horde:Abigail Shiel} en los Claros de Tirisfal.",
  ["(Horde only) Make {s:6413:inv_misc_food_10:Scorpid Surprise} if you have some {i:5466:spell_nature_nullifypoison:Scorpid Stinger}. The recipe is sold by {n:0:horde:Grimtak} in Durotar."] = "(Solo Horda) Haz {s:6413:inv_misc_food_10:Scorpid Surprise} si tienes algunos {i:5466:spell_nature_nullifypoison:Scorpid Stinger}. La receta la vende {n:0:horde:Grimtak} en Durotar.",
  ["(Alliance only) Make {s:6412:inv_misc_food_68:Kaldorei Spider Kabob} if you have some {i:5465:inv_misc_monsterspidercarapace_01:Small Spider Leg}. The recipe is a reward from {q:4161::Recipe of the Kaldorei}. You can get the quest from {n:0:alliance:Zarrin} in Teldrassil."] = "(Solo Alianza) Haz {s:6412:inv_misc_food_68:Kaldorei Spider Kabob} si tienes algunas {i:5465:inv_misc_monsterspidercarapace_01:Small Spider Leg}. La receta es una recompensa de {q:4161::Recipe of the Kaldorei}. Puedes conseguir la misión con {n:0:alliance:Zarrin} en Teldrassil.",
  ["Journeyman Cooking (50-150)"] = "Cocina de Oficial (50-150)",
  ["{b}Visit your trainer again and learn Journeyman Cooking{/b}, it requires Cooking 50."] = "{b}Vuelve a visitar a tu instructor y aprende Cocina de Oficial{/b}, requiere Cocina 50.",
  ["{b}Make sure to learn Journeyman Cooking before you start the next part{/b}, especially if you go AFK while cooking. Without it you stop getting skill points at 75 and keep cooking for nothing."] = "{b}Asegúrate de aprender Cocina de Oficial antes de empezar la siguiente parte{/b}, sobre todo si te pones AFK mientras cocinas. Sin ella dejas de obtener puntos de habilidad en 75 y sigues cocinando para nada.",
  ["Make around 55 from any of the recipes below. The two fish are usually the cheapest. {s:8607:inv_misc_food_13:Smoked Bear Meat} turns yellow sooner than the rest, so make more of it, or cook it first if you have more than one type of meat."] = "Haz unos 55 de cualquiera de las recetas de abajo. Los dos pescados suelen ser los más baratos. La {s:8607:inv_misc_food_13:Smoked Bear Meat} se vuelve amarilla antes que las demás, así que haz más, o cocínala primero si tienes más de un tipo de carne.",
  ["Mulgore: {n:0:horde:Harn Longcast} Silverpine Forest: {n:0:horde:Killian Sanatha} Thunder Bluff: {n:0:horde:Naal Mistrunner} Undercity: {n:0:horde:Lizbeth Cromwell} Elwynn Forest: {n:0:alliance:Tharynn Bouden} Ironforge: {n:0:alliance:Tansy Puddlefizz} Loch Modan: {n:0:alliance:Khara Deepwater} Teldrassil: {n:0:alliance:Nyoma}"] = "Mulgore: {n:0:horde:Harn Longcast} Bosque de Argénteos: {n:0:horde:Killian Sanatha} Cima del Trueno: {n:0:horde:Naal Mistrunner} Entrañas: {n:0:horde:Lizbeth Cromwell} Bosque de Elwynn: {n:0:alliance:Tharynn Bouden} Forjaz: {n:0:alliance:Tansy Puddlefizz} Loch Modan: {n:0:alliance:Khara Deepwater} Teldrassil: {n:0:alliance:Nyoma}",
  ["Durotar: {n:0:horde:Zansoa} Orgrimmar: {n:0:horde:Shankys} Silverpine Forest: {n:0:horde:Killian Sanatha} Undercity: {n:0:horde:Ronald Burch} Darkshore: {n:0:alliance:Heldan Galesong} Stormwind City: {n:0:alliance:Catherine Leland} Teldrassil: {n:0:alliance:Nessa Shadowsong} Westfall: {n:0:alliance:Kriggon Talsone} Wetlands: {n:0:alliance:Stuart Fleming} The Barrens: {n:0::Kilxx}"] = "Durotar: {n:0:horde:Zansoa} Orgrimmar: {n:0:horde:Shankys} Bosque de Argénteos: {n:0:horde:Killian Sanatha} Entrañas: {n:0:horde:Ronald Burch} Costa Oscura: {n:0:alliance:Heldan Galesong} Ventormenta: {n:0:alliance:Catherine Leland} Teldrassil: {n:0:alliance:Nessa Shadowsong} Páramos de Poniente: {n:0:alliance:Kriggon Talsone} Los Humedales: {n:0:alliance:Stuart Fleming} Los Baldíos: {n:0::Kilxx}",
  ["Silverpine Forest: {n:0:horde:Andrew Hilbert} Loch Modan: {n:0:alliance:Drac Roughcut}"] = "Bosque de Argénteos: {n:0:horde:Andrew Hilbert} Loch Modan: {n:0:alliance:Drac Roughcut}",
  ["55x {i:5469:inv_misc_food_16:Strider Meat} 55x {i:4536:inv_misc_food_19:Shiny Red Apple} (Vendor)"] = "55x {i:5469:inv_misc_food_16:Strider Meat} 55x {i:4536:inv_misc_food_19:Shiny Red Apple} (vendedor)",
  ["The Barrens: {n:0:horde:Tari'qa} (Horde only) Reward from {q:2178::Easy Strider Living} (Alliance only)"] = "Los Baldíos: {n:0:horde:Tari'qa} (solo Horda) Recompensa de {q:2178::Easy Strider Living} (solo Alianza)",
  ["Make around 30-35 from one of these two."] = "Haz unos 30-35 de una de estas dos.",
  ["30x {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} (buy around 55, you will need 25 more at 130-150)"] = "30x {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} (compra unos 55, necesitarás 25 más en 130-150)",
  ["Hillsbrad Foothills: {n:0:horde:Derak Nightfall} Thunder Bluff: {n:0:horde:Naal Mistrunner} Thunder Bluff: {n:0:horde:Sewa Mistrunner} Undercity: {n:0:horde:Ronald Burch} Hillsbrad Foothills: {n:0:alliance:Lindea Rabonne} Stormwind City: {n:0:alliance:Catherine Leland} The Barrens: {n:0::Kilxx}"] = "Laderas de Trabalomas: {n:0:horde:Derak Nightfall} Cima del Trueno: {n:0:horde:Naal Mistrunner} Cima del Trueno: {n:0:horde:Sewa Mistrunner} Entrañas: {n:0:horde:Ronald Burch} Laderas de Trabalomas: {n:0:alliance:Lindea Rabonne} Ventormenta: {n:0:alliance:Catherine Leland} Los Baldíos: {n:0::Kilxx}",
  ["Stormwind City: {n:0:alliance:Kendor Kabonka} (Alliance only)"] = "Ventormenta: {n:0:alliance:Kendor Kabonka} (solo Alianza)",
  ["Make around 20-25 from any of the recipes below."] = "Haz unos 20-25 de cualquiera de las recetas de abajo.",
  ["See above"] = "Ver arriba",
  ["Stormwind City: {n:0:alliance:Kendor Kabonka} (Alliance) Arathi Highlands: {n:0:horde:Keena} (Horde)"] = "Ventormenta: {n:0:alliance:Kendor Kabonka} (Alianza) Tierras Altas de Arathi: {n:0:horde:Keena} (Horda)",
  ["The Barrens: {n:0:horde:Zargh} (Horde only)"] = "Los Baldíos: {n:0:horde:Zargh} (solo Horda)",
  ["Expert Cooking (150-225)"] = "Cocina de Experto (150-225)",
  ["To learn Expert Cooking you need to reach Cooking 125, then buy the {i:16072:inv_misc_book_08:Expert Cookbook} from {n:0:horde:Wulan} (Horde) in Desolace at Shadowprey Village or from {n:0:alliance:Shandrina} (Alliance) in Ashenvale at Mystral Lake."] = "Para aprender Cocina de Experto tienes que llegar a Cocina 125 y después comprar el {i:16072:inv_misc_book_08:Expert Cookbook} a {n:0:horde:Wulan} (Horda), en la Aldea Cazasombras de Desolace, o a {n:0:alliance:Shandrina} (Alianza), en el Lago Mystral de Vallefresno.",
  ["Make around 25-30 from one of these three."] = "Haz unos 25-30 de una de estas tres.",
  ["You can also keep making {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}, but it's green from 160, so you need around 90 of them for these 25 points."] = "También puedes seguir haciendo {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}, pero está en verde desde 160, así que necesitas unos 90 para estos 25 puntos.",
  ["Make around 55 from one of these. The Roast Raptor is usually the cheapest."] = "Haz unos 55 de una de estas. El Raptor asado suele ser el más barato.",
  ["Arathi Highlands: {n:0:alliance:Hammon Karwn} Arathi Highlands: {n:0:horde:Keena} Dustwallow Marsh: {n:0:horde:Ogg'marr}"] = "Tierras Altas de Arathi: {n:0:alliance:Hammon Karwn} Tierras Altas de Arathi: {n:0:horde:Keena} Marjal Revolcafango: {n:0:horde:Ogg'marr}",
  ["Ashenvale: {n:0:horde:Wik'Tar} Orgrimmar: {n:0:horde:Shankys} Stranglethorn Vale: {n:0::Kelsey Yance} Undercity: {n:0:horde:Lizbeth Cromwell} Ironforge: {n:0:alliance:Tansy Puddlefizz} Wetlands: {n:0:alliance:Stuart Fleming} Desolace: {n:0:horde:Wulan} Darkshore: {n:0:alliance:Heldan Galesong} Hillsbrad Foothills: {n:0:alliance:Lindea Rabonne}"] = "Vallefresno: {n:0:horde:Wik'Tar} Orgrimmar: {n:0:horde:Shankys} Vega de Tuercespina: {n:0::Kelsey Yance} Entrañas: {n:0:horde:Lizbeth Cromwell} Forjaz: {n:0:alliance:Tansy Puddlefizz} Los Humedales: {n:0:alliance:Stuart Fleming} Desolace: {n:0:horde:Wulan} Costa Oscura: {n:0:alliance:Heldan Galesong} Laderas de Trabalomas: {n:0:alliance:Lindea Rabonne}",
  ["Reward from a quest in Hillsbrad Foothills NPC: {n:0:horde:Christoph Jeffcoat}, quest: {q:7321::Soothing Turtle Bisque} NPC: {n:0:alliance:Chef Jessen}, quest: {q:555::Soothing Turtle Bisque}"] = "Recompensa de una misión en las Laderas de Trabalomas PNJ: {n:0:horde:Christoph Jeffcoat}, misión: {q:7321::Soothing Turtle Bisque} PNJ: {n:0:alliance:Chef Jessen}, misión: {q:555::Soothing Turtle Bisque}",
  ["Artisan Cooking (225-300)"] = "Cocina de Artesano (225-300)",
  ["Artisan Cooking is the reward of the {q:6610::Clamlette Surprise} quest. You need {b}level 35{/b} and {b}Cooking 225{/b} for it."] = "Cocina de Artesano es la recompensa de la misión {q:6610::Clamlette Surprise}. Necesitas {b}nivel 35{/b} y {b}Cocina 225{/b} para ella.",
  ["Pick up the quest that sends you to Gadgetzan: Horde players take {q:6611::To Gadgetzan You Go!} from {n:0:horde:Zamja} in Orgrimmar, Alliance players take {q:6612::I Know A Guy...} from {n:0:alliance:Daryl Riknussun} in Ironforge."] = "Recoge la misión que te envía a Gadgetzan: los jugadores de la Horda cogen {q:6611::To Gadgetzan You Go!} de {n:0:horde:Zamja} en Orgrimmar, y los de la Alianza cogen {q:6612::I Know A Guy...} de {n:0:alliance:Daryl Riknussun} en Forjaz.",
  ["Collect 12x {i:12207:inv_egg_03:Giant Egg}, 10x {i:7974:inv_misc_food_51:Zesty Clam Meat} and 20x {i:8932:inv_misc_food_37:Alterac Swiss}. {b}Don't go to Gadgetzan before you have all of them{/b}, otherwise you make the trip twice."] = "Reúne 12x {i:12207:inv_egg_03:Giant Egg}, 10x {i:7974:inv_misc_food_51:Zesty Clam Meat} y 20x {i:8932:inv_misc_food_37:Alterac Swiss}. {b}No vayas a Gadgetzan antes de tenerlo todo{/b}, si no harás el viaje dos veces.",
  ["Find {n:0::Dirge Quikcleave} in Gadgetzan, take Clamlette Surprise from him and hand in the three items. He teaches you Artisan Cooking on the spot. While you are in Tanaris, go to Steamwheedle Port and {b}buy {i:13939:inv_scroll_03:Recipe: Spotted Yellowtail} from {n:0::Gikkix}{/b}, you need it in the next step."] = "Busca a {n:0::Dirge Quikcleave} en Gadgetzan, acepta Clamlette Surprise y entrégale los tres objetos. Te enseña Cocina de Artesano en el acto. Mientras estés en Tanaris, ve a Puerto Bonvapor y {b}compra {i:13939:inv_scroll_03:Recipe: Spotted Yellowtail} a {n:0::Gikkix}{/b}, la necesitas en el siguiente paso.",
  ["Make around 140 from one of these two, buy the fish that is cheaper."] = "Haz unos 140 de una de estas dos; compra el pescado que sea más barato.",
  ["Stranglethorn Vale: {n:0::Kelsey Yance}"] = "Vega de Tuercespina: {n:0::Kelsey Yance}",
  ["This WoW Forever First Aid leveling guide will show you the fastest way to level your First Aid skill from 1 to 300. You will also find every trainer location and where to train First Aid past 150 and 225."] = "Esta guía de Primeros auxilios para WoW Forever te mostrará la forma más rápida de subir tu habilidad de Primeros auxilios de 1 a 300. También encontrarás la ubicación de todos los instructores y dónde aprender Primeros auxilios más allá de 150 y 225.",
  ["First Aid does not take up one of your two profession slots, so every character can learn it. Bandages heal you between fights, and in Forever First Aid also makes the healing potions that used to be Alchemy recipes, so it's worth leveling on every character. Below you will find the shopping list, the First Aid trainers by starting zone and capital city, and the cheapest recipes for every skill range."] = "Primeros auxilios no ocupa uno de tus dos huecos de profesión, así que todos los personajes pueden aprenderlo. Las vendas te curan entre combates, y en Forever Primeros auxilios también fabrica las pociones de sanación que antes eran recetas de Alquimia, así que merece la pena subirlo en todos tus personajes. A continuación encontrarás la lista de la compra, los instructores de Primeros auxilios por zona inicial y capital, y las recetas más baratas para cada rango de habilidad.",
  ["First Aid Trainer Locations"] = "Ubicación de los instructores de Primeros auxilios",
  ["Apprentice First Aid has no level requirement, so you can learn it on a fresh character. Every trainer also teaches Journeyman First Aid, so you don't have to find a different trainer at 50."] = "Primeros auxilios de Aprendiz no tiene requisito de nivel, así que puedes aprenderlo con un personaje recién creado. Todos los instructores también enseñan Primeros auxilios de Oficial, así que no tienes que buscar otro instructor en 50.",
  ["Undercity: {n:0:horde:Mary Edras}"] = "Entrañas: {n:0:horde:Mary Edras}",
  ["Thunder Bluff: {n:0:horde:Pand Stonebinder}"] = "Cima del Trueno: {n:0:horde:Pand Stonebinder}",
  ["Every starting zone has a First Aid trainer, most of them are inside the inn."] = "Todas las zonas iniciales tienen un instructor de Primeros auxilios; la mayoría están dentro de la posada.",
  ["{n:0:horde:Rawrk} in the barracks in Razor Hill"] = "{n:0:horde:Rawrk} en el cuartel de Cerrotajo",
  ["{n:0:horde:Vira Younghoof} inside the inn in Bloodhoof Village"] = "{n:0:horde:Vira Younghoof} dentro de la posada del Poblado Pezuña de Sangre",
  ["{n:0:horde:Nurse Neela} inside the inn in Brill"] = "{n:0:horde:Nurse Neela} dentro de la posada de Rémol",
  ["{n:0::Melasa Fairmend} in Valanaar, {n:0::Naleeia Tattermend} in Shen'dar Village"] = "{n:0::Melasa Fairmend} en Valanaar, {n:0::Naleeia Tattermend} en la Aldea Shen'dar",
  ["Stormwind City: {n:0:alliance:Shaina Fuller}"] = "Ventormenta: {n:0:alliance:Shaina Fuller}",
  ["Ironforge: {n:0:alliance:Nissa Firestone}"] = "Forjaz: {n:0:alliance:Nissa Firestone}",
  ["{n:0:alliance:Michelle Belle} upstairs in the inn in Goldshire"] = "{n:0:alliance:Michelle Belle} en el piso de arriba de la posada de Villadorada",
  ["{n:0:alliance:Thamner Pol} in the Thunderbrew Distillery in Kharanos"] = "{n:0:alliance:Thamner Pol} en la Destilería Cebatruenos de Kharanos",
  ["{n:0:alliance:Byancie} in Dolanaar, in the building north of the inn"] = "{n:0:alliance:Byancie} en Dolanaar, en el edificio al norte de la posada",
  ["You can find every First Aid trainer for Horde and Alliance on my WoW Forever First Aid Trainers page."] = "Puedes encontrar todos los instructores de Primeros auxilios de la Horda y la Alianza en mi página de instructores de Primeros auxilios de WoW Forever.",
  ["Apprentice First Aid (1-75)"] = "Primeros auxilios de Aprendiz (1-75)",
  ["If you have Linen Cloth or bought some, pick the {b}Bandages{/b} tab. If you bought herbs, pick the {b}Healing Potions{/b} tab."] = "Si tienes Paño de lino o has comprado, elige la pestaña {b}Vendas{/b}. Si has comprado hierbas, elige la pestaña {b}Pociones de sanación{/b}.",
  ["Bandages"] = "Vendas",
  ["Healing Potions"] = "Pociones de sanación",
  ["86x {s:1244431:inv_potion_49:Minor Healing Potion} - 86 Peacebloom, 86 Mild Spices, 86 Empty Vial"] = "86x {s:1244431:inv_potion_49:Minor Healing Potion} - 86 Flor de paz, 86 Especias suaves, 86 Vial vacío",
  ["{i:2678:inv_misc_food_wheat_02:Mild Spices} are sold by Cooking supply vendors, {i:3371:inv_potion_84:Empty Vial} by Alchemy supply vendors. Open your faction below to see who sells them near your trainer:"] = "Las {i:2678:inv_misc_food_wheat_02:Mild Spices} las venden los vendedores de suministros de cocina, y el {i:3371:inv_potion_84:Empty Vial} los vendedores de suministros de alquimia. Despliega tu facción abajo para ver quién los vende cerca de tu instructor:",
  ["spices: {n:0:horde:Xen'to} vials: {n:0:horde:Kor'geld}"] = "especias: {n:0:horde:Xen'to} viales: {n:0:horde:Kor'geld}",
  ["{n:0:horde:Felicia Doan} in the Trade Quarter"] = "{n:0:horde:Felicia Doan} en el Barrio Comercial",
  ["spices: {n:0:horde:Naal Mistrunner} vials: {n:0:horde:Mani Winterhoof}"] = "especias: {n:0:horde:Naal Mistrunner} viales: {n:0:horde:Mani Winterhoof}",
  ["{n:0:horde:Wunna Darkmane} in Bloodhoof Village"] = "{n:0:horde:Wunna Darkmane} en el Poblado Pezuña de Sangre",
  ["{n:0:horde:Abigail Shiel} in Brill"] = "{n:0:horde:Abigail Shiel} en Rémol",
  ["{n:0::Iallion Featherfall} in Valanaar {n:0::Belandiel Farflight} in Shen'dar Village"] = "{n:0::Iallion Featherfall} en Valanaar {n:0::Belandiel Farflight} en la Aldea Shen'dar",
  ["{n:0:alliance:Edna Mullby} in the Trade District"] = "{n:0:alliance:Edna Mullby} en el Distrito de Mercaderes",
  ["spices: {n:0:alliance:Emrul Riknussun} vials: {n:0:alliance:Gwina Stonebranch}, right next to the trainer"] = "especias: {n:0:alliance:Emrul Riknussun} viales: {n:0:alliance:Gwina Stonebranch}, justo al lado del instructor",
  ["{n:0:alliance:Golorn Frostbeard} in Kharanos"] = "{n:0:alliance:Golorn Frostbeard} en Kharanos",
  ["{n:0:alliance:Narret Shadowgrove} in Dolanaar"] = "{n:0:alliance:Narret Shadowgrove} en Dolanaar",
  ["50x {s:3275:inv_misc_bandage_15:Linen Bandage} - 50 Linen Cloth"] = "50x {s:3275:inv_misc_bandage_15:Linen Bandage} - 50 Paño de lino",
  ["49x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 98 Linen Cloth"] = "49x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 98 Paño de lino",
  ["Journeyman First Aid (75-150)"] = "Primeros auxilios de Oficial (75-150)",
  ["To train past 75, visit your trainer and learn Journeyman First Aid, it requires First Aid 50."] = "Para entrenar más allá de 75, visita a tu instructor y aprende Primeros auxilios de Oficial, requiere Primeros auxilios 50.",
  ["16x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 32 Linen Cloth"] = "16x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 32 Paño de lino",
  ["12x {s:3277:inv_misc_bandage_14:Wool Bandage} - 12 Wool Cloth"] = "12x {s:3277:inv_misc_bandage_14:Wool Bandage} - 12 Paño de lana",
  ["If you have Wool Cloth, pick the {b}Bandages{/b} tab. If you have to buy everything, the {b}Healing Potions{/b} tab is cheaper."] = "Si tienes Paño de lana, elige la pestaña {b}Vendas{/b}. Si tienes que comprarlo todo, la pestaña {b}Pociones de sanación{/b} es más barata.",
  ["43x {s:3277:inv_misc_bandage_14:Wool Bandage} - 43 Wool Cloth"] = "43x {s:3277:inv_misc_bandage_14:Wool Bandage} - 43 Paño de lana",
  ["54x {s:3278:inv_misc_bandage_17:Heavy Wool Bandage} - 108 Wool Cloth"] = "54x {s:3278:inv_misc_bandage_17:Heavy Wool Bandage} - 108 Paño de lana",
  ["For this tab you need 54 {i:2678:inv_misc_food_wheat_02:Mild Spices}, 31 {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}, 31 {i:3372:inv_potion_85:Leaded Vial} and 54 {i:2723:inv_drink_10:Bottle of Dalaran Noir}. Spices are sold by Cooking supply vendors, vials by Alchemy supply vendors and the bottles by barkeeps. The starting zone vendors don't sell Hot Spices or Leaded Vials, so buy them in a capital city. Open your faction below to see who sells them:"] = "Para esta pestaña necesitas 54 {i:2678:inv_misc_food_wheat_02:Mild Spices}, 31 {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}, 31 {i:3372:inv_potion_85:Leaded Vial} y 54 {i:2723:inv_drink_10:Bottle of Dalaran Noir}. Las especias las venden los vendedores de suministros de cocina, los viales los vendedores de suministros de alquimia y las botellas los taberneros. Los vendedores de las zonas iniciales no venden Especias picantes ni Viales emplomados, así que cómpralos en una capital. Despliega tu facción abajo para ver quién los vende:",
  ["{i:2678:inv_misc_food_wheat_02:Mild Spices} and {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}"] = "{i:2678:inv_misc_food_wheat_02:Mild Spices} y {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}",
  ["Orgrimmar: {n:0:horde:Xen'to} Undercity: {n:0:horde:Felicia Doan} Thunder Bluff: {n:0:horde:Naal Mistrunner}"] = "Orgrimmar: {n:0:horde:Xen'to} Entrañas: {n:0:horde:Felicia Doan} Cima del Trueno: {n:0:horde:Naal Mistrunner}",
  ["Orgrimmar: {n:0:horde:Kor'geld} Undercity: {n:0:horde:Felicia Doan} Thunder Bluff: {n:0:horde:Mani Winterhoof}"] = "Orgrimmar: {n:0:horde:Kor'geld} Entrañas: {n:0:horde:Felicia Doan} Cima del Trueno: {n:0:horde:Mani Winterhoof}",
  ["Orgrimmar: {n:5611::Barkeep Morag} Booty Bay: {n:2832::Nixxrax Fillamug}"] = "Orgrimmar: {n:5611::Barkeep Morag} Bahía del Botín: {n:2832::Nixxrax Fillamug}",
  ["Stormwind City: {n:0:alliance:Edna Mullby} Ironforge: {n:0:alliance:Emrul Riknussun} Darnassus: {n:0:alliance:Mythrin'dir}"] = "Ventormenta: {n:0:alliance:Edna Mullby} Forjaz: {n:0:alliance:Emrul Riknussun} Darnassus: {n:0:alliance:Mythrin'dir}",
  ["Stormwind City: {n:0:alliance:Edna Mullby} Ironforge: {n:0:alliance:Gwina Stonebranch} Darnassus: {n:0:alliance:Mythrin'dir}"] = "Ventormenta: {n:0:alliance:Edna Mullby} Forjaz: {n:0:alliance:Gwina Stonebranch} Darnassus: {n:0:alliance:Mythrin'dir}",
  ["Stormwind City: {n:277::Roberto Pupellyverbos} and {n:1328::Elly Langston} Ironforge: {n:5570::Bruuk Barleybeard} Booty Bay: {n:2832::Nixxrax Fillamug}"] = "Ventormenta: {n:277::Roberto Pupellyverbos} y {n:1328::Elly Langston} Forjaz: {n:5570::Bruuk Barleybeard} Bahía del Botín: {n:2832::Nixxrax Fillamug}",
  ["54x {s:1259342:inv_10_alchemy2_quenchingfluid_color2:Simple Poultice} - 54 Spider Ichor, 54 Mild Spices, 54 Bottle of Dalaran Noir"] = "54x {s:1259342:inv_10_alchemy2_quenchingfluid_color2:Simple Poultice} - 54 Icor de araña, 54 Especias suaves, 54 Botella de Dalaran Noir",
  ["31x {s:1244433:inv_potion_51:Healing Potion} - 31 Bruiseweed, 31 Hot Spices, 31 Leaded Vial"] = "31x {s:1244433:inv_potion_51:Healing Potion} - 31 Hierba cardenal, 31 Especias picantes, 31 Vial emplomado",
  ["Expert First Aid (150-225)"] = "Primeros auxilios de Experto (150-225)",
  ["{b}Learn {s:7928:inv_misc_bandage_01:Silk Bandage} from your trainer before you leave{/b}, it's the last recipe the trainers teach."] = "{b}Aprende {s:7928:inv_misc_bandage_01:Silk Bandage} con tu instructor antes de irte{/b}, es la última receta que enseñan los instructores.",
  ["How to learn Expert First Aid"] = "Cómo aprender Primeros auxilios de Experto",
  ["To train past 150, buy the {i:16084:inv_misc_book_08:Expert First Aid - Under Wraps} book from {n:0:alliance:Deneb Walker} (Alliance) in Arathi Highlands or {n:0:horde:Balai Lok'Wein} (Horde) in Dustwallow Marsh. The book has {b}no level requirement{/b}, you only need First Aid 125."] = "Para entrenar más allá de 150, compra el libro {i:16084:inv_misc_book_08:Expert First Aid - Under Wraps} a {n:0:alliance:Deneb Walker} (Alianza) en las Tierras Altas de Arathi o a {n:0:horde:Balai Lok'Wein} (Horda) en el Marjal Revolcafango. El libro {b}no tiene requisito de nivel{/b}, solo necesitas Primeros auxilios 125.",
  ["They also sell the next two manuals, so {b}buy all three{/b} while you are there, or get them from the Auction House if you are low level:"] = "También venden los dos manuales siguientes, así que {b}compra los tres{/b} mientras estés allí, o consíguelos en la casa de subastas si eres de nivel bajo:",
  ["47x {s:7928:inv_misc_bandage_01:Silk Bandage} - 47 Silk Cloth"] = "47x {s:7928:inv_misc_bandage_01:Silk Bandage} - 47 Paño de seda",
  ["47x {s:7929:inv_misc_bandage_02:Heavy Silk Bandage} - 94 Silk Cloth"] = "47x {s:7929:inv_misc_bandage_02:Heavy Silk Bandage} - 94 Paño de seda",
  ["Use the Manual: Heavy Silk Bandage first to learn the recipe."] = "Usa primero el Manual: Venda de seda gruesa para aprender la receta.",
  ["19x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 19 Mageweave Cloth"] = "19x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 19 Paño de tejido mágico",
  ["Use the Manual: Mageweave Bandage first to learn the recipe."] = "Usa primero el Manual: Venda de tejido mágico para aprender la receta.",
  ["Artisan First Aid (225-300)"] = "Primeros auxilios de Artesano (225-300)",
  ["You can train First Aid past 225 by completing the Triage quest. It requires {b}First Aid 225{/b} and {b}level 35{/b}, even though the quest itself is level 45."] = "Puedes entrenar Primeros auxilios más allá de 225 completando la misión Triaje. Requiere {b}Primeros auxilios 225{/b} y {b}nivel 35{/b}, aunque la misión en sí es de nivel 45.",
  ["{b}Bring everything you need in order to skill up to 275{/b}, as you will learn the next two bandages from the same doctor, so bring around 90 Mageweave Cloth and 20 Runecloth with you."] = "{b}Lleva todo lo que necesitas para subir hasta 275{/b}, ya que aprenderás las dos vendas siguientes con el mismo doctor; lleva unos 90 Paño de tejido mágico y 20 Paño rúnico.",
  ["The {q:6622::Triage} quest is given by {n:0:horde:Doctor Gregory Victor} in Arathi Highlands at Hammerfall."] = "La misión {q:6622::Triage} la da {n:0:horde:Doctor Gregory Victor} en Sentencia, Tierras Altas de Arathi.",
  ["Hammerfall, Arathi Highlands"] = "Sentencia, Tierras Altas de Arathi",
  ["The {q:6624::Triage} quest is given by {n:0:alliance:Doctor Gustaf VanHowzen} in Dustwallow Marsh at Theramore."] = "La misión {q:6624::Triage} la da {n:0:alliance:Doctor Gustaf VanHowzen} en Theramore, Marjal Revolcafango.",
  ["Foothold Citadel, Dustwallow Marsh"] = "Ciudadela Garrida, Marjal Revolcafango",
  ["You get a stack of triage bandages and have to save 15 patients, heal the critically injured ones first."] = "Recibes un montón de vendas de triaje y tienes que salvar a 15 pacientes; cura primero a los heridos graves.",
  ["How to complete the Triage quest"] = "Cómo completar la misión Triaje",
  ["Make sure you have about 10 minutes of spare time to do this with no interruptions."] = "Asegúrate de tener unos 10 minutos libres para hacerla sin interrupciones.",
  ["Press CTRL + V to show the health bars over the patients, or turn on \"Show NPC names\" in the interface options."] = "Pulsa CTRL + V para mostrar las barras de salud sobre los pacientes, o activa \"Mostrar nombres de PNJ\" en las opciones de interfaz.",
  ["Zoom the camera out to third person, so you see as much of the room as you can."] = "Aleja la cámara a tercera persona para ver la mayor parte posible de la sala.",
  ["Put the Triage Bandages the doctor gave you on your action bar and use those, not your own bandages."] = "Pon en tu barra de acción las Vendas de triaje que te dio el doctor y usa esas, no tus propias vendas.",
  ["Stand in the middle of the room."] = "Colócate en el centro de la sala.",
  ["When you see another patient, left-click on them to pre-select them, and as soon as your current heal has finished click the bandages in your action bar and the pre-selected one will begin to heal. Saves valuable seconds this way."] = "Cuando veas a otro paciente, haz clic izquierdo sobre él para preseleccionarlo y, en cuanto termine tu cura actual, haz clic en las vendas de tu barra de acción y empezarás a curar al preseleccionado. Así ahorras unos segundos valiosos.",
  ["When you have saved 15 patients, {b}turn in the quest immediately{/b}. I failed it on my druid because I waited, six patients died in the meantime and the quest went from completed to failed."] = "Cuando hayas salvado a 15 pacientes, {b}entrega la misión de inmediato{/b}. Yo la fallé con mi druida porque esperé: seis pacientes murieron mientras tanto y la misión pasó de completada a fallida.",
  ["29x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 29 Mageweave Cloth"] = "29x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 29 Paño de tejido mágico",
  ["30x {s:10841:inv_misc_bandage_20:Heavy Mageweave Bandage} - 60 Mageweave Cloth"] = "30x {s:10841:inv_misc_bandage_20:Heavy Mageweave Bandage} - 60 Paño de tejido mágico",
  ["The doctor teaches it at 240."] = "El doctor la enseña en 240.",
  ["20x {s:18629:inv_misc_bandage_11:Runecloth Bandage} - 20 Runecloth"] = "20x {s:18629:inv_misc_bandage_11:Runecloth Bandage} - 20 Paño rúnico",
  ["The doctor teaches it at 260."] = "El doctor la enseña en 260.",
  ["30x {s:1244436:inv_potion_54:Major Healing Potion} - 30 Golden Sansam, 90 Soothing Spices, 30 Crystal Vial"] = "30x {s:1244436:inv_potion_54:Major Healing Potion} - 30 Sansam dorado, 90 Especias calmantes, 30 Vial de cristal",
  ["The recipe is {i:255729:inv_misc_book_03:Manual: Major Healing Potion}. Check the Auction House first, and buy it there if it costs less than 8g."] = "La receta es {i:255729:inv_misc_book_03:Manual: Major Healing Potion}. Mira primero en la casa de subastas y cómprala allí si cuesta menos de 8 o.",
  ["If it costs more, you can buy it from {n:0::Pexmit} in Mount Hyjal for 8g, but he can be tricky to find."] = "Si cuesta más, puedes comprársela a {n:0::Pexmit} en el Monte Hyjal por 8 o, pero puede ser difícil de encontrar.",
  ["Horde players can also get it from Ortak Lomgok in Elderwild, Mount Hyjal, as the reward for {q:96622::A Rest Without Pain}. You have to complete his {q:96616::Herbs for the Bruised and Weary} quest first."] = "Los jugadores de la Horda también pueden conseguirla de Ortak Lomgok en Elderwild, Monte Hyjal, como recompensa de {q:96622::A Rest Without Pain}. Antes tienes que completar su misión {q:96616::Herbs for the Bruised and Weary}.",
  ["This WoW Forever Fishing leveling guide will show you the fastest way to level Fishing from 1 to 300. Fishing takes a lot of patience, you will have to catch a lot of fish to get from start to finish, but you don't need any materials, only a Fishing Pole and a few lures."] = "Esta guía de Pesca para WoW Forever te mostrará la forma más rápida de subir Pesca de 1 a 300. La Pesca requiere mucha paciencia, tendrás que pescar muchísimos peces para llegar de principio a fin, pero no necesitas materiales, solo una Caña de pescar y algunos cebos.",
  ["Below you will find every Fishing trainer by starting zone and capital city, where to fish for each skill range, and how to learn Expert and Artisan Fishing. If you haven't leveled Cooking yet, use my Fishing and Cooking leveling guide instead, because the fish you catch will level your Cooking at the same time:"] = "A continuación encontrarás todos los instructores de Pesca por zona inicial y capital, dónde pescar en cada rango de habilidad y cómo aprender Pesca de Experto y de Artesano. Si aún no has subido Cocina, usa mejor mi guía de Pesca y Cocina, porque los peces que pesques subirán tu Cocina al mismo tiempo:",
  ["Fishing Trainer Locations"] = "Ubicación de los instructores de Pesca",
  ["Apprentice Fishing has no level requirement in Forever, so you can learn it on a fresh character. Every trainer also teaches Journeyman Fishing, so you don't have to find a different trainer at 50."] = "Pesca de Aprendiz no tiene requisito de nivel en Forever, así que puedes aprenderla con un personaje recién creado. Todos los instructores también enseñan Pesca de Oficial, así que no tienes que buscar otro instructor en 50.",
  ["Undercity: {n:0:horde:Armand Cromwell}"] = "Entrañas: {n:0:horde:Armand Cromwell}",
  ["Thunder Bluff: {n:0:horde:Kah Mistrunner}"] = "Cima del Trueno: {n:0:horde:Kah Mistrunner}",
  ["Every starting zone has a Fishing trainer, and they all stand next to water, so you can start fishing right away."] = "Todas las zonas iniciales tienen un instructor de Pesca, y todos están junto al agua, así que puedes empezar a pescar enseguida.",
  ["{n:0:horde:Lau'Tiki} on the coast at Sen'jin Village"] = "{n:0:horde:Lau'Tiki} en la costa de la Aldea Sen'jin",
  ["{n:0:horde:Uthan Stillwater} at Stonebull Lake, next to Bloodhoof Village"] = "{n:0:horde:Uthan Stillwater} en el Lago Toro de Piedra, junto al Poblado Pezuña de Sangre",
  ["{n:0:horde:Clyde Kellen} at Brightwater Lake, east of Brill"] = "{n:0:horde:Clyde Kellen} en el Lago Aguasclaras, al este de Rémol",
  ["{n:0::Baelann Swiftcurrent} in Valanaar, {n:0::Fenn Fairweather} in Shen'dar Village"] = "{n:0::Baelann Swiftcurrent} en Valanaar, {n:0::Fenn Fairweather} en la Aldea Shen'dar",
  ["Stormwind City: {n:0:alliance:Arnold Leland}"] = "Ventormenta: {n:0:alliance:Arnold Leland}",
  ["Ironforge: {n:0:alliance:Grimnur Stonebrand}"] = "Forjaz: {n:0:alliance:Grimnur Stonebrand}",
  ["{n:0:alliance:Lee Brown} at Crystal Lake, east of Goldshire"] = "{n:0:alliance:Lee Brown} en el Lago de Cristal, al este de Villadorada",
  ["{n:0:alliance:Paxton Ganter} at Iceflow Lake, on the way to Gnomeregan"] = "{n:0:alliance:Paxton Ganter} en el Lago Flujohelado, de camino a Gnomeregan",
  ["{n:0:alliance:Androl Oakhand} in Rut'theran Village, on the shore next to the dock"] = "{n:0:alliance:Androl Oakhand} en la Aldea Rut'theran, en la orilla junto al muelle",
  ["You can find every Fishing trainer for Horde and Alliance on my WoW Forever Fishing Trainers page."] = "Puedes encontrar todos los instructores de Pesca de la Horda y la Alianza en mi página de instructores de Pesca de WoW Forever.",
  ["How to Fish in WoW Forever (1-75)"] = "Cómo pescar en WoW Forever (1-75)",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a few {i:6529:inv_misc_orb_03:Shiny Bauble} from a Fishing Supply or Trade Supply vendor. In the capital cities they stand next to the trainer, for every other zone open your faction below:"] = "Compra una {i:6256:inv_fishingpole_02:Fishing Pole} y algunos {i:6529:inv_misc_orb_03:Shiny Bauble} a un vendedor de suministros de pesca o de suministros de comercio. En las capitales están junto al instructor; para el resto de zonas, despliega tu facción abajo:",
  ["{n:0:horde:Zansoa} in Sen'jin Village"] = "{n:0:horde:Zansoa} en la Aldea Sen'jin",
  ["{n:0:horde:Martine Tramblay} at the Death's Watch Waystation, south-east of Brill"] = "{n:0:horde:Martine Tramblay} en la parada de Death's Watch, al sureste de Rémol",
  ["{n:0::Baelann Swiftcurrent} in Valanaar, {n:0::Belandiel Farflight} in Shen'dar Village"] = "{n:0::Baelann Swiftcurrent} en Valanaar, {n:0::Belandiel Farflight} en la Aldea Shen'dar",
  ["{n:0:horde:Shankys}, next to the Fishing trainer"] = "{n:0:horde:Shankys}, junto al instructor de Pesca",
  ["{n:0:horde:Lizbeth Cromwell}, next to the Fishing trainer"] = "{n:0:horde:Lizbeth Cromwell}, junto al instructor de Pesca",
  ["{n:0:horde:Sewa Mistrunner}, next to the Fishing trainer"] = "{n:0:horde:Sewa Mistrunner}, junto al instructor de Pesca",
  ["{n:0:horde:Wik'Tar} in Zoram'gar Outpost"] = "{n:0:horde:Wik'Tar} en la Avanzada de Zoram'gar",
  ["{n:0:horde:Katoom the Angler}, the Fishing trainer in Revantusk Village"] = "{n:0:horde:Katoom the Angler}, el instructor de Pesca del Poblado Sañadiente",
  ["{n:0:alliance:Gretta Ganter} at Iceflow Lake"] = "{n:0:alliance:Gretta Ganter} en el Lago Flujohelado",
  ["{n:0:alliance:Nessa Shadowsong} in Rut'theran Village"] = "{n:0:alliance:Nessa Shadowsong} en la Aldea Rut'theran",
  ["{n:0:alliance:Catherine Leland}, next to the Fishing trainer"] = "{n:0:alliance:Catherine Leland}, junto al instructor de Pesca",
  ["{n:0:alliance:Tansy Puddlefizz}, next to the Fishing trainer"] = "{n:0:alliance:Tansy Puddlefizz}, junto al instructor de Pesca",
  ["{n:0:alliance:Voloren}, next to the Fishing trainer"] = "{n:0:alliance:Voloren}, junto al instructor de Pesca",
  ["{n:0:alliance:Khara Deepwater} at the Loch"] = "{n:0:alliance:Khara Deepwater} en el Loch",
  ["{n:0:alliance:Stuart Fleming} in Menethil Harbor"] = "{n:0:alliance:Stuart Fleming} en Puerto de Menethil",
  ["Redridge Mountains"] = "Montañas Crestagrana",
  ["{n:0:alliance:Vernon Hale} at Lake Everstill"] = "{n:0:alliance:Vernon Hale} en el Lago Sempiterno",
  ["{n:0:alliance:Lindea Rabonne} in Southshore"] = "{n:0:alliance:Lindea Rabonne} en Costasur",
  ["Open the Professions window."] = "Abre la ventana de Profesiones.",
  ["Click on the {b}hammer button{/b} in the row of buttons on the right side of your screen, {b}NOT the Fishing tab{/b}."] = "Haz clic en el {b}botón del martillo{/b} de la fila de botones del lado derecho de tu pantalla, {b}NO en la pestaña de Pesca{/b}.",
  ["Drag the {s:7731:trade_fishing:Fishing} button from the Fishing box to your action bar."] = "Arrastra el botón {s:7731:trade_fishing:Fishing} del recuadro de Pesca a tu barra de acción.",
  ["Equip your Fishing Pole and apply the {i:6529:inv_misc_orb_03:Shiny Bauble} lure."] = "Equípate la Caña de pescar y ponle el cebo {i:6529:inv_misc_orb_03:Shiny Bauble}.",
  ["Go to any starting zone and look for a lake, pond or river. Stand in front of the water and press the fishing button."] = "Ve a cualquier zona inicial y busca un lago, estanque o río. Colócate frente al agua y pulsa el botón de pesca.",
  ["Mouse over the bobber in the water, and when it splashes, right-click on it."] = "Pasa el ratón sobre el corcho en el agua y, cuando salpique, haz clic derecho sobre él.",
  ["Fish until you reach Fishing 75."] = "Pesca hasta llegar a Pesca 75.",
  ["{b}Starting zones:{/b} Dun Morogh, Durotar, Elwynn Forest, Mulgore, Teldrassil, Tirisfal Glades, Zephras Isle"] = "{b}Zonas iniciales:{/b} Dun Morogh, Durotar, Bosque de Elwynn, Mulgore, Teldrassil, Claros de Tirisfal, Isla Zephras",
  ["{b}Remember, starting zones do not include capital cities!{/b}"] = "{b}¡Recuerda que las zonas iniciales no incluyen las capitales!{/b}",
  ["If you can't find the Fishing button, I show it with pictures in my how to fish in WoW Forever guide."] = "Si no encuentras el botón de Pesca, lo muestro con imágenes en mi guía de cómo pescar en WoW Forever.",
  ["Go back to your trainer and learn Journeyman Fishing. It requires {b}Fishing 50{/b} and {b}level 10{/b}."] = "Vuelve a tu instructor y aprende Pesca de Oficial. Requiere {b}Pesca 50{/b} y {b}nivel 10{/b}.",
  ["Fish until 150 in one of the capital cities:"] = "Pesca hasta 150 en una de las capitales:",
  ["You can fish in any of these zones too: The Barrens, Darkshore, Ironforge, Loch Modan, Silverpine Forest, Westfall."] = "También puedes pescar en cualquiera de estas zonas: Los Baldíos, Costa Oscura, Forjaz, Loch Modan, Bosque de Argénteos, Páramos de Poniente.",
  ["If the fish keep getting away, buy {i:6530:inv_misc_monstertail_03:Nightcrawlers} from a Fishing Supply vendor. They need Fishing 50."] = "Si se te siguen escapando los peces, compra {i:6530:inv_misc_monstertail_03:Nightcrawlers} a un vendedor de suministros de pesca. Requieren Pesca 50.",
  ["You can learn Expert Fishing from the {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} book (requires {b}level 20{/b} and {b}Fishing 125{/b}) sold by {n:0::Old Man Heming} at Booty Bay in Stranglethorn Vale. He is in the middle of Booty Bay at the very bottom, near the fishing sign. You can also buy the book from the Auction House."] = "Puedes aprender Pesca de Experto con el libro {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} (requiere {b}nivel 20{/b} y {b}Pesca 125{/b}), que vende {n:0::Old Man Heming} en Bahía del Botín, Vega de Tuercespina. Está en el centro de Bahía del Botín, abajo del todo, cerca del cartel de pesca. También puedes comprar el libro en la casa de subastas.",
  ["Buy a bunch of {i:6532:inv_misc_gem_variety_02:Bright Baubles} from Old Man Heming before you leave."] = "Compra un buen puñado de {i:6532:inv_misc_gem_variety_02:Bright Baubles} al Viejo Heming antes de irte.",
  ["Go to {b}Dustwallow Marsh{/b}, apply {i:6532:inv_misc_gem_variety_02:Bright Baubles} to your Fishing Pole and fish until 225."] = "Ve al {b}Marjal Revolcafango{/b}, pon {i:6532:inv_misc_gem_variety_02:Bright Baubles} en tu Caña de pescar y pesca hasta 225.",
  ["I recommend fishing in Dustwallow because the Artisan Fishing quest starts there, but you can fish in these zones too: Alterac Mountains, Arathi Highlands, Desolace, Stranglethorn Vale, Swamp of Sorrows, and Thousand Needles."] = "Te recomiendo pescar en el Marjal Revolcafango porque la misión de Pesca de Artesano empieza allí, pero también puedes pescar en estas zonas: Montañas de Alterac, Tierras Altas de Arathi, Desolace, Vega de Tuercespina, Pantano de las Penas y Las Mil Agujas.",
  ["Learning Artisan Fishing"] = "Aprender Pesca de Artesano",
  ["To train Fishing past 225, you must complete the quest {q:6607::Nat Pagle, Angler Extreme} from {n:0::Nat Pagle} in Dustwallow Marsh."] = "Para entrenar Pesca más allá de 225, tienes que completar la misión {q:6607::Nat Pagle, Angler Extreme} de {n:0::Nat Pagle} en el Marjal Revolcafango.",
  ["It requires {b}level 35{/b} and {b}Fishing 225{/b}."] = "Requiere {b}nivel 35{/b} y {b}Pesca 225{/b}.",
  ["To complete the quest, you have to catch 4 quest fish in four different zones:"] = "Para completar la misión, tienes que pescar 4 peces de misión en cuatro zonas distintas:",
  ["Use {i:6532:inv_misc_gem_variety_02:Bright Baubles} when you are fishing in {b}Feralas{/b} to stop the fish from getting away. You don't need any lures in the other zones because your Fishing skill is high enough by then."] = "Usa {i:6532:inv_misc_gem_variety_02:Bright Baubles} cuando pesques en {b}Feralas{/b} para que no se escapen los peces. No necesitas cebos en las otras zonas porque para entonces tu habilidad de Pesca es lo bastante alta.",
  ["Nat Pagle, Angler Extreme quest"] = "Misión Nat Pagle, pescador extremo",
  ["After you completed the quest, fish in any of these zones:"] = "Después de completar la misión, pesca en cualquiera de estas zonas:",
  ["Western Plaguelands"] = "Tierras de la Peste del Oeste",
  ["You will have to use {i:6532:inv_misc_gem_variety_02:Bright Baubles} in these zones to stop the fish from getting away!"] = "¡Tendrás que usar {i:6532:inv_misc_gem_variety_02:Bright Baubles} en estas zonas para que no se escapen los peces!",
  ["This WoW Forever Lockpicking leveling guide will show you the fastest way to level Lockpicking from 1 to 300, with the best place to pick locks for each skill range."] = "Esta guía de Forzar cerraduras para WoW Forever te mostrará la forma más rápida de subir Forzar cerraduras de 1 a 300, con el mejor sitio para forzar cerraduras en cada rango de habilidad.",
  ["Max Lockpicking Skill by Level"] = "Habilidad máxima de Forzar cerraduras por nivel",
  ["{b}Your Lockpicking skill can't go higher than 5 times your level{/b}, so you have to level your character to level Lockpicking. This is the level you need for each part of the guide:"] = "{b}Tu habilidad de Forzar cerraduras no puede superar 5 veces tu nivel{/b}, así que tienes que subir tu personaje para subir Forzar cerraduras. Este es el nivel que necesitas para cada parte de la guía:",
  ["Your level"] = "Tu nivel",
  ["Max Lockpicking skill"] = "Habilidad máxima de Forzar cerraduras",
  ["I originally made this guide with my rogue in Classic. In WoW Forever I'm leveling a hunter, so a friend of mine checks the spots on his rogue, and he confirmed the Horde 1-100 part. Readers told me where they leveled from 150 to 300. I'm assuming the rest is the same as in Classic, but I will confirm it later. If something looks off, send me feedback."] = "Originalmente hice esta guía con mi pícaro en Classic. En WoW Forever estoy subiendo un cazador, así que un amigo comprueba los sitios con su pícaro, y él confirmó la parte 1-100 de la Horda. Los lectores me contaron dónde subieron de 150 a 300. Doy por hecho que el resto es igual que en Classic, pero lo confirmaré más adelante. Si algo no cuadra, envíame tus comentarios.",
  ["Go to the ship near Ratchet in The Barrens. The Buccaneer's Strongboxes there respawn after a few seconds, so even two rogues can skill up there at the same time. {b}They are inside the ship{/b}, at the spot marked on the map below."] = "Ve al barco cerca de Trinquete, en Los Baldíos. Las Cajas fuertes de bucanero de allí reaparecen tras unos segundos, así que incluso dos pícaros pueden subir allí a la vez. {b}Están dentro del barco{/b}, en el punto marcado en el mapa de abajo.",
  ["There is another chest at the bottom of the ship called The Jewel of the Southsea. Don't open it if you are low level, because it spawns a mob that will kill you."] = "Hay otro cofre en el fondo del barco llamado La Joya de los Mares del Sur. No lo abras si eres de nivel bajo, porque hace aparecer un enemigo que te matará.",
  ["There are a bunch of Practice Lockboxes in Redridge Mountains, north of Lake Everstill. They respawn really fast, so you can get to 100 there easily."] = "Hay un montón de Cajas de seguridad de práctica en las Montañas Crestagrana, al norte del Lago Sempiterno. Reaparecen muy rápido, así que puedes llegar a 100 allí fácilmente.",
  ["Go to Zoram Strand in Ashenvale and look for Waterlogged Footlockers along the shore, on land."] = "Ve a la Playa de Zoram, en Vallefresno, y busca Baúles anegados a lo largo de la orilla, en tierra firme.",
  ["Go to Angor Fortress in Badlands. There are two kinds of footlockers there, the Battered Footlockers upstairs need 150, and the Dented Footlockers downstairs need {b}175{/b}."] = "Ve a la Fortaleza de Angor, en las Tierras Inhóspitas. Allí hay dos tipos de baúles: los Baúles maltrechos del piso de arriba necesitan 150, y los Baúles abollados del piso de abajo necesitan {b}175{/b}.",
  ["The footlockers downstairs give a skill point every time until 215, so you can stay here until 225."] = "Los baúles del piso de abajo dan un punto de habilidad cada vez hasta 215, así que puedes quedarte aquí hasta 225.",
  ["Don't bother pickpocketing the mobs there, because their boxes are too low level to give any skill."] = "No te molestes en robar a los enemigos de allí, porque sus cajas son de nivel demasiado bajo para dar habilidad.",
  ["Go to The Slag Pit, the cave in the middle of Searing Gorge, and pick the footlockers there. The ones on the upper part give skill points all the way to 300. They stay yellow until 290 and turn green after that, so the last 10 points take longer."] = "Ve a La Fosa de Escoria, la cueva en el centro de La Garganta de Fuego, y fuerza los baúles de allí. Los de la parte superior dan puntos de habilidad hasta 300. Se mantienen en amarillo hasta 290 y después se vuelven verdes, así que los últimos 10 puntos tardan más.",
  ["{b}There are two kinds of Dented Footlockers in the Slag Pit{/b}, with the same name. The ones on the lower part need 200 and the ones on the upper part need 225. Pick both until the lower ones stop giving skill points, then stay on the upper part."] = "{b}Hay dos tipos de Baúles abollados en La Fosa de Escoria{/b}, con el mismo nombre. Los de la parte inferior necesitan 200 y los de la parte superior 225. Fuerza ambos hasta que los inferiores dejen de dar puntos y después quédate en la parte superior.",
  ["Don't bother pickpocketing the mobs there, because their boxes are too low level to give much skill."] = "No te molestes en robar a los enemigos de allí, porque sus cajas son de nivel demasiado bajo para dar mucha habilidad.",
  ["This WoW Forever camping guide will show you how camping works, how to make a campfire and every camp item and buff of every profession."] = "Esta guía de acampada para WoW Forever te mostrará cómo funciona la acampada, cómo hacer una hoguera y todos los objetos de campamento y beneficios de cada profesión.",
  ["Three night elves sitting at a campfire in Dolanaar, Teldrassil, in WoW Forever"] = "Tres elfos de la noche sentados alrededor de una hoguera en Dolanaar, Teldrassil, en WoW Forever",
  ["How Camping Works"] = "Cómo funciona la acampada",
  ["Someone puts down a campfire, and everyone around it can place a camp item of their own profession. {b}Sit (/sit) next to the fire for a minute{/b}, you will see a buff start counting down. Then you get Camp Benefits, one buff with everything the camp items give, for an hour."] = "Alguien coloca una hoguera y todos los que estén alrededor pueden colocar un objeto de campamento de su propia profesión. {b}Siéntate (/sit) junto al fuego durante un minuto{/b}: verás que empieza a contar un beneficio. Después obtienes Beneficios de campamento, un único beneficio con todo lo que dan los objetos de campamento, durante una hora.",
  ["{b}Each player can place one camp item{/b}, and it puts all your camp items on a 1 hour cooldown. A campfire holds 3, 5 or 10 camp items, depending on how big it is (see How to Make a Campfire below). The buffs are weaker class buffs and don't stack with them."] = "{b}Cada jugador puede colocar un objeto de campamento{/b}, y eso pone todos tus objetos de campamento en un tiempo de reutilización de 1 hora. Una hoguera admite 3, 5 o 10 objetos de campamento, según su tamaño (ver Cómo hacer una hoguera abajo). Los beneficios son versiones más débiles de los beneficios de clase y no se acumulan con ellos.",
  ["The intro quests in the starting zones, The Great Outdoors and Camping 101, are optional, the buffs work without them. The quest givers' fires always give the Camp Tent's rested experience."] = "Las misiones de introducción de las zonas iniciales, The Great Outdoors y Camping 101, son opcionales; los beneficios funcionan sin ellas. Las hogueras de quienes dan esas misiones siempre otorgan la experiencia de descanso de la Tienda de campamento.",
  ["How to Make a Campfire"] = "Cómo hacer una hoguera",
  ["Learn Cooking from any Cooking trainer, the Basic Campfire Kit comes with it at skill 1. {i:4470:inv_tradeskillitem_01:Simple Wood} is sold by the trade and general goods vendors in most towns. Open your Professions window (the hammer and pick button in the menu bar), craft the kit from 1 Simple Wood under Cooking, then use it from your bags to place the campfire."] = "Aprende Cocina con cualquier instructor de Cocina; el Kit de hoguera básica viene incluido con habilidad 1. La {i:4470:inv_tradeskillitem_01:Simple Wood} la venden los vendedores de suministros de comercio y de víveres de la mayoría de los pueblos. Abre tu ventana de Profesiones (el botón del martillo y el pico en la barra de menú), fabrica el kit con 1 Madera simple en Cocina y luego úsalo desde tus bolsas para colocar la hoguera.",
  ["{b}Tip:{/b} you don't have to carry Flint and Tinder and wood around any more, craft a stack of Basic Campfire Kits at home and carry only those, they take one bag slot. You can also hand them to others."] = "{b}Consejo:{/b} ya no tienes que llevar encima Pedernal y yesca y madera; fabrica un montón de Kits de hoguera básica en casa y lleva solo esos, ocupan una casilla de bolsa. También puedes dárselos a otros.",
  ["The bigger campfires hold more camp items, but they need a Blueprint."] = "Las hogueras más grandes admiten más objetos de campamento, pero necesitan un Plano.",
  ["The Expert Campfire Kit needs more Cooking to use than to learn (220 against 200). It's usually the other way around, so maybe it's a bug."] = "El Kit de hoguera de experto necesita más Cocina para usarlo que para aprenderlo (220 frente a 200). Normalmente es al revés, así que quizá sea un error.",
  ["Learn at"] = "Se aprende con",
  ["Use at"] = "Se usa con",
  ["Camp items"] = "Objetos de campamento",
  ["Made from"] = "Se fabrica con",
  ["Comes with Cooking"] = "Viene con Cocina",
  ["{i:273087:inv_garrison_blueprints3:Blueprint: Journeyman Campfire} Dropped by: {n:3673::Lord Serpentis} in Wailing Caverns"] = "{i:273087:inv_garrison_blueprints3:Blueprint: Journeyman Campfire} Lo suelta: {n:3673::Lord Serpentis} en las Cuevas de los Lamentos",
  ["{i:273101:inv_garrison_blueprints3:Blueprint: Expert Campfire} I don't know yet where it drops"] = "{i:273101:inv_garrison_blueprints3:Blueprint: Expert Campfire} Aún no sé dónde se consigue",
  ["Camp Items"] = "Objetos de campamento",
  ["Every profession has three camp items, at skill 20, 140 and 300 (Cooking has two), and each one replaces the one before. The tier 1 item comes from your profession trainer, {b}tier 2 and 3 need a Blueprint{/b}, a recipe item. The tier 2 and 3 blueprints drop from bosses, most of them in dungeons, the tabs show which one. Only the Herbalism one at 300 is not known yet."] = "Cada profesión tiene tres objetos de campamento, con habilidad 20, 140 y 300 (Cocina tiene dos), y cada uno sustituye al anterior. El objeto de nivel 1 lo da el instructor de tu profesión; {b}los de nivel 2 y 3 necesitan un Plano{/b}, un objeto de receta. Los planos de nivel 2 y 3 los sueltan jefes, la mayoría en mazmorras; las pestañas muestran cuál. Solo falta por saber el de Herboristería de 300.",
  ["{b}Every item also gives the buff of the tier 1 item of its profession{/b}, so you never have to choose between a buff and a crafting station. A Master Forge still gives the Strength buff of the Sharpening Wheel. Whether a tier 3 item also gives what the tier 2 item gives (an anvil from a Master Forge) is not confirmed yet. The tabs only list what each tier adds."] = "{b}Cada objeto también da el beneficio del objeto de nivel 1 de su profesión{/b}, así que nunca tienes que elegir entre un beneficio y una estación de fabricación. Una Forja maestra sigue dando el beneficio de Fuerza de la Rueda de afilar. Aún no está confirmado si un objeto de nivel 3 también da lo que da el de nivel 2 (un yunque con una Forja maestra). Las pestañas solo indican lo que añade cada nivel.",
  ["Alchemy"] = "Alquimia",
  ["Blacksmithing"] = "Herrería",
  ["Enchanting"] = "Encantamiento",
  ["Engineering"] = "Ingeniería",
  ["Leatherworking"] = "Peletería",
  ["Tailoring"] = "Sastrería",
  ["Skinning"] = "Desuello",
  ["First Aid"] = "Primeros auxilios",
  ["Camp Item"] = "Objeto de campamento",
  ["What It Does"] = "Qué hace",
  ["Mana regeneration buff, doesn't stack with Blessing of Wisdom"] = "Beneficio de regeneración de maná, no se acumula con Bendición de sabiduría",
  ["Trainer or the Camping 101 quest"] = "Instructor o la misión Camping 101",
  ["A Fermenter, needed for a few Alchemy recipes"] = "Un Fermentador, necesario para algunas recetas de Alquimia",
  ["{i:273085:inv_garrison_blueprints3:Blueprint: Fermenter} Dropped by: {n:250657::Rath'mael} in the Ruins of Lordaeron"] = "{i:273085:inv_garrison_blueprints3:Blueprint: Fermenter} Lo suelta: {n:250657::Rath'mael} en las Ruinas de Lordaeron",
  ["An Alchemy Lab, needed for some Alchemy recipes"] = "Un Laboratorio de alquimia, necesario para algunas recetas de Alquimia",
  ["{i:273112:inv_garrison_blueprints3:Blueprint: Alchemy Laboratory} Dropped by: {n:10508::Ras Frostwhisper} in Scholomance"] = "{i:273112:inv_garrison_blueprints3:Blueprint: Alchemy Laboratory} Lo suelta: {n:10508::Ras Frostwhisper} en Scholomance",
  ["Strength buff, doesn't stack with Strength of Earth Totem"] = "Beneficio de Fuerza, no se acumula con Tótem Fuerza de la tierra",
  ["An anvil"] = "Un yunque",
  ["{i:273086:inv_garrison_blueprints3:Blueprint: Anvil} Dropped by: {n:1763::Gilnid} in The Deadmines"] = "{i:273086:inv_garrison_blueprints3:Blueprint: Anvil} Lo suelta: {n:1763::Gilnid} en las Minas de la Muerte",
  ["A Master Forge, needed for many Blacksmithing recipes"] = "Una Forja maestra, necesaria para muchas recetas de Herrería",
  ["{i:273113:inv_garrison_blueprints3:Blueprint: Master Forge} Dropped by: {n:8983::Golem Lord Argelmach} in Blackrock Depths"] = "{i:273113:inv_garrison_blueprints3:Blueprint: Master Forge} Lo suelta: {n:8983::Golem Lord Argelmach} en las Profundidades de Roca Negra",
  ["Armor, all stats and resistances buff, doesn't stack with Mark of the Wild"] = "Beneficio de armadura, todas las estadísticas y resistencias, no se acumula con Marca de lo Salvaje",
  ["Better disenchanting"] = "Mejor desencantamiento",
  ["{i:273103:inv_garrison_blueprints3:Blueprint: Arcane Salvager} Dropped by: {n:246020::Shade of the Archmage} in the City of Dalaran"] = "{i:273103:inv_garrison_blueprints3:Blueprint: Arcane Salvager} Lo suelta: {n:246020::Shade of the Archmage} en la Ciudad de Dalaran",
  ["An Arcane Forge, needed for some Enchanting recipes"] = "Una Forja Arcana, necesaria para algunas recetas de Encantamiento",
  ["{i:273116:inv_garrison_blueprints3:Blueprint: Arcane Forge} Dropped by: {n:261809::Nanaya} in Kalimdor"] = "{i:273116:inv_garrison_blueprints3:Blueprint: Arcane Forge} Lo suelta: {n:261809::Nanaya} en Kalimdor",
  ["Summons the {n:242498::Reagent Bot}, a vendor with class reagents and profession supplies for everyone at the camp"] = "Invoca al {n:242498::Reagent Bot}, un vendedor con componentes de clase y suministros de profesión para todos los del campamento",
  ["Repairs for everyone at the camp"] = "Reparaciones para todos los del campamento",
  ["{i:273092:inv_garrison_blueprints3:Blueprint: Repair Bot} Dropped by: {n:643::Sneed} in The Deadmines"] = "{i:273092:inv_garrison_blueprints3:Blueprint: Repair Bot} Lo suelta: {n:643::Sneed} en las Minas de la Muerte",
  ["An Anarchist's Workbench, needed for some Engineering recipes"] = "Un Banco de trabajo de anarquista, necesario para algunas recetas de Ingeniería",
  ["{i:273117:inv_garrison_blueprints3:Blueprint: Anarchist's Workbench} Dropped by: {n:11058::Ezra Grimm} in Stratholme"] = "{i:273117:inv_garrison_blueprints3:Blueprint: Anarchist's Workbench} Lo suelta: {n:11058::Ezra Grimm} en Stratholme",
  ["Rested experience up to 5% of a level, once an hour (a debuff blocks it until then)"] = "Experiencia de descanso de hasta el 5% de un nivel, una vez por hora (un perjuicio lo bloquea hasta entonces)",
  ["A Tanning Rack, needed for many Leatherworking recipes"] = "Un Bastidor de curtido, necesario para muchas recetas de Peletería",
  ["{i:273096:inv_garrison_blueprints3:Blueprint: Tanning Rack} Dropped by: {n:3886::Razorclaw the Butcher} in Shadowfang Keep"] = "{i:273096:inv_garrison_blueprints3:Blueprint: Tanning Rack} Lo suelta: {n:3886::Razorclaw the Butcher} en el Castillo de Colmillo Oscuro",
  ["A Sewing Machine, needed for many Leatherworking recipes"] = "Una Máquina de coser, necesaria para muchas recetas de Peletería",
  ["{i:273121:inv_garrison_blueprints3:Blueprint: Sewing Machine} Dropped by: {n:10432::Vectus} in Scholomance"] = "{i:273121:inv_garrison_blueprints3:Blueprint: Sewing Machine} Lo suelta: {n:10432::Vectus} en Scholomance",
  ["Spirit buff for players of your faction, doesn't stack with Divine Spirit. Horde and Alliance each have their own banner"] = "Beneficio de Espíritu para los jugadores de tu facción, no se acumula con Espíritu divino. La Horda y la Alianza tienen cada una su propio estandarte",
  ["A Spinning Wheel, needed for many Tailoring recipes"] = "Una Rueca, necesaria para muchas recetas de Sastrería",
  ["{i:273099:inv_garrison_blueprints3:Blueprint: Spinning Wheel} Dropped by: {n:246017::Unstable Sentinel} in the City of Dalaran"] = "{i:273099:inv_garrison_blueprints3:Blueprint: Spinning Wheel} Lo suelta: {n:246017::Unstable Sentinel} en la Ciudad de Dalaran",
  ["A Loom, needed for many Tailoring recipes"] = "Un Telar, necesario para muchas recetas de Sastrería",
  ["{i:273124:inv_garrison_blueprints3:Blueprint: Loom} Dropped by: {n:10436::Baroness Anastari} in Stratholme"] = "{i:273124:inv_garrison_blueprints3:Blueprint: Loom} Lo suelta: {n:10436::Baroness Anastari} en Stratholme",
  ["Intellect buff, doesn't stack with Arcane Intellect"] = "Beneficio de Intelecto, no se acumula con Intelecto Arcano",
  ["A Greenhouse that grows herbs from seeds you plant"] = "Un Invernadero que cultiva hierbas a partir de las semillas que plantas",
  ["{i:273106:inv_garrison_blueprints3:Blueprint: Greenhouse} Dropped by: {n:260325::Shadetooth} in Excavation Site: Wetlands"] = "{i:273106:inv_garrison_blueprints3:Blueprint: Greenhouse} Lo suelta: {n:260325::Shadetooth} en Excavation Site: Wetlands",
  ["A Seed Hybridizer that multiplies seeds or combines them into rarer ones"] = "Un Hibridador de semillas que multiplica semillas o las combina en otras más raras",
  ["Melee Attack Power buff, doesn't stack with Blessing of Might"] = "Beneficio de poder de ataque cuerpo a cuerpo, no se acumula con Bendición de poderío",
  ["Spawns a common mining node over time, and gives the Lodestone buff too"] = "Genera con el tiempo un yacimiento de minería común, y también da el beneficio Piedra imán",
  ["{i:273097:inv_garrison_blueprints3:Blueprint: Rock Garden} Dropped by: {n:260326::Relic Guardian} in Excavation Site: Wetlands"] = "{i:273097:inv_garrison_blueprints3:Blueprint: Rock Garden} Lo suelta: {n:260326::Relic Guardian} en Excavation Site: Wetlands",
  ["A Molten Foundry, needed for Smelt Heavy Thorium"] = "Una Fundición fundida, necesaria para Fundir torio pesado",
  ["{i:273122:inv_garrison_blueprints3:Blueprint: Molten Foundry} Dropped by: {n:9156::Ambassador Flamelash} in Blackrock Depths"] = "{i:273122:inv_garrison_blueprints3:Blueprint: Molten Foundry} Lo suelta: {n:9156::Ambassador Flamelash} en las Profundidades de Roca Negra",
  ["+2% crit chance, doesn't stack with Moonkin Aura"] = "+2% de probabilidad de crítico, no se acumula con Aura de lechúcico lunar",
  ["A book anyone can read to learn Track Beasts"] = "Un libro que cualquiera puede leer para aprender Rastrear bestias",
  ["{i:273098:inv_garrison_blueprints3:Blueprint: Field Guide} Dropped by: {n:3671::Lady Anacondra} in Wailing Caverns"] = "{i:273098:inv_garrison_blueprints3:Blueprint: Field Guide} Lo suelta: {n:3671::Lady Anacondra} en las Cuevas de los Lamentos",
  ["A workbench with 1 trap"] = "Un banco de trabajo con 1 trampa",
  ["{i:273109:inv_garrison_blueprints3:Blueprint: Trapper's Workbench} Dropped by: {n:10430::The Beast} in Upper Blackrock Spire and {n:3974::Houndmaster Loksey} in Scarlet Monastery"] = "{i:273109:inv_garrison_blueprints3:Blueprint: Trapper's Workbench} Lo sueltan: {n:10430::The Beast} en la Cumbre de Roca Negra superior y {n:3974::Houndmaster Loksey} en el Monasterio Escarlata",
  ["Cooking has no tier 1 camp item, its first one is the campfire (see How to Make a Campfire above)."] = "Cocina no tiene objeto de campamento de nivel 1; su primer objeto es la hoguera (ver Cómo hacer una hoguera arriba).",
  ["Stamina food for everyone at the camp"] = "Comida de Aguante para todos los del campamento",
  ["{i:273102:inv_garrison_blueprints3:Blueprint: Cookie's Feast} Dropped by: {n:645::Cookie} in The Deadmines"] = "{i:273102:inv_garrison_blueprints3:Blueprint: Cookie's Feast} Lo suelta: {n:645::Cookie} en las Minas de la Muerte",
  ["An Iron Oven, needed for the most advanced Cooking recipes"] = "Un Horno de hierro, necesario para las recetas de Cocina más avanzadas",
  ["{i:273115:inv_garrison_blueprints3:Blueprint: Iron Oven} Dropped by: {n:9736::Quartermaster Zigris} in Lower Blackrock Spire"] = "{i:273115:inv_garrison_blueprints3:Blueprint: Iron Oven} Lo suelta: {n:9736::Quartermaster Zigris} en la Cumbre de Roca Negra inferior",
  ["Stamina buff, doesn't stack with Power Word: Fortitude"] = "Beneficio de Aguante, no se acumula con Palabra de poder: entereza",
  ["Healing potions and anti-venom"] = "Pociones de sanación y antídoto",
  ["{i:273105:inv_garrison_blueprints3:Blueprint: Toxin Study} Dropped by: {n:4278::Commander Springvale} in Shadowfang Keep"] = "{i:273105:inv_garrison_blueprints3:Blueprint: Toxin Study} Lo suelta: {n:4278::Commander Springvale} en el Castillo de Colmillo Oscuro",
  ["Healing potions and poultices"] = "Pociones de sanación y cataplasmas",
  ["{i:273118:inv_garrison_blueprints3:Blueprint: Plague Doctor's Laboratory} Dropped by: {n:11261::Doctor Theolen Krastinov} in Scholomance"] = "{i:273118:inv_garrison_blueprints3:Blueprint: Plague Doctor's Laboratory} Lo suelta: {n:11261::Doctor Theolen Krastinov} en Scholomance",
  ["+8% all stats, doesn't stack with Blessing of Kings"] = "+8% a todas las estadísticas, no se acumula con Bendición de reyes",
  ["Uncommon fish for 1 hour and Fishing lures"] = "Peces poco comunes durante 1 hora y cebos de pesca",
  ["{i:273141:inv_garrison_blueprints3:Blueprint: Fishing Rack} Dropped by: {n:6243::Gelihast} in Blackfathom Deeps"] = "{i:273141:inv_garrison_blueprints3:Blueprint: Fishing Rack} Lo suelta: {n:6243::Gelihast} en las Cavernas de Brazanegra",
  ["Rare fish for 1 hour and Fishing lures"] = "Peces raros durante 1 hora y cebos de pesca",
  ["{i:273119:inv_garrison_blueprints3:Blueprint: Fishing Hut} Dropped by: {n:5710::Jammal'an the Prophet} in the Sunken Temple"] = "{i:273119:inv_garrison_blueprints3:Blueprint: Fishing Hut} Lo suelta: {n:5710::Jammal'an the Prophet} en el Templo Sumergido",
  ["Crafting Stations: Tanning Rack, Loom and More"] = "Estaciones de fabricación: Bastidor de curtido, Telar y más",
  ["A lot of recipes in WoW Forever need a crafting station nearby, like a Tanning Rack, a Spinning Wheel or a Loom. {b}I haven't found any of them out in the world{/b}, they only come from camps, so for a lot of higher level crafting you need a camp. The easiest way is a camp that already has the station, anyone at the fire can use it."] = "Muchas recetas de WoW Forever necesitan una estación de fabricación cerca, como un Bastidor de curtido, una Rueca o un Telar. {b}No he encontrado ninguna en el mundo{/b}, solo salen de los campamentos, así que para mucha fabricación de nivel alto necesitas un campamento. Lo más fácil es un campamento que ya tenga la estación; cualquiera junto al fuego puede usarla.",
  ["To place one yourself:"] = "Para colocar una tú mismo:",
  ["Get your profession to the skill in the table below."] = "Sube tu profesión a la habilidad que indica la tabla de abajo.",
  ["Get the station's Blueprint and learn it. The table shows where it drops, if we know it."] = "Consigue el Plano de la estación y apréndelo. La tabla muestra dónde se consigue, si lo sabemos.",
  ["Craft the station, put down a campfire and use the station from your bags next to it."] = "Fabrica la estación, coloca una hoguera y usa la estación desde tus bolsas junto a ella.",
  ["Station"] = "Estación",
  ["Profession"] = "Profesión",
  ["Blueprint"] = "Plano",
  ["Dropped by: {n:250657::Rath'mael} in the Ruins of Lordaeron"] = "Lo suelta: {n:250657::Rath'mael} en las Ruinas de Lordaeron",
  ["Dropped by: {n:10508::Ras Frostwhisper} in Scholomance"] = "Lo suelta: {n:10508::Ras Frostwhisper} en Scholomance",
  ["Dropped by: {n:8983::Golem Lord Argelmach} in Blackrock Depths"] = "Lo suelta: {n:8983::Golem Lord Argelmach} en las Profundidades de Roca Negra",
  ["Dropped by: {n:261809::Nanaya} in Kalimdor"] = "Lo suelta: {n:261809::Nanaya} en Kalimdor",
  ["Dropped by: {n:11058::Ezra Grimm} in Stratholme"] = "Lo suelta: {n:11058::Ezra Grimm} en Stratholme",
  ["Dropped by: {n:3886::Razorclaw the Butcher} in Shadowfang Keep"] = "Lo suelta: {n:3886::Razorclaw the Butcher} en el Castillo de Colmillo Oscuro",
  ["Dropped by: {n:10432::Vectus} in Scholomance"] = "Lo suelta: {n:10432::Vectus} en Scholomance",
  ["Dropped by: {n:246017::Unstable Sentinel} in the City of Dalaran"] = "Lo suelta: {n:246017::Unstable Sentinel} en la Ciudad de Dalaran",
  ["Dropped by: {n:10436::Baroness Anastari} in Stratholme"] = "Lo suelta: {n:10436::Baroness Anastari} en Stratholme",
  ["Dropped by: {n:9156::Ambassador Flamelash} in Blackrock Depths"] = "Lo suelta: {n:9156::Ambassador Flamelash} en las Profundidades de Roca Negra",
  ["Dropped by: {n:9736::Quartermaster Zigris} in Lower Blackrock Spire"] = "Lo suelta: {n:9736::Quartermaster Zigris} en la Cumbre de Roca Negra inferior",
  ["Merchant's Favor is a new currency in WoW Forever. You get it by filling Waylaid Crates with materials and handing them in at your faction's camp, Durotar Supply and Logistics for Horde and the Azeroth Commerce Authority for Alliance, and you spend it on the recipes, mount, pet, tabard and titles the camp vendors sell. Many recipes and the mount, pet and tabard also need reputation with the camp, which you get from Craftsman's Writs. This WoW Forever Merchant's Favor guide will show you where the camps are, how to earn Merchant's Favor and reputation, and every recipe the vendors sell."] = "El Favor del mercader es una nueva moneda de WoW Forever. Lo consigues llenando Cajas extraviadas con materiales y entregándolas en el campamento de tu facción, Suministros y Logística de Durotar para la Horda y la Autoridad Comercial de Azeroth para la Alianza, y lo gastas en las recetas, la montura, la mascota, el tabardo y los títulos que venden los vendedores del campamento. Muchas recetas y la montura, la mascota y el tabardo también requieren reputación con el campamento, que consigues con los Encargos de artesano. Esta guía del Favor del mercader para WoW Forever te mostrará dónde están los campamentos, cómo ganar Favor del mercader y reputación, y todas las recetas que venden los vendedores.",
  ["How It Works"] = "Cómo funciona",
  ["Waylaid Crates drop randomly in the open world and in dungeons, and you can also buy them on the Auction House. You fill a crate with the materials it asks for and hand it in at your camp. For that you get Merchant's Favor, the currency you buy the recipes with."] = "Las Cajas extraviadas caen al azar en el mundo y en las mazmorras, y también puedes comprarlas en la casa de subastas. Llenas una caja con los materiales que pide y la entregas en tu campamento. A cambio obtienes Favor del mercader, la moneda con la que compras las recetas.",
  ["Many recipes also need reputation with the camp. You earn reputation by doing Craftsman's Writs. You get a writ, craft the item it asks for and bring it to the customer."] = "Muchas recetas también requieren reputación con el campamento. Ganas reputación haciendo Encargos de artesano: consigues un encargo, fabricas el objeto que pide y se lo llevas al cliente.",
  ["Where the Camps Are"] = "Dónde están los campamentos",
  ["The Horde camp belongs to Durotar Supply and Logistics, and the Alliance camp belongs to the Azeroth Commerce Authority. Each camp has a recipe vendor for every crafting profession and Cooking, and both camps sell the same recipes (see Recipes by Profession below)."] = "El campamento de la Horda pertenece a Suministros y Logística de Durotar, y el de la Alianza a la Autoridad Comercial de Azeroth. Cada campamento tiene un vendedor de recetas para cada profesión de fabricación y para Cocina, y ambos campamentos venden las mismas recetas (ver Recetas por profesión abajo).",
  ["Three Corners, Redridge Mountains"] = "Tres Caminos, Montañas Crestagrana",
  ["How to Earn Merchant's Favor"] = "Cómo ganar Favor del mercader",
  ["You earn Merchant's Favor by filling Waylaid Crates with materials and bringing them to your camp."] = "Ganas Favor del mercader llenando Cajas extraviadas con materiales y llevándolas a tu campamento.",
  ["Merchant's Favor is per character, so every character has to earn its own."] = "El Favor del mercader es por personaje, así que cada personaje tiene que ganar el suyo.",
  ["Filling a Waylaid Crate"] = "Llenar una Caja extraviada",
  ["{b}Find a Waylaid Crate.{/b} They drop randomly in the open world and in dungeons, and {b}you can also buy them on the Auction House{/b}. Each one asks for one kind of material, for example {i:248684:inv_crate_07:Waylaid Crate: Apprentice Textiles}."] = "{b}Encuentra una Caja extraviada.{/b} Caen al azar en el mundo y en las mazmorras, y {b}también puedes comprarlas en la casa de subastas{/b}. Cada una pide un tipo de material, por ejemplo {i:248684:inv_crate_07:Waylaid Crate: Apprentice Textiles}.",
  ["Right-click it and fill it with one of the bundles it lists, for example 40 Linen Cloth or 20 Light Leather (see Waylaid Crates and Rewards below). You get a Sealed crate, and that one binds to you."] = "Haz clic derecho sobre ella y llénala con uno de los lotes que indica, por ejemplo 40 Paño de lino o 20 Cuero ligero (ver Cajas extraviadas y recompensas abajo). Obtienes una caja sellada, que se liga a ti.",
  ["Bring the Sealed crate to {n:0::Dokimi} at the Horde camp or {n:0::Marcy Baker} at the Alliance camp. You get Merchant's Favor and some silver for it."] = "Lleva la caja sellada a {n:0::Dokimi} en el campamento de la Horda o a {n:0::Marcy Baker} en el de la Alianza. A cambio obtienes Favor del mercader y algo de plata.",
  ["Waylaid Crates and Rewards"] = "Cajas extraviadas y recompensas",
  ["When you fill a Waylaid Crate, it turns into a Sealed crate of the same rank and color. You hand that one in at your camp for the Merchant's Favor in the last column. There are also blue Sealed crates and a Sealed Elite Crate, but I don't know yet what they give."] = "Cuando llenas una Caja extraviada, se convierte en una caja sellada del mismo rango y color. La entregas en tu campamento a cambio del Favor del mercader de la última columna. También hay cajas selladas azules y una Caja de élite sellada, pero aún no sé qué dan.",
  ["The Textiles, Ore, Herbs and Curiosities crates take raw materials, and the Fabrics, Ingots and Parts crates take crafted ones."] = "Las cajas de Textiles, Mineral, Hierbas y Curiosidades piden materiales en bruto, y las de Tejidos, Lingotes y Piezas piden materiales fabricados.",
  ["{b}A crate needs only one of the bundles in its row, not all of them.{/b}"] = "{b}Una caja solo necesita uno de los lotes de su fila, no todos.{/b}",
  ["Apprentice"] = "Aprendiz",
  ["Journeyman"] = "Oficial",
  ["Expert"] = "Experto",
  ["Artisan"] = "Artesano",
  ["You need level 10 to open these."] = "Necesitas nivel 10 para abrirlas.",
  ["You also get {m:2:s:} {m:50:c:} for a white crate and {m:5:s:} for a green one."] = "También obtienes {m:2:s:} {m:50:c:} por una caja blanca y {m:5:s:} por una verde.",
  ["Crate"] = "Caja",
  ["Fill it with one of these"] = "Llénala con uno de estos",
  ["Reward"] = "Recompensa",
  ["You also get {m:5:s:} for a white crate and {m:10:s:} for a green one."] = "También obtienes {m:5:s:} por una caja blanca y {m:10:s:} por una verde.",
  ["You need level 20 to open these."] = "Necesitas nivel 20 para abrirlas.",
  ["You also get {m:7:s:} {m:50:c:} for a white crate and {m:15:s:} for a green one."] = "También obtienes {m:7:s:} {m:50:c:} por una caja blanca y {m:15:s:} por una verde.",
  ["You need level 35 to open these."] = "Necesitas nivel 35 para abrirlas.",
  ["Not known yet"] = "Aún no se sabe",
  ["How to Earn Durotar Supply and Azeroth Commerce Authority Reputation"] = "Cómo ganar reputación con Suministros de Durotar y la Autoridad Comercial de Azeroth",
  ["{b}Handing in Sealed crates doesn't give reputation.{/b} Reputation with Durotar Supply and Logistics or the Azeroth Commerce Authority comes from Craftsman's Writs, crafting orders that you deliver to a customer somewhere in the world. After reaching Friendly, empty Waylaid Crates give reputation too (see Crate Returns after Friendly below)."] = "{b}Entregar cajas selladas no da reputación.{/b} La reputación con Suministros y Logística de Durotar o con la Autoridad Comercial de Azeroth sale de los Encargos de artesano, pedidos de fabricación que entregas a un cliente en algún lugar del mundo. Al llegar a Amistoso, las Cajas extraviadas vacías también dan reputación (ver Devolución de cajas a partir de Amistoso abajo).",
  ["The first time you fill a crate or start a writ, you also get a {i:280180:inv_misc_note_03:Shipping Label}. It starts a quest to your camp, which gives 2,000 reputation and 50 Merchant's Favor."] = "La primera vez que llenas una caja o empiezas un encargo, también obtienes una {i:280180:inv_misc_note_03:Shipping Label}. Inicia una misión hacia tu campamento que da 2000 de reputación y 50 de Favor del mercader.",
  ["Craftsman's Writs"] = "Encargos de artesano",
  ["A Journeyman writ gives 75 reputation, an Expert writ 125 and an Artisan writ 200. {b}You can do each writ once a day{/b}, and as many different writs a day as you want."] = "Un encargo de Oficial da 75 de reputación, uno de Experto 125 y uno de Artesano 200. {b}Puedes hacer cada encargo una vez al día{/b}, y tantos encargos distintos al día como quieras.",
  ["{b}Get a Craftsman's Writ.{/b} In the open world and in dungeons they drop as a {i:262888:inv_misc_note_02:Sealed Journeyman's Writ}, {i:262889:inv_misc_note_02:Sealed Expert's Writ} or {i:262890:inv_misc_note_02:Sealed Artisan's Writ}, an envelope with a random writ of that rank inside. {b}You can also buy writs on the Auction House.{/b}"] = "{b}Consigue un Encargo de artesano.{/b} En el mundo y en las mazmorras caen como {i:262888:inv_misc_note_02:Sealed Journeyman's Writ}, {i:262889:inv_misc_note_02:Sealed Expert's Writ} o {i:262890:inv_misc_note_02:Sealed Artisan's Writ}, un sobre con un encargo aleatorio de ese rango dentro. {b}También puedes comprar encargos en la casa de subastas.{/b}",
  ["Right-click the writ to start its quest, for example {i:264047:inv_misc_note_01:Craftsman's Writ: Lesser Wizard's Robe}."] = "Haz clic derecho en el encargo para empezar su misión, por ejemplo {i:264047:inv_misc_note_01:Craftsman's Writ: Lesser Wizard's Robe}.",
  ["Make the item it asks for or buy it on the Auction House. You don't need the profession yourself."] = "Fabrica el objeto que pide o cómpralo en la casa de subastas. No necesitas tener tú la profesión.",
  ["Bring the item to the customer, your map shows where. The customer takes the item and the writ, and you get the reputation and a Coin Pouch with some silver. Writs don't give Merchant's Favor. {b}On the beta, the customer had no question mark over their head.{/b} I think it was a bug, so if you don't see one, right-click them anyway and the window to hand in the writ opens."] = "Lleva el objeto al cliente; tu mapa muestra dónde está. El cliente se queda con el objeto y el encargo, y tú obtienes la reputación y una Bolsa de monedas con algo de plata. Los encargos no dan Favor del mercader. {b}En la beta, el cliente no tenía un signo de interrogación sobre la cabeza.{/b} Creo que era un error, así que si no lo ves, haz clic derecho sobre él de todas formas y se abrirá la ventana para entregar el encargo.",
  ["Crate Returns after Friendly"] = "Devolución de cajas a partir de Amistoso",
  ["At Friendly, you unlock the Uncertified Scribe in your camp, {n:0:horde:Kurvelk Shadowhoof} at the Horde camp and {n:0:alliance:Dianne Softstep} at the Alliance camp. Both sell the same two items:"] = "Con Amistoso desbloqueas al Escriba no certificado de tu campamento: {n:0:horde:Kurvelk Shadowhoof} en el campamento de la Horda y {n:0:alliance:Dianne Softstep} en el de la Alianza. Ambos venden los mismos dos objetos:",
  ["Reputation"] = "Reputación",
  ["What it does"] = "Qué hace",
  ["Friendly"] = "Amistoso",
  ["Turns an empty Waylaid Crate into 50 reputation, see the steps below."] = "Convierte una Caja extraviada vacía en 50 de reputación, mira los pasos de abajo.",
  ["Honored"] = "Honorable",
  ["Turns a Craftsman's Writ into a random writ of the same rank."] = "Convierte un Encargo de artesano en un encargo aleatorio del mismo rango.",
  ["{b}Buy a {i:262902:inv_10_inscription2_repcontracts_scroll_02_uprez_color5:Forged Delivery Receipt}{/b} from the Uncertified Scribe."] = "{b}Compra un {i:262902:inv_10_inscription2_repcontracts_scroll_02_uprez_color5:Forged Delivery Receipt}{/b} al Escriba no certificado.",
  ["Buy a Waylaid Crate on the Auction House. The receipt seems to work on any of them, so buy the cheapest one."] = "Compra una Caja extraviada en la casa de subastas. El recibo parece funcionar con cualquiera, así que compra la más barata.",
  ["Use the receipt on the crate. You get a {i:262917:inv_crate_01:Notarized Shipping Container}."] = "Usa el recibo sobre la caja. Obtienes un {i:262917:inv_crate_01:Notarized Shipping Container}.",
  ["Hand the container to the same NPC who takes your Sealed crates. You get the reputation and 1 silver."] = "Entrega el contenedor al mismo PNJ que recoge tus cajas selladas. Obtienes la reputación y 1 de plata.",
  ["Recipes by Profession"] = "Recetas por profesión",
  ["Both camps, Durotar Supply and Logistics (Horde) and the Azeroth Commerce Authority (Alliance), sell the same recipes for Merchant's Favor. This is what each profession gets:"] = "Ambos campamentos, Suministros y Logística de Durotar (Horda) y la Autoridad Comercial de Azeroth (Alianza), venden las mismas recetas a cambio de Favor del mercader. Esto es lo que recibe cada profesión:",
  ["{b}Alchemy:{/b} potions and elixirs."] = "{b}Alquimia:{/b} pociones y elixires.",
  ["{b}Blacksmithing:{/b} mail and plate sets for tanks, melee, healers and paladins, and three weapons."] = "{b}Herrería:{/b} conjuntos de malla y placas para tanques, cuerpo a cuerpo, sanadores y paladines, y tres armas.",
  ["{b}Cooking:{/b} six smoothies that give Spirit."] = "{b}Cocina:{/b} seis batidos que dan Espíritu.",
  ["{b}Enchanting:{/b} necklace, weapon and armor enchants, relics (idols, totems and librams) and caster weapons (staves, off-hands and wands)."] = "{b}Encantamiento:{/b} encantamientos de collar, arma y armadura, reliquias (ídolos, tótems y tratados) y armas de lanzador (bastones, sostenidos en la mano izquierda y varitas).",
  ["{b}Engineering:{/b} bombs, thrown weapons, goggles, belts, trinkets and gadgets."] = "{b}Ingeniería:{/b} bombas, armas arrojadizas, gafas, cinturones, abalorios y artilugios.",
  ["{b}Leatherworking:{/b} leather and mail sets for every role, and two armor kits."] = "{b}Peletería:{/b} conjuntos de cuero y malla para cada rol, y dos kits de armadura.",
  ["{b}Tailoring:{/b} cloth sets for every spell school and for healers, and two reagent bags."] = "{b}Sastrería:{/b} conjuntos de tela para cada escuela de hechizos y para sanadores, y dos bolsas de componentes.",
  ["{b}The armor and weapons you craft from these recipes bind on pickup{/b}, so you can only make them for yourself."] = "{b}Las armaduras y armas que fabricas con estas recetas se ligan al recogerlas{/b}, así que solo puedes hacerlas para ti.",
  ["{n:0:horde:Apothecary Durelle} at the Horde camp and {n:0:alliance:Nina Surefire} at the Alliance camp sell 28 Alchemy recipes."] = "{n:0:horde:Apothecary Durelle} en el campamento de la Horda y {n:0:alliance:Nina Surefire} en el de la Alianza venden 28 recetas de Alquimia.",
  ["Potions"] = "Pociones",
  ["Elixirs"] = "Elixires",
  ["Req. Level"] = "Nivel req.",
  ["Effect"] = "Efecto",
  ["Prof. Skill"] = "Hab. prof.",
  ["+31 healing for 30 sec"] = "+31 de sanación durante 30 s",
  ["+16 spell damage for 30 sec"] = "+16 de daño con hechizos durante 30 s",
  ["+28 attack power for 30 sec"] = "+28 de poder de ataque durante 30 s",
  ["282 Fire damage in a cone in front of you, then 35 every 2 sec for 8 sec"] = "282 de daño de Fuego en un cono frente a ti y luego 35 cada 2 s durante 8 s",
  ["Thrown, a cloud for 12 sec that deals 31-36 Nature damage every second to enemies in it"] = "Arrojadiza: una nube durante 12 s que inflige 31-36 de daño de Naturaleza cada segundo a los enemigos que están dentro",
  ["10 doses for 20 sec. When you take Bleed damage, a dose moves to a nearby enemy and deals 325 Nature damage when it ends"] = "10 dosis durante 20 s. Cuando recibes daño de sangrado, una dosis pasa a un enemigo cercano e inflige 325 de daño de Naturaleza al terminar",
  ["+88 healing for 30 sec"] = "+88 de sanación durante 30 s",
  ["+105 spell damage against Elementals for 5 min"] = "+105 de daño con hechizos contra elementales durante 5 min",
