  ["{n:0:horde:Gor'mak} at the Horde camp and {n:0:alliance:Stondry Darkhammer} at the Alliance camp sell 61 Blacksmithing recipes."] = "{n:0:horde:Gor'mak} en el campamento de la Horda y {n:0:alliance:Stondry Darkhammer} en el de la Alianza venden 61 recetas de Herrería.",
